const TERM_BANK = {"terms":[{"term":"新陈代谢","answer":"在生活的生物体和细胞内，存在着无休止的化学反应，一系列的酶促\n反应组成复杂的反应的网络，这些化学反应的总和称为新陈代谢。新\n陈代谢可分为物质代谢和能量代谢。","chapterNo":1,"chapterTitle":"绪论","source":"term_doc","answerStatus":"reference","qid":"TERM-0001"},{"term":"稳态","answer":"生物体内的新陈代谢所需要的物理、化学条件被限制在一个很窄的幅\n度之内，生物体通过许多调节机制来维持内部条件相对稳定，这一特\n性称为稳态。维持内环境稳定的主要调节机制是反馈。","chapterNo":1,"chapterTitle":"绪论","source":"term_doc","answerStatus":"reference","qid":"TERM-0002"},{"term":"应激性","answer":"体外和体外的物理、化学变化都可能对生物体造成影响，生物体能感\n受这些变化，并做出有利于保持其体内稳态、维持生命活动的应答，\n这一行为称为应激性。","chapterNo":1,"chapterTitle":"绪论","source":"term_doc","answerStatus":"reference","qid":"TERM-0003"},{"term":"适应","answer":"指一种生物和它所具有的某些遗传性状，提高了它在特定环境中生存\n和生殖能力。包括结构与功能的适应，结构与功能和环境的适应。","chapterNo":1,"chapterTitle":"绪论","source":"term_doc","answerStatus":"reference","qid":"TERM-0004"},{"term":"发育","answer":"在多细胞生物的生活史中，发生一系列结构与功能的变化，包括器官、\n组织的形态建成、性成熟、衰老等，称为发育。","chapterNo":1,"chapterTitle":"绪论","source":"term_doc","answerStatus":"reference","qid":"TERM-0005"},{"term":"演化","answer":"指种群里的遗传性状在亲代与子代以及子代不同个体之间出现变异\n的现象。根据进化发生的时间尺度的不同，可分为宏演化和微演化。","chapterNo":1,"chapterTitle":"绪论","source":"term_doc","answerStatus":"reference","qid":"TERM-0006"},{"term":"多层次的组构系统","answer":"生物界的复杂性首先表现在它是一个多层次的组构系统。总共有 11\n个组构层次构成一个有序的阶层:生物大分子、细胞器、细胞、组织、\n器官、系统、个体、种群、群落、生态系统和生物圈。","chapterNo":1,"chapterTitle":"绪论","source":"term_doc","answerStatus":"reference","qid":"TERM-0007"},{"term":"双名法","answer":"林奈创立，用两个拉丁名作为物种的学名，第一个名字是属名，第二\n个名字是种名。（命名规则为：属名在前，第一个字母要大写，种名\n在后，均小写。属名和种名后还可加上定名者的姓名。）","chapterNo":1,"chapterTitle":"绪论","source":"term_doc","answerStatus":"reference","qid":"TERM-0008"},{"term":"生物界的多级分类系统","answer":"生物分类系统的构成：生物学将每一个物种分到一个多级的分类系统\n中去，每一级称为一个分类阶元。生物分类系统有 7 个基本阶元：\n界、门、纲、目、科、属、种。当 7 个阶元不够用时，可在某一阶\n元下增加一个阶元，如亚目；也可在某一阶元上增加一个阶元，如超\n科。20 世纪末，在界以上增加一个新的阶元：域。生物分类的历史\n事件有 18 世纪的双名法、1967 年的五界系统、1977 年的三域分类\n学说。","chapterNo":1,"chapterTitle":"绪论","source":"term_doc","answerStatus":"reference","qid":"TERM-0009"},{"term":"五界分类系统","answer":"惠特克根据细胞结构和营养类型将生物分为五界，即原核生物界、原\n生生物界、植物界、动物界和真菌界。","chapterNo":1,"chapterTitle":"绪论","source":"term_doc","answerStatus":"reference","qid":"TERM-0010"},{"term":"三域分类学说","answer":"伍斯和福克斯等根据核糖体亚基的 16SrRNA、18SrRNA 序列分析，把\n生物界分为真细菌域、古细菌域和真核生物域三个域。","chapterNo":1,"chapterTitle":"绪论","source":"term_doc","answerStatus":"reference","qid":"TERM-0011"},{"term":"涌现属性","answer":"从生物大分子到生态系统，各个层次复杂性递增。而且每上升一个层\n次，就会有新的属性出现，称为涌现属性。\n涌现属性是指若干系统或者元件以某种方式组合在一起时出现的新\n的属性，这些属性是每一个个别系统或元件所不具有的。比如，将叶\n绿体中的叶绿素和蛋白质分别抽提出来后，即使在光下也不能进行光\n合作用，但是这些色素和蛋白质等在叶绿体中正确组装和相互作用，\n就能够进行光合作用。","chapterNo":1,"chapterTitle":"绪论","source":"term_doc","answerStatus":"reference","qid":"TERM-0012"},{"term":"必需元素","answer":"生物体生命活动不可或缺的化学元素。包括碳、氢、氧、氮、磷、硫\n等主要元素，以及铁、锌、钙等微量元素，缺乏会导致生理功能障碍。\n缺铁性贫血，佝偻病等。","chapterNo":2,"chapterTitle":"生命的化学基础","source":"term_doc","answerStatus":"reference","qid":"TERM-0013"},{"term":"同位素示踪","answer":"利用放射性（如³²P）或稳定同位素（如¹⁵N）标记分子，追踪其在生\n物体内的代谢路径、分布及转化过程的研究技术。同位素是指质子数\n和电子数都相同，但中子数不同的原子，它们在周期表中的位置相同。","chapterNo":2,"chapterTitle":"生命的化学基础","source":"term_doc","answerStatus":"reference","qid":"TERM-0014"},{"term":"生物大分子（3,4,5一起记，一起写）脂肪只由 C，H，O 组成，不","answer":"是大分子和多聚体。\n生物体内具有重要功能的大型有机分子，不但有生物功能，而且分子\n量较大，其结构较复杂，通常由单体聚合而成。包括蛋白质（氨基酸）\n核酸（核苷酸）多糖（葡萄糖）","chapterNo":2,"chapterTitle":"生命的化学基础","source":"term_doc","answerStatus":"reference","qid":"TERM-0015"},{"term":"多聚体","answer":"由多个相同或不同的单体通过共价键连接形成的大分子。例如淀粉\n（葡萄糖多聚体）、蛋白质（氨基酸多聚体）。","chapterNo":2,"chapterTitle":"生命的化学基础","source":"term_doc","answerStatus":"reference","qid":"TERM-0016"},{"term":"单体","answer":"构成多聚体的基本小分子单元。如葡萄糖是淀粉的单体，氨基酸是蛋\n白质的单体。","chapterNo":2,"chapterTitle":"生命的化学基础","source":"term_doc","answerStatus":"reference","qid":"TERM-0017"},{"term":"糖类","answer":"含醛基或酮基的多羟基化合物，通式多为（CH₂ O)ₙ 。分为单糖（葡\n萄糖，果糖，半乳糖）、双糖（蔗糖，麦芽糖，乳糖）、多糖（纤维\n素，糖原，淀粉等）。","chapterNo":2,"chapterTitle":"生命的化学基础","source":"term_doc","answerStatus":"reference","qid":"TERM-0018"},{"term":"氨基酸","answer":"蛋白质的基本组成单位，含氨基（-NH₂ ）和羧基（-COOH）及可变侧\n链（R 基）。自然界存在20种标准氨基酸。绝大多数蛋白质是由20\n中氨基酸合成。氨基酸的连接方式是脱水缩合。","chapterNo":2,"chapterTitle":"生命的化学基础","source":"term_doc","answerStatus":"reference","qid":"TERM-0019"},{"term":"肽键","answer":"一个氨基酸的α-羧基与另一个氨基酸的α-氨基脱水缩合形成的酰\n胺键（-CO-NH-），是连接氨基酸形成多肽链的共价键。","chapterNo":2,"chapterTitle":"生命的化学基础","source":"term_doc","answerStatus":"reference","qid":"TERM-0020"},{"term":"肽和多肽","answer":"肽：由2-50 个氨基酸通过肽键连接而成的链状化合物。\n多肽：通常指超过50个氨基酸的肽链，是蛋白质的前体。","chapterNo":2,"chapterTitle":"生命的化学基础","source":"term_doc","answerStatus":"reference","qid":"TERM-0021"},{"term":"蛋白质的变性","answer":"蛋白质在物理（高温）或化学（强酸）因素作用下，空间结构破坏导\n致生物活性丧失的过程。一级结构不变，通常不可逆。","chapterNo":2,"chapterTitle":"生命的化学基础","source":"term_doc","answerStatus":"reference","qid":"TERM-0022"},{"term":"核苷酸","answer":"核酸（DNA/RNA）的基本单位，由戊糖（核糖/脱氧核糖）、含氮碱基\n（嘌呤/嘧啶）和磷酸基团组成。","chapterNo":2,"chapterTitle":"生命的化学基础","source":"term_doc","answerStatus":"reference","qid":"TERM-0023"},{"term":"类固醇","answer":"一类脂溶性甾体化合物，具有四环骨架（三个六元环+一个五元环）。\n包括胆固醇（细胞膜成分）、性激素（睾酮、雌激素）、维生素D等，\n参与信号传递和代谢调节。","chapterNo":2,"chapterTitle":"生命的化学基础","source":"term_doc","answerStatus":"reference","qid":"TERM-0024"},{"term":"脱氧核糖核苷酸","answer":"简称DNA,是一种由4种脱氧核糖核苷酸通过磷酸二酯键连接而成的多\n聚体；大多为不分支的线性分子，有些为环状；多数生物靠其携带特\n定顺序的核苷酸组成的遗传信息来控制生物体特定的性状，并在细胞\n增殖过程中将其遗传信息传递给下一代。","chapterNo":2,"chapterTitle":"生命的化学基础","source":"term_doc","answerStatus":"reference","qid":"TERM-0025"},{"term":"核糖核酸","answer":"简称RNA,是由核糖核苷酸通过磷酸二酯键连接而成的一类核酸，已发\n现3种主要形式：核糖体核糖核酸（rRNA）、转运核糖核酸（tRNA）\n和信使核糖核酸 （mRNA）。它们都在蛋白质生物合成中起作用，在\n有些病毒中作为遗传信息的载体。","chapterNo":2,"chapterTitle":"生命的化学基础","source":"term_doc","answerStatus":"reference","qid":"TERM-0026"},{"term":"功能团：","answer":"功能团是指有机化合物中具有化学反应活性的原子团。羟基、羰基、\n羧基和氨基是组成细胞分子最重要的功能团，这四种功能团都具有极\n性，使得生物分子具有亲水性而使化合物在含有大量水分子的细胞中\n稳定存在。许多生物分子中含有两种或更多种功能团，例如糖分子中\n有羟基和醛基或酮基。","chapterNo":2,"chapterTitle":"生命的化学基础","source":"term_doc","answerStatus":"reference","qid":"TERM-0027"},{"term":"脱水缩合：","answer":"由生物单体分子合成生物大分子多聚体往往涉及与功能基团相关的\n脱水反应，即两个单体（或亚基）结合时，由一个单体分子中脱下的\n一个羟基（-OH） 与另一个单体分子中脱下的氢（H）相结合，形成\n一分子水（H2O）。这种脱水缩合反应需要消耗能量来打破相应的化\n学键。","chapterNo":2,"chapterTitle":"生命的化学基础","source":"term_doc","answerStatus":"reference","qid":"TERM-0028"},{"term":"水解反应：","answer":"生物大分子多聚体在水分子的参与下分解为单体的反应，水解反应在\n断开生物大分子间的共价键时可释放出储藏在这些共价键中的能量。\n水解反应是脱水缩合反应的逆反应。","chapterNo":2,"chapterTitle":"生命的化学基础","source":"term_doc","answerStatus":"reference","qid":"TERM-0029"},{"term":"单糖：","answer":"组成多糖的单体是单糖，最常见的单糖是葡萄糖和果糖，葡萄糖是生\n物体内最重要的单糖，分子式为 C6H12O6，果糖的分子式也是 C6H12O6,\n但结构式不同。常见的单糖还有半乳糖(动物特有)、核糖、脱氧核糖。","chapterNo":2,"chapterTitle":"生命的化学基础","source":"term_doc","answerStatus":"reference","qid":"TERM-0030"},{"term":"双糖：","answer":"双糖在细胞中是由两个单糖通过脱水作用合成的糖。常见双糖有麦芽\n糖、蔗糖、乳糖。","chapterNo":2,"chapterTitle":"生命的化学基础","source":"term_doc","answerStatus":"reference","qid":"TERM-0031"},{"term":"多糖：","answer":"多糖是指由数百至数千个单糖通过脱水合成而形成的多聚体。这些多\n聚体有许多种，最重要的 3 种多糖是淀粉、糖原和纤维素。","chapterNo":2,"chapterTitle":"生命的化学基础","source":"term_doc","answerStatus":"reference","qid":"TERM-0032"},{"term":"脂质：","answer":"脂质是指生物体内不溶于水而溶于有机溶剂的各种非极性小分子，主\n要由 C、H 两种元素和非极性的共价键组成，具有疏水性，包括脂肪、\n磷脂、蜡、类固醇等。其中，最常见的是脂肪。","chapterNo":2,"chapterTitle":"生命的化学基础","source":"term_doc","answerStatus":"reference","qid":"TERM-0033"},{"term":"脂肪：","answer":"脂肪是由甘油和 3 个脂肪酸通过脱水缩合而形成的物质，又称甘油\n三酯或三酰甘油，在脂质中最常见。特点有：脂肪中的 3 个酰基一\n般是不同的，来源于 C16、C18 或其他脂肪酸；脂肪中有多个碳氢链，\n可储存大量能量。","chapterNo":2,"chapterTitle":"生命的化学基础","source":"term_doc","answerStatus":"reference","qid":"TERM-0034"},{"term":"脂肪酸：","answer":"脂肪酸是由碳、氢、氧三种元素组成的一类化合物，是脂肪、磷脂、\n糖脂的主要成分。脂肪酸可分为不饱和脂肪酸和饱和脂肪酸两大类。\n不饱和脂肪酸有双键，熔点较低，在常温下是液态，常见于植物油中。\n饱和脂肪酸无双键，熔点较高，在常温下是固态，常见于动物脂肪中。\n膳食中太多会引起动脉粥样硬化。","chapterNo":2,"chapterTitle":"生命的化学基础","source":"term_doc","answerStatus":"reference","qid":"TERM-0035"},{"term":"蛋白质：","answer":"蛋白质是由氨基酸组成的多聚体，是重要的生物大分子。根据蛋白质\n在机体内的功能，可将其分为 7 大类，分别为结构蛋白、收缩蛋白、\n贮藏蛋白、防御蛋白、转运蛋白、信号蛋白和酶。","chapterNo":2,"chapterTitle":"生命的化学基础","source":"term_doc","answerStatus":"reference","qid":"TERM-0036"},{"term":"核酸：","answer":"是由核苷酸聚合而成的生物大分子，包括脱氧核糖核酸（DNA）和核\n糖核酸（RNA）。DNA 可携带遗传信息，是遗传物质；RNA 与遗传信\n息的表达有关，在蛋白质合成中起重要作用。在只含 RNA 的生物中，\nRNA 是遗传物质。","chapterNo":2,"chapterTitle":"生命的化学基础","source":"term_doc","answerStatus":"reference","qid":"TERM-0037"},{"term":"分级分离技术","answer":"细胞的分级分离技术是指将细胞破碎，通过离心将各种细胞器分开，\n从而可以分别研究它们的功能的技术。其中使用的仪器：超速离心机。\n操作步骤：匀浆化（即将细胞/组织打碎），再低温下离心。细胞分\n离分级的产物：根据离心速度的不同，可得到不同的产物。","chapterNo":3,"chapterTitle":"细胞结构与物质交换和信息传递","source":"term_doc","answerStatus":"reference","qid":"TERM-0038"},{"term":"细胞核","answer":"细胞核是真核细胞的控制中心，除哺乳动物成熟的红细胞和维管植物\n筛管细胞外（核在发育过程中消失），一切真核细胞都有完整的细胞\n核；有些细胞有多个核，大多数细胞只有一个核。细胞核包括核被膜、\n染色质、核仁和核基质等部分。","chapterNo":3,"chapterTitle":"细胞结构与物质交换和信息传递","source":"term_doc","answerStatus":"reference","qid":"TERM-0039"},{"term":"核小体","answer":"核小体是染色质的基本结构单位。由4 对组蛋白（H2A、H2B、H3、H4）\n构成的八聚体核心＋核心外围的DNA分子长链＋结合核心部分与DNA\n的组蛋白H1组成。","chapterNo":3,"chapterTitle":"细胞结构与物质交换和信息传递","source":"term_doc","answerStatus":"reference","qid":"TERM-0040"},{"term":"核基质","answer":"核基质是指由含蛋白质的细纤维组成的不溶的网架结构，可作为维持\n细胞核形态的骨架，还可以用来固定许多与细胞核活动有关的装置。","chapterNo":3,"chapterTitle":"细胞结构与物质交换和信息传递","source":"term_doc","answerStatus":"reference","qid":"TERM-0041"},{"term":"内膜系统","answer":"真核细胞中，质膜、核被膜及多种具膜结构的细胞器，直接连在一起\n或通过形成小的囊泡相关联，构成内膜系统。包括核被膜、内质网、\n高尔基体、溶酶体、液泡、质膜等。","chapterNo":3,"chapterTitle":"细胞结构与物质交换和信息传递","source":"term_doc","answerStatus":"reference","qid":"TERM-0042"},{"term":"线粒体","answer":"线粒体是指由内外两层膜包被的囊状细胞器，外膜平整，内膜向内折\n叠形成嵴，内外两层膜之间有腔；囊内充有液态的基质，含有环状\nDNA分子和核糖体；内膜上有许多ATP合酶；线粒体基质中拥有一套\n自身独立的遗传体系与遗传物质。线粒体的特点有：随细胞种类的不\n同，线粒体的数目不等，如分泌细胞中线粒体多；线粒体和细菌的大\n小相似，核糖体相似，且二者的DNA分子均为环状；是一种半自主细\n胞器，其膜蛋白是由其自身游离的核糖体合成的。线粒体是主要的进\n行能量转换的细胞器，可将化学能转变成细胞可直接利用的能量。","chapterNo":3,"chapterTitle":"细胞结构与物质交换和信息传递","source":"term_doc","answerStatus":"reference","qid":"TERM-0043"},{"term":"叶绿体","answer":"叶绿体是进行光合作用的细胞器，植物、藻类均含有叶绿体；叶绿体\n的分布与光照有关：光照下，常分布在细胞的光照一侧；黑暗时，叶\n绿体则移向内部；叶绿体具有双层被膜，叶绿体基质含有类囊体，大\n部分类囊体有规律地叠在一起称为基粒；光合作用的色素和电子传递\n体都位于类囊体膜中，各基粒之间还含基质类囊体，与基粒类囊体相\n连；叶绿体有环状DNA和核糖体，叶绿体中的部分蛋白质是自身合成\n的。","chapterNo":3,"chapterTitle":"细胞结构与物质交换和信息传递","source":"term_doc","answerStatus":"reference","qid":"TERM-0044"},{"term":"微体","answer":"微体是与H2O2 代谢有关的细胞器。微体与溶酶体相同，也是由单层\n膜包被的细胞器，但其所含的酶不是水解酶。微体可分为过氧化物酶\n体和乙醛酸循环体。过氧化物酶体存在于动物、植物细胞中，内有氧\n化酶类；过氧化物酶体中的过氧化氢酶可将细胞中氧化反应产生的对\n细胞有毒的H2O2 分解为H2O和O2，从而起到解毒作用；肝中的过氧\n化物酶体能分解酒精等有毒物质。乙醛酸循环体只存在于植物细胞中，\n是脂肪转化为糖的场所；动物细胞中没有乙醛酸循环体，不能将脂肪\n直接转化为糖。","chapterNo":3,"chapterTitle":"细胞结构与物质交换和信息传递","source":"term_doc","answerStatus":"reference","qid":"TERM-0045"},{"term":"中心粒","answer":"中心粒是一类由微管构成的细胞器，存在于大部分真核细胞(除种子\n植物和某些原生动物细胞)。通常一个细胞中有2个中心粒，彼此垂\n直分布，每个中心粒由9束等距的三联体微管组成，中央没有微管，\n与鞭毛的基体相似；中心粒埋藏在一团特殊的细胞质，即中心体中。","chapterNo":3,"chapterTitle":"细胞结构与物质交换和信息传递","source":"term_doc","answerStatus":"reference","qid":"TERM-0046"},{"term":"微管组织中心","answer":"在活细胞内，能组织微管形成并固定微管的细胞结构称为微管组织中\n心。例如，基体是鞭毛和纤毛的微管组织中心，中心体是纺锤体微管\n的微管组织中心。","chapterNo":3,"chapterTitle":"细胞结构与物质交换和信息传递","source":"term_doc","answerStatus":"reference","qid":"TERM-0047"},{"term":"细胞壁","answer":"细胞壁是植物细胞区别于动物细胞的显著特点之一，位于细胞膜外侧。\n主要功能是保护植物细胞，维持其形状，使其不能吸收过量的水分。\n相邻细胞的细胞壁上有小孔，可与细胞质连通，这种细胞间的联结称\n为胞间连丝，是植物细胞间特有的联结方式。细胞壁的结构有初生壁、\n胞间层、次生壁。","chapterNo":3,"chapterTitle":"细胞结构与物质交换和信息传递","source":"term_doc","answerStatus":"reference","qid":"TERM-0048"},{"term":"胞间层","answer":"胞间层是细胞壁的结构，在细胞分裂产生新细胞时形成，相邻细胞之\n间共有的一层富含黏性的多糖即果胶质薄膜。作用是粘连相邻的细胞。","chapterNo":3,"chapterTitle":"细胞结构与物质交换和信息传递","source":"term_doc","answerStatus":"reference","qid":"TERM-0049"},{"term":"胞外基质","answer":"动物细胞有胞外基质和细胞连接。ECM（胞外基质）的主要成分是细\n胞所分泌的糖蛋白，主要是胶原，在细胞外形成粗壮的丝；胶原纤维\n埋藏在蛋白聚糖所形成的网中，蛋白聚糖中糖极多，可形成极大的复\n合物；纤连蛋白与整合在质膜内的整联蛋白相连，使细胞与ECM相连，\n使ECM能影响细胞的生活。","chapterNo":3,"chapterTitle":"细胞结构与物质交换和信息传递","source":"term_doc","answerStatus":"reference","qid":"TERM-0050"},{"term":"胞间连丝","answer":"植物细胞的细胞连接方式是胞间连丝。相邻细胞的细胞膜伸入细胞壁\n上的孔中，彼此相连，两细胞的光面内质网也彼此相通，连成一片，\n为水分子以及小分子物质提供共质体运输途径。","chapterNo":3,"chapterTitle":"细胞结构与物质交换和信息传递","source":"term_doc","answerStatus":"reference","qid":"TERM-0051"},{"term":"流动镶嵌模型","answer":"流动镶嵌模型是美国科学家辛格和尼科尔森提出的，认为膜是个具有\n流动性的脂质双层，蛋白质以不同的方式插入其中，其主要内容包括：\n膜是流动的、膜是镶嵌的、膜上的糖类为细胞间识别所必需。","chapterNo":3,"chapterTitle":"细胞结构与物质交换和信息传递","source":"term_doc","answerStatus":"reference","qid":"TERM-0052"},{"term":"G蛋白","answer":"G 蛋白是一类能与 GTP 结合的蛋白质，GTP 能水解为 GDP和 Pi；G 蛋\n白松散地连接在质膜的胞质侧，起着开关作用。当G蛋白与GTP结合\n时具有活性；当与GDP结合时，活性丧失。G蛋白受体系统的活动过\n程：信号分子到达靶细胞后，并不进入细胞内部，而是与细胞膜表面\n特异性受体结合，激活与受体偶联的G蛋白，使G 蛋白与GTP相连，\n处于活化状态；活化的G蛋白在质膜上移动并与有关的酶分子结合；\n活化的酶分子引起反应。","chapterNo":3,"chapterTitle":"细胞结构与物质交换和信息传递","source":"term_doc","answerStatus":"reference","qid":"TERM-0053"},{"term":"柠檬酸循环","answer":"①含义：是指存在于大多数动物、植物和微生物中，在有氧的情况下，\n将糖酵解产生的丙酮酸氧化脱羧形成的乙酰CoA,乙酰CoA通过一系\n列氧化脱羧，最终生成C02和H2O,并产生能量的过程。\n②反应场所：反应发生在真核生物细胞的线粒体基质和原核生物细胞\n的细胞质中，\n③意义：是三大营养素分解的最终代谢通路和相互转变的联系枢纽。","chapterNo":4,"chapterTitle":"细胞代谢","source":"term_doc","answerStatus":"reference","qid":"TERM-0054"},{"term":"氧化磷酸化","answer":"①含义：伴随生物氧化将ADP磷酸化形成ATP的过程，称为氧化磷酸\n化。有两种途径，一个是指底物水平磷酸化，一个是电子传递链上的\n氧化磷酸化。很多时候氧化磷酸化是指的后者。\n②机制：目前比较普遍接受的解释是通过化学渗透机制。\n要点是在发生电子传递时释放出的能量使传递链中的蛋白质复合体\n将质子由内膜的内侧通过主动转运到达外侧，造成膜两侧的质子浓度\n梯度，质子不能自由透过内膜，膜两侧的质子梯度就是一种势能，一\n旦质子通过ATP 合酶的质子通道进入膜内，这种势能就被 ATP合酶用\n于合成ATP。\n③反应场所：在真核细胞中,氧化磷酸化作用在线粒体中发生,参与氧\n化及磷酸化的体系以复合体的形式分布在线粒体的内膜上;原核生物\n中,这一作用发生在细胞质膜上。\n④意义：是需氧生物获得能量的主要方式。","chapterNo":4,"chapterTitle":"细胞代谢","source":"term_doc","answerStatus":"reference","qid":"TERM-0055"},{"term":"光合磷酸化","answer":"①定义：光合磷酸化是指光合电子传递链运行过程中产生 ATP的过程。\n②作用机制：电子传递过程中所产生的能量将质子从叶绿体基质中运\n至类囊体腔内，造成一个质子梯度，质子不能自由通过类囊体膜，只\n有通过膜中的ATP合酶，才能顺浓度梯度到达叶绿体基质中，H+流经\nATP合酶会引起ATP的合成。\n③有两种类型:循环式光合磷酸化和非循环式光合磷酸化。前者是在\n光反应的循环式电子传递过程中同时发生磷酸化,产生ATP。后者是\n在光反应的非循环式电子传递过程中同时发生磷酸化,产生ATP。","chapterNo":4,"chapterTitle":"细胞代谢","source":"term_doc","answerStatus":"reference","qid":"TERM-0064"},{"term":"底物水平磷酸化","answer":"①含义：在底物氧化过程中形成的某些高能化合物，通过酶促转移高\n能基团的反应。②机制：酶将一种底物上的磷酸基团转移给ADP。③\n意义：糖酵解和柠檬酸循环都有底物水平磷酸化，产生ATP。","chapterNo":4,"chapterTitle":"细胞代谢","source":"term_doc","answerStatus":"reference","qid":"TERM-0057"},{"term":"电子传递链/呼吸链","answer":"①含义：是一系列电子载体按对电子亲和力逐渐升高的顺序组成的电\n子传递系统,所有组成成分都按顺序分段组成分离的复合物,在复合\n物内各载体成分的物理排列也符合电子流动的方向。②组成：组成电\n子传递链的有3 种蛋白质复合体以及分别多于一个的电子载体。\n③特点：①这些电子载体都是专一的蛋白质，在真核生物细胞中，位\n于线粒体内膜，在原核生物细胞中，位于质膜中。②这些电子传递链\n传递电子是有严格顺序的，前一个载体将电子传给后一个载体，前一\n个载体被氧化，后一个被还原。就是发生了一个氧化还原反应。③最\n后一个被还原的电子载体把电子传递给O2，形成H2O。④是一个放热\n的过程。","chapterNo":4,"chapterTitle":"细胞代谢","source":"term_doc","answerStatus":"reference","qid":"TERM-0058"},{"term":"光合电子传递链","answer":"（1）含义：是一系列电子载体按对电子亲和力逐渐升高的顺序组成\n的电子传递系统,所有组成成分都按顺序分段组成分离的复合物,在\n复合物内各载体成分的物理排列也符合电子流动的方向。\n（2）过程：○1 从光系统II开始，P680 被光激发后产生高能电子，\nP680失去一个电子成为电子受体，氧化剂将H2O氧化成为O2,产生2\n个H+和2 个电子，电子回到P680；○2高能电子被原初电子受体所\n接受，通过一系列电子载体而传递给光系统I的P700,传递过程中有\n一些能量形成了ATP中的能量；○3当电子从光系统II传递到光系\n统I的P700 时，能量水平不足以还原NADP+，这时被光激发的P700\n又产生另一个高能电子，电子传递继续进行，直到将NADP+还原为\nNADPH；\n（3）特点：○1 这些电子载体都是专一的蛋白质，位于类囊体内膜\n上。○2这些电子传递链传递电子是有严格顺序的，电子每从一个载\n体传递到下一个载体时都会丢失一部分能量，一步就是发生了一个氧\n化还原反应。○3是一个吸热的过程。","chapterNo":4,"chapterTitle":"细胞代谢","source":"term_doc","answerStatus":"reference","qid":"TERM-0059"},{"term":"化学渗透假说","answer":"①内涵：解释氧化磷酸化的偶联的机理。\n②要点：在发生电子传递时释放出的能量使传递链中的蛋白质复合体\n将质子由内膜的内侧通过主动转运到达外侧，造成膜两侧的质子浓度\n梯度，质子不能自由透过内膜，膜两侧的质子梯度就是一种势能，一\n旦质子通过ATP 合酶的质子通道进入膜内，这种势能就被 ATP合酶用\n于合成ATP。\n③意义：可以很好地说明线粒体内膜中电子传递、质子动势的建立、\nADP磷酸化的关系。","chapterNo":4,"chapterTitle":"细胞代谢","source":"term_doc","answerStatus":"reference","qid":"TERM-0060"},{"term":"发酵作用","answer":"①发酵是指在无氧条件下，底物脱氢后所产生的[H]未经呼吸链传递\n而直接交某一内源性中间代谢产物接受，以实现底物水平磷酸化产能\n的一类生物氧化反应。\n②乙醇发酵是指无氧条件下，丙酮酸氧化NADH，转变为CO2和乙醇\n（酒精）的过程。\n③乳酸发酵是指某些微生物（乳酸菌）、高等动物葡萄糖酵解产生的\n丙酮酸不经过脱羧，直接接受H+还原成乳酸的过程。","chapterNo":4,"chapterTitle":"细胞代谢","source":"term_doc","answerStatus":"reference","qid":"TERM-0061"},{"term":"光合作用","answer":"是自养生物（植物、藻类和某些细菌）,在可见光的照射下,经过光反\n应和暗反应,利用光合色素,将二氧化碳和水转化为有机物,并释放出\n氧气的生化过程。光合作用的O2来自于H2O，主要步骤包括光反应\n和碳反应，先在叶绿体类囊体膜上发生光反应，需要光，然后在叶绿\n体基质中进行碳反应，必须在光下进行，但不需要光直接参与。光合\n作用是一系列复杂的代谢反应的总和,为异养生物提供食物和氧气，\n是生物界赖以生存的基础,也是地球碳氧循环的重要媒介。","chapterNo":4,"chapterTitle":"细胞代谢","source":"term_doc","answerStatus":"reference","qid":"TERM-0062"},{"term":"光系统","answer":"（1）含义：是由叶绿素、类胡萝卜素、蛋白质和光合作用的原初电\n子受体等分子组成的将光能转化为化学能的功能单位。\n（2）分类和组成：叶绿体中有两类光系统，分别是光系统I 和光系\n统II，叶绿素a也分别分为P680和P700，每一个光系统含有3个部\n分组成:天线色素、作用中心和几种电子载体。\n（3）功能：天线色素将所吸收的光能传递给作用中心的叶绿素a 分\n子,由叶绿素a激发一个电子,并进入光合作用的电子传递链。蛋白质\n是光系统的重要组成部分，与色素分子结合。总之光系统接收光能合\n成ATP和NADPH。","chapterNo":4,"chapterTitle":"细胞代谢","source":"term_doc","answerStatus":"reference","qid":"TERM-0063"},{"term":"卡尔文循环","answer":"①内涵：由卡尔文等人提出的高等植物及各种光合有机体中将\nCO2.ATP和NADPH转变为磷酸丙糖的复杂生化反应的循环过程。是光\n合作用中碳反应的一部分。\n②反应过程：可分为三个阶段:CO2固定，氧化还原反应，RuBP的再\n生。\n③意义：利用光反应产生的能量形成光合产物，不管是对生产者本身\n还是对异养生物，光合产物都是他们能量的唯一来源。","chapterNo":4,"chapterTitle":"细胞代谢","source":"term_doc","answerStatus":"reference","qid":"TERM-0065"},{"term":"景天酸代谢途径（又称 CAM途径）","answer":"（1）含义：在景天科，仙人掌科等科植物中，与有机酸合成日变化\n有关的光合碳代谢途径成为景天酸代谢途径。\n（2）特点：○1CAM 植物常生存于热带及亚热带干旱及半干旱地区。\n○2CAM植物叶片气孔白天关闭,夜间开放。夜间C02能够进入叶中,\n固定C02 产生有机酸，白天有机酸脱羧释放C02，进行C02固定，参\n与卡尔文循环。○3CAM 光合作用的效率不高，利用这种途径的植物\n可以在荒漠中，酷热的条件下存活，但生长很缓慢。\n（3）举例：菠萝、仙人掌、芦荟和许多肉质植物进行这类光合作用。","chapterNo":4,"chapterTitle":"细胞代谢","source":"term_doc","answerStatus":"reference","qid":"TERM-0066"},{"term":"酶","answer":"一种生物催化剂。绝大多数是蛋白质，少数是RNA。能降低反应的活\n化能，加速生物体内化学反应进行，但在反应前后本身并不发生变化。\n酶的化学本质是蛋白质或RNA。按其分子组成的不同，可分为单纯酶\n和结合酶。仅含有蛋白质的称为单纯酶；结合酶则由酶蛋白和辅助因\n子组成。","chapterNo":4,"chapterTitle":"细胞代谢","source":"term_doc","answerStatus":"reference","qid":"TERM-0067"},{"term":"核酶","answer":"少数作为催化剂的RNA。核酶一词用于描述具有催化活性的RNA，即\n化学本质是核糖核酸（RNA）。核酶的作用底物可以是不同的分子，\n有些作用底物就是同一RNA分子中的某些部位。核酶的功能很多，有\n的能够切割RNA，有的能够切割DNA，有些还具有RNA 连接酶、磷酸\n酶等活性。与酶相比，核酶的催化效率较低，是一种较为原始的催化\n酶。","chapterNo":4,"chapterTitle":"细胞代谢","source":"term_doc","answerStatus":"reference","qid":"TERM-0068"},{"term":"竞争性抑制剂","answer":"与酶的正常底物相似的化学物质，它与被抑制的酶的底物通常有结构\n上的相似性，能与底物竞争结合酶的活性部位的化学试剂。另一类竞\n争性抑制剂在化学结构和分子形状上与底物无相似之处，因此并不在\n活性中心与酶结合，而是在活性中心以外的地方结合。然而一旦结合，\n酶的构象就发生变化，从而导致活性中心不能再结合底物。","chapterNo":4,"chapterTitle":"细胞代谢","source":"term_doc","answerStatus":"reference","qid":"TERM-0069"},{"term":"非竞争性抑制剂","answer":"与酶的活性部位以外的部位结合，使酶分子形状发生变化，从而导致\n酶的活性部位不能接纳底物分子的化学试剂。","chapterNo":4,"chapterTitle":"细胞代谢","source":"term_doc","answerStatus":"reference","qid":"TERM-0070"},{"term":"细胞呼吸","answer":"细胞在有氧条件下氧化分解糖类等有机物，最终产生CO2.H2O，并释\n放出能量的过程。细胞呼吸分为发酵、有氧呼吸、无氧呼吸三种（根\n据最终电子受体不同的分类方式）。○1 有氧呼吸以分子氧（O2）为\n最终电子受体，无氧呼吸以无机氧化物为最终电子受体，○2 发酵以\n有机物为最终电子受体。酵母酿酒、同型乳酸发酵、异型乳酸发酵等\n都是属于发酵的范畴，而不是无氧呼吸。○3无氧呼吸指的是，依然\n进行三羧酸循环，还原辅酶依然经过氧化呼吸链，只不过最终的电子\n受体不是氧气，而是无机氧化物。其它过程几乎和有氧呼吸一样，但\n是最后产能较有氧呼吸少。","chapterNo":4,"chapterTitle":"细胞代谢","source":"term_doc","answerStatus":"reference","qid":"TERM-0071"},{"term":"碳反应","answer":"一种发生在叶绿体基质中，不断消耗ATP和NADPH，固定 CO2，并将\n它还原成葡萄糖的途径，也叫做卡尔文循环。这个过程不需要光的直\n接参与，包括CO2的固定、氧化还原反应和RuBP再生三个阶段。","chapterNo":4,"chapterTitle":"细胞代谢","source":"term_doc","answerStatus":"reference","qid":"TERM-0072"},{"term":"光呼吸","answer":"植物在光照下，利用光合作用所产生的O2，将细胞中已有的糖分解\n为CO2和H2O的过程。（光呼吸不会释放能量）绿色植物在光照条件\n下，吸收氧气和释放CO2 的过程。它表明植物在进行光合作用的同时，\n又进行呼吸作用。光呼吸涉及一系列反应，需要叶绿体、过氧化物酶\n体及线粒体三个细胞器的参与。触发条件：当叶片内部氧气浓度相对\n较高而二氧化碳浓度相对较低时（例如高温、干旱、强光导致气孔部\n分关闭），光合作用的关键酶Rubisco（核酮糖-1,5-二磷酸羧化酶/\n加氧酶）会错误地催化其底物RuBP（核酮糖-1,5-二磷酸）与氧气（O\n₂ ）结合，而不是与二氧化碳（CO₂ ）结合。","chapterNo":4,"chapterTitle":"细胞代谢","source":"term_doc","answerStatus":"reference","qid":"TERM-0073"},{"term":"光饱和点","answer":"是指光强对光合作用的影响，在低光强区，光合速率随光强的增强而\n呈比例地增加；当超过一定光强，光合速率增加就会转慢；当达到某\n一光强时，光合速率就不再增加，而呈现光饱和现象。开始达到光合\n速率最大值时的光强称为光饱和点。","chapterNo":4,"chapterTitle":"细胞代谢","source":"term_doc","answerStatus":"reference","qid":"TERM-0074"},{"term":"细胞代谢","answer":"细胞代谢是细胞内所发生的用于维持生命的一系列有序的化学反应\n的总称。这些反应进程使得生物体能够生长和繁殖、保持它们的结构\n以及对外界环境做出反应。代谢通常被分为两类:分解代谢可以对大\n的分子进行分解以获得能量（如细胞呼吸）;合成代谢则可以利用能\n量来合成细胞中的各个组分，如蛋白质和核酸等。","chapterNo":4,"chapterTitle":"细胞代谢","source":"term_doc","answerStatus":"reference","qid":"TERM-0075"},{"term":"同化作用","answer":"生物体将简单小分子合成复杂大分子并消耗能量的过程称为同化作\n用或合成代谢。","chapterNo":4,"chapterTitle":"细胞代谢","source":"term_doc","answerStatus":"reference","qid":"TERM-0076"},{"term":"异化作用","answer":"生物体将复杂化合物分解为简单小分子并放出能量的反应，称为异化\n作用或分解代谢。","chapterNo":4,"chapterTitle":"细胞代谢","source":"term_doc","answerStatus":"reference","qid":"TERM-0077"},{"term":"ATP循环","answer":"是指通过ATP的水解和合成，而使放能反应所释放的能量贮入ATP，\nATP所贮能量供吸能反应消耗能量时使用的过程。因为ATP是细胞中\n普遍应用的能量载体，所以常称之为细胞的能量通货。","chapterNo":4,"chapterTitle":"细胞代谢","source":"term_doc","answerStatus":"reference","qid":"TERM-0078"},{"term":"辅因子","answer":"辅因子也称为非蛋白成分。许多酶需要辅因子的参与才能正常发挥作\n用。辅因子可能是无机物，如钾、镁离子，也可能是有机物，有机的\n辅因子称为辅酶，许多辅酶来自维生素或就是维生素。","chapterNo":4,"chapterTitle":"细胞代谢","source":"term_doc","answerStatus":"reference","qid":"TERM-0079"},{"term":"辅酶","answer":"许多酶需要辅因子的参与才能正常发挥作用。有机的辅因子称为辅酶，\n许多辅酶来自维生素或就是维生素。","chapterNo":4,"chapterTitle":"细胞代谢","source":"term_doc","answerStatus":"reference","qid":"TERM-0080"},{"term":"渗透","answer":"渗逶是水的被动转运。水分子从低浓度一侧穿过膜而进入高浓度的一\n侧就是渗透。溶液中溶质的总浓度决定渗透方向，渗逶方向与溶质的\n种类无关。只要半透膜的两侧不是等渗溶液，水分子总体一定会向一\n侧移动，直至两侧浓度相等为止。30.转运蛋白膜转运蛋白是指细胞\n膜上具有物质转运能力的蛋白质。主要包括通道蛋白和载体蛋白。通\n道蛋白为某种分子或离子提供一个亲水的通道，使它们极易通过膜。\n例如水通道蛋白、NA＋通道蛋白、K＋通道蛋白。载体蛋白在与被动\n转运的离子结合后会发生细微的形状上的变化，将离子从膜的一侧运\n到另一侧。","chapterNo":4,"chapterTitle":"细胞代谢","source":"term_doc","answerStatus":"reference","qid":"TERM-0081"},{"term":"协同转运","answer":"协同转运又称偶联运输，是指一种物质以被动运输方式进行运输所产\n生的势能推动另一种物质进行主动运输的过程。它是一类由Na＋-k+\n泵(或H+泵)与载体蛋白协同作用，靠间接消耗 ATP所完成的主动运\n输方式。例如植物细胞利用质子泵所产生的H＋浓度梯度来推动糖类、\n氨基酸等养分被吸收进入细胞的活动。","chapterNo":4,"chapterTitle":"细胞代谢","source":"term_doc","answerStatus":"reference","qid":"TERM-0082"},{"term":"ATP合酶","answer":"ATP合酶是指催化氧化磷酸化反应的酶，即ATP酶(ATPase)，它既催\n化ATP的水解反应，又催化ATP 的合成反应，广泛分布于线粒体内膜，\n叶绿体类囊体，异养菌和光合菌的质膜上。ATP（三磷酸腺苷）：ATP\n分子由一个戊糖、一个含氮碱基和三个磷酸基团组成，其中一个磷酸\n基团连接在糖分子上，另外两个以高能磷酸键相继连接，高能磷酸键\n用“~”表示。ATP水解时，高能磷酸键断裂释放大量的自由能，供\n生命活动所需。ATP在细胞中可以与ADP相互转化，是细胞中的“能\n量通货”。生成ATP的方式有：氧化磷酸化、底物水平磷酸化、光合\n磷酸化","chapterNo":4,"chapterTitle":"细胞代谢","source":"term_doc","answerStatus":"reference","qid":"TERM-0083"},{"term":"二分分裂","answer":"二分分裂是原核细胞的细胞增殖方式。细菌拟核由环状DNA和相关的\n蛋白质组成。在分裂中的细菌细胞内两条DNA是主动分开的，一旦\nDNA开始复制，复制起点马上分开。细胞在复制过程中长大，复制完\n成时，细胞长大一倍，然后质膜向内凹陷，将细胞一分为二，每个子\n细胞中各有一个基因组。","chapterNo":5,"chapterTitle":"细胞分裂与细胞分化","source":"term_doc","answerStatus":"reference","qid":"TERM-0084"},{"term":"检控点","answer":"是细胞周期中的关键点，它发出的信号停止前一阶段的事件而启动后\n一阶段的事件。细胞周期的检控点存在于G1期、G2期和M期。","chapterNo":5,"chapterTitle":"细胞分裂与细胞分化","source":"term_doc","answerStatus":"reference","qid":"TERM-0085"},{"term":"生长因子","answer":"生长因子是某些体细胞分泌的蛋白质，它促进其他细胞的分裂，如血\n小板衍生的生长因子(PDGF)。","chapterNo":5,"chapterTitle":"细胞分裂与细胞分化","source":"term_doc","answerStatus":"reference","qid":"TERM-0086"},{"term":"贴壁依赖性","answer":"许多动物细胞必须贴在某种基底上，如培养器皿的内壁上或组织的胞\n外基质上才能正常分裂。贴壁和锚定的信号是通过一种途径传递到细\n胞周期控制系统的，而癌细胞既无密度制约的抑制，也无贴壁依赖性。","chapterNo":5,"chapterTitle":"细胞分裂与细胞分化","source":"term_doc","answerStatus":"reference","qid":"TERM-0087"},{"term":"染色体带型","answer":"是指染色体经过特殊处理，并用特定染料染色后，呈现的不同深浅颜\n色的条纹。产生的染色带分布在整个染色体的长度上，如Q 带、G带\n和R带。","chapterNo":5,"chapterTitle":"细胞分裂与细胞分化","source":"term_doc","answerStatus":"reference","qid":"TERM-0088"},{"term":"同源染色体","answer":"指在二倍体生物细胞中，形态、结构基本相同，一条来自父方、一条\n来自母方的染色体。","chapterNo":5,"chapterTitle":"细胞分裂与细胞分化","source":"term_doc","answerStatus":"reference","qid":"TERM-0089"},{"term":"细线期是减数第一次分裂前期第1 个亚时期。已复制的染色体由两","answer":"条姐妹染色单体组成，由于两条染色单体互相并列呈细而长的线状，\n因此看不出染色体的双重性。","chapterNo":5,"chapterTitle":"细胞分裂与细胞分化","source":"term_doc","answerStatus":"reference","qid":"TERM-0090"},{"term":"偶线期","answer":"是减数第一次分裂前期第2 个亚时期。这个时期的特点有：同源染色\n体的两个成员逐渐变粗并侧向靠拢，这种现象称为联会；出现联会复\n合体。","chapterNo":5,"chapterTitle":"细胞分裂与细胞分化","source":"term_doc","answerStatus":"reference","qid":"TERM-0091"},{"term":"粗线期","answer":"是减数第一次分裂前期第3 个亚时期。这个时期的特点有:染色体进\n一步缩短变粗，同源染色体配对完毕，配对完毕的染色体为二价体或\n四分体；在这个时期，非姐妹染色单体间来可能发生交换，产生基因\n重组。","chapterNo":5,"chapterTitle":"细胞分裂与细胞分化","source":"term_doc","answerStatus":"reference","qid":"TERM-0092"},{"term":"双线期","answer":"是减数第一次分裂前期第4 个亚时期。这个时期的特点有:染色体继\n续变粗变短，二价体中配对的同源染色体趋向分开；在非姐妹染色单\n体间出现交叉结，交叉结的出现是发生交换的有形结果；联会复合体\n消失，交叉结在染色体彼此分离拉开时而消失。","chapterNo":5,"chapterTitle":"细胞分裂与细胞分化","source":"term_doc","answerStatus":"reference","qid":"TERM-0093"},{"term":"浓缩期","answer":"是减数第一次分裂前期第5 个亚时期。这个时期的特点有:染色体螺\n旋化程度更高，变得更加粗而短；核被膜、核仁解体，中心粒完成复\n制；两个中心体分别移向细胞两极，纺锤体形成，减数第一次分裂前\n期结束。在植物的减数分裂过程中，不形成中心体，其他与动物细胞\n相同。","chapterNo":5,"chapterTitle":"细胞分裂与细胞分化","source":"term_doc","answerStatus":"reference","qid":"TERM-0094"},{"term":"细胞衰老","answer":"是指多细胞生物体的细胞经过有限次数的分裂以后，停止生长，进入\n不可逆转的增殖抑制状态，细胞形态和生理代谢活动发生衰老性变化。","chapterNo":5,"chapterTitle":"细胞分裂与细胞分化","source":"term_doc","answerStatus":"reference","qid":"TERM-0095"},{"term":"端粒学说","answer":"端粒是线性染色体末端的一种特殊结构，维持着染色体的稳定,端粒\n因细胞分裂而变短到一定程度时，细胞就会死亡。端粒破损会导致\nDNA变得脆弱，容易发生变异，可能导致些与衰老相关的疾病，如动\n脉硬化和某些癌症。","chapterNo":5,"chapterTitle":"细胞分裂与细胞分化","source":"term_doc","answerStatus":"reference","qid":"TERM-0096"},{"term":"自由基学说","answer":"自由基是细胞衰老的主要原因之一。其主要机制是细胞利用氧分子获\n得能量的同时,2%-3%的氧分子转化为过氧化氢和羟自由基，自由基对\n细胞中的DNA、RNA和蛋白质均会造成较大的损伤，还会破坏细胞膜、\n细胞内部结构和功能，引起生理生化反应的衰退，造成细胞衰老。","chapterNo":5,"chapterTitle":"细胞分裂与细胞分化","source":"term_doc","answerStatus":"reference","qid":"TERM-0097"},{"term":"联会（synapsis）","answer":"亦称配对,指同源染色体两两配对在细胞减数分裂前期的偶线期,来\n自父本和母本的同源染色体,两两靠拢进行准确的配对,形成四分体,\n即一对染色体含有四条染色单体,但仅有两个着丝点,所以又称四分\n体,是减数分裂的重要特征。","chapterNo":5,"chapterTitle":"细胞分裂与细胞分化","source":"term_doc","answerStatus":"reference","qid":"TERM-0098"},{"term":"四分体（tetrad）","answer":"由于每一个染色体实际含有一对姐妹染色单体，因此联会复合体共有\n4个染色单体，称四分体。联会复合体的形成使同源的非姐妹染色单\n体间形成交叉并有可能发生对等片段的交换，最终导致遗传物质的非\n随机重组，从而造成了子代生物遗传特性的变异。","chapterNo":5,"chapterTitle":"细胞分裂与细胞分化","source":"term_doc","answerStatus":"reference","qid":"TERM-0099"},{"term":"细胞增殖","answer":"是生命的基本现象，生物体生长、发育、繁殖和遗传的基础，维持体\n内细胞数量动态平衡的基本措施，是受基因调控的精确过程。靠细胞\n的分裂来实现。","chapterNo":5,"chapterTitle":"细胞分裂与细胞分化","source":"term_doc","answerStatus":"reference","qid":"TERM-0100"},{"term":"细胞周期","answer":"细胞从一次分裂开始到第二次分裂开始所经历的全过程称为一个细\n胞周期，包括一个有丝分裂期和一个分裂间期。后者包括DNA合成期\n(s期)以及s 期前后的2个间歇期(G1期、G2期)。","chapterNo":5,"chapterTitle":"细胞分裂与细胞分化","source":"term_doc","answerStatus":"reference","qid":"TERM-0101"},{"term":"染色单体","answer":"在细胞分裂过程中，每个染色体经过分裂间期复制后实际上含有2个\n并列的、由同一着丝粒固着的、经过紧密盘旋折叠的DNA双链，称为\n染色单体。","chapterNo":5,"chapterTitle":"细胞分裂与细胞分化","source":"term_doc","answerStatus":"reference","qid":"TERM-0102"},{"term":"着丝粒","answer":"位于染色体的主缢痕中，是染色单体上一段特殊的DNA序列（重复序\n列)，是姐妹染色单体在分开前相互联结的位置。它是染色质，是染\n色体最后复制的部分。着丝粒和主缢痕在各染色体上的位置是确定的，\n位于染色体中央，或是偏于染色体一侧，甚至近于染色体的一端。","chapterNo":5,"chapterTitle":"细胞分裂与细胞分化","source":"term_doc","answerStatus":"reference","qid":"TERM-0103"},{"term":"动粒","answer":"细胞有丝分裂和减数分裂过程中，位于染色体着丝粒区域的一种高度\n复杂的蛋白质复合体结构。它是连接染色体与纺锤体微管的关键装置，\n确保染色体精确分离到子细胞中。星体：是指中心体的外围有成辐射\n状排列的微管，形成光学显微镜下可见的星状丝，星状丝和中心体合\n称星体。","chapterNo":5,"chapterTitle":"细胞分裂与细胞分化","source":"term_doc","answerStatus":"reference","qid":"TERM-0104"},{"term":"赤道面","answer":"是指细胞中央的一个平面。细胞有丝分裂中期，纺锤体内的染色体逐\n渐聚集在赤道面上，各着丝粒排列在这个平面上而形成赤道板，及至\n末期，在动物细胞中，赤道面的表层细胞质产生凹缩，而开始细胞质\n分裂；而在植物细胞中，则从赤道面的中央部位发展形成成膜体，在\n赤道面上形成细胞板。","chapterNo":5,"chapterTitle":"细胞分裂与细胞分化","source":"term_doc","answerStatus":"reference","qid":"TERM-0105"},{"term":"主缢痕","answer":"在两条染色单体相连处，染色体上出现的一个向内凹陷的缩细的部位，\n着丝粒位于其上，这个部位就叫主缢痕，又称着丝粒区。(由于这一\n区域染色体的螺旋化程度低，DNA含量少，所以染色很浅或不着色.","chapterNo":5,"chapterTitle":"细胞分裂与细胞分化","source":"term_doc","answerStatus":"reference","qid":"TERM-0106"},{"term":"次缢痕","answer":"是指除主缢痕外，在染色体上其他的浅染缢缩部位。(每种生物染色\n体组中至少有一条或一对染色体上有次缢痕。次缢痕中的染色质含有\nrDNA,它与rDNA 的形成有关。)","chapterNo":5,"chapterTitle":"细胞分裂与细胞分化","source":"term_doc","answerStatus":"reference","qid":"TERM-0107"},{"term":"性染色体","answer":"是决定性别的染色体。女人的一对性染色体结构相同，称为x染色体；\n男人的一对性染色体一条为x 染色体，另一条为y 染色体。","chapterNo":5,"chapterTitle":"细胞分裂与细胞分化","source":"term_doc","answerStatus":"reference","qid":"TERM-0108"},{"term":"常染色体","answer":"在生物体细胞中，除了与决定性别有关的性染色性外，还有与性别决\n定无关的染色体，是成对存在的，称为常染色体。人有23对染色体，\n其中22对为常染色体，只有一对为性染色体。","chapterNo":5,"chapterTitle":"细胞分裂与细胞分化","source":"term_doc","answerStatus":"reference","qid":"TERM-0109"},{"term":"端粒【2017 年名词解释】","answer":"线形染色体末端的一种特殊结构，由特定的DNA序列和蛋白质组成，\n对细胞的正常复制至关重要。(端粒的长度反映细胞复制史及复制潜\n能，被称作细胞寿命的“有丝分裂钟”。)","chapterNo":5,"chapterTitle":"细胞分裂与细胞分化","source":"term_doc","answerStatus":"reference","qid":"TERM-0110"},{"term":"染色体组型","answer":"根据染色体的相对大小，着丝粒的位置，臂的长短，随体的有无等特\n征，把某种生物体细胞中的全套染色体按一定顺序分组排列起来就构\n成了这一物种的染色体组型。例如，人有23对染色体，可根据它们\n的形态、大小、着丝粒位置等，按序排列成1-22对，另外还有一对\n性染色体，这就是人的染色体组型。","chapterNo":5,"chapterTitle":"细胞分裂与细胞分化","source":"term_doc","answerStatus":"reference","qid":"TERM-0111"},{"term":"G0期细胞","answer":"从细胞增殖角度看，细胞可以分三类：\n(1)周期性细胞：持续不断分裂的细胞，始终保持旺盛的增殖活性。\n如顶端分生组织细胞、造血干细胞。\n(2)静止期细胞(G0期细胞、休眠细胞):暂时脱离细胞周期不再分裂\n的细胞外部刺激可以使其恢复分裂能力。如肝细胞、淋巴细胞。\n(3)终末分化细胞：永久失去分裂能力，不再分裂的细胞，其结构和\n功能高度特化。如神经细胞。","chapterNo":5,"chapterTitle":"细胞分裂与细胞分化","source":"term_doc","answerStatus":"reference","qid":"TERM-0112"},{"term":"无丝分裂","answer":"是一类没有染色体和纺锤体出现的细胞分裂方式，其主要特征是首先\n细胞核分裂，进而细胞质分割，形成两个子细胞的过程。因为分裂时\n没有纺锤丝与染色体的变化，所以叫做无丝分裂。","chapterNo":5,"chapterTitle":"细胞分裂与细胞分化","source":"term_doc","answerStatus":"reference","qid":"TERM-0113"},{"term":"有丝分裂","answer":"是真核生物体细胞的分裂方式，有丝分裂中DNA复制一次，细胞分裂\n一次，得到两个与母代染色体数目相等的子细胞，保证了细胞遗传的\n稳定性。有丝分裂可分为前期，前中期，中期，后期和末期几个阶段。\n在分裂进入后期和末期时，胞质分裂将细胞分为两个子细胞。","chapterNo":5,"chapterTitle":"细胞分裂与细胞分化","source":"term_doc","answerStatus":"reference","qid":"TERM-0114"},{"term":"减数分裂","answer":"是有性生殖个体形成生殖细胞过程中所发生的一种特殊的细胞分裂\n方式。减数分裂中DNA复制一次细胞分裂两次，因此子细胞染色体数\n目减半，但是通过精卵结合又恢复到原来体细胞中染色体的数目。","chapterNo":5,"chapterTitle":"细胞分裂与细胞分化","source":"term_doc","answerStatus":"reference","qid":"TERM-0115"},{"term":"联会","answer":"减数分裂I期的偶线期，同源染色体的两个成员逐渐变粗并侧向靠拢，\n这种现象称为联会。是减数分裂的一个重要过程。","chapterNo":5,"chapterTitle":"细胞分裂与细胞分化","source":"term_doc","answerStatus":"reference","qid":"TERM-0116"},{"term":"联会复合体","answer":"是配对染色体之间的特殊结构，成分主要是蛋白质，在减数分裂中有\n使两个染色体紧密靠拢的作用。联会复合体出现于偶线期，成熟于粗\n线期，消失于双线期。","chapterNo":5,"chapterTitle":"细胞分裂与细胞分化","source":"term_doc","answerStatus":"reference","qid":"TERM-0117"},{"term":"四分体","answer":"是减数分裂配对完毕的染色体，又称二价体。每个二价体由两条同源\n染色体组成，而每条同源染色体包括2 条姐妹染色单体，这样每个二\n价体包括4条染色单体，称为四分体。","chapterNo":5,"chapterTitle":"细胞分裂与细胞分化","source":"term_doc","answerStatus":"reference","qid":"TERM-0118"},{"term":"细胞分化【2013年名词解释】","answer":"是指多细胞生物在个体发育过程中，细胞后代在形态结构和功能上发\n生稳定性差异，产生不同类型细胞的过程。细胞分化的实质是基因的\n选择性表达。一般情况下，细胞分化过程是不可逆的。细胞分化是动\n物和植物发育的基础，使生物体能正常的生长发育。","chapterNo":5,"chapterTitle":"细胞分裂与细胞分化","source":"term_doc","answerStatus":"reference","qid":"TERM-0119"},{"term":"干细胞（第五版新增概念）//修改了分类","answer":"是指具有分化成其他细胞类型和构建组织和器官的能力的一类细胞。\n具有持久性或终身自我更新能力。根据干细胞发育全潜能分为五类：\n全能干细胞、多潜能干细胞、多能干细胞、双能干细胞和单能干细胞。\n（1）全能干细胞：具有分化形成胚胎组织在在内的完整生命体的潜\n能，如受精卵和早期卵裂球细胞。\n（2）多潜能干细胞：能分化成三个胚层，构建整个胚胎，如胚胎干\n细胞。\n（3）多能干细胞：仅具有分化成多个细胞类型的能力，不能构建完\n整胚胎。如造血干细胞。\n（4）双能干细胞：具有两种类型细胞发育的潜能。如指甲根部的干\n细胞可以分化成指甲和表皮。\n（5）单能干细胞：只能分化成一种细胞类型。如神经干细胞只能分\n化成神经细胞。","chapterNo":5,"chapterTitle":"细胞分裂与细胞分化","source":"term_doc","answerStatus":"reference","qid":"TERM-0120"},{"term":"细胞全能性【2018、19 年-名词解释】","answer":"细胞经分裂和分化后仍具有产生完整有机体的潜能或特性。在多细胞\n生物中，每个体细胞的细胞核都含有个体发育的全部基因，只要条件\n许可都可发育成完整的个体。受精卵和早期胚胎干细胞都是具有细胞\n全能性的细胞。","chapterNo":5,"chapterTitle":"细胞分裂与细胞分化","source":"term_doc","answerStatus":"reference","qid":"TERM-0121"},{"term":"复制性细胞衰老","answer":"细胞经过有限次分裂后，进人不可逆转的增殖抑制状态，其结构和功\n能发生衰老性改变的过程。(成因：随着复制次数的增加，细胞染色\n体两端的端粒逐渐缩短，细胞复制能力由此减弱。)","chapterNo":5,"chapterTitle":"细胞分裂与细胞分化","source":"term_doc","answerStatus":"reference","qid":"TERM-0122"},{"term":"Hayflick界限","answer":"是指Hayflick等人发现的细胞分裂能力和寿命是有一定限度的规律，\n如体外培养人的二倍体细胞，只能培养成活40-60代。","chapterNo":5,"chapterTitle":"细胞分裂与细胞分化","source":"term_doc","answerStatus":"reference","qid":"TERM-0123"},{"term":"细胞凋亡【2015、16、17、19、20 年名词解释】","answer":"是指在细胞发育过程中由自身基因编程的一种主动的程序性死亡过\n程，细胞凋亡普遍存在于生物的生长发育阶段，使生物体得以清除不\n再需要的组织、细胞，而不引起炎症反应。如脊椎动物的肢体发育过\n程中，通过指尖的细胞发生凋亡，而形成正常的肢体。","chapterNo":5,"chapterTitle":"细胞分裂与细胞分化","source":"term_doc","answerStatus":"reference","qid":"TERM-0124"},{"term":"细胞坏死","answer":"细胞受到物理化学、生物因素的伤害，细胞质膜通透性增高，致使细\n胞肿胀破裂，DNA随机降解，细胞死亡的现象。常常引起炎症反应。","chapterNo":5,"chapterTitle":"细胞分裂与细胞分化","source":"term_doc","answerStatus":"reference","qid":"TERM-0125"},{"term":"纺锤丝","answer":"纺锤丝是光学显微镜下所见到的有丝分裂期组成纺锤体的丝状结构\n之总称。动物细胞的纺锤丝由中心体释放，植物细胞的纺锤丝由细胞\n两极发出。纺锤丝由微管聚合而成，功能是牵引姐妹染色单体并在细\n胞增殖的后期将姐妹染色单体分别牵引到细胞的两侧。构成纺锤体的\n纺锤丝有二种类型：染色体牵丝和连续丝。","chapterNo":5,"chapterTitle":"细胞分裂与细胞分化","source":"term_doc","answerStatus":"reference","qid":"TERM-0126"},{"term":"脱分化","answer":"已分化的细胞经过诱导后失去其特有的结构和功能而转变成未分化\n细胞的过程叫脱分化。脱分化与再分化是植物组织培养的重要过程。","chapterNo":5,"chapterTitle":"细胞分裂与细胞分化","source":"term_doc","answerStatus":"reference","qid":"TERM-0127"},{"term":"再分化","answer":"已经脱分化的愈伤组织，在一定条件下再分化出胚状体形成完整植株，\n这一过程叫做再分化。(细胞再分化过程事实上是基因选择性表达与\n修饰的人工调控过程。)","chapterNo":5,"chapterTitle":"细胞分裂与细胞分化","source":"term_doc","answerStatus":"reference","qid":"TERM-0128"},{"term":"植物细胞的全能性","answer":"指的是植物的每个细胞都包含着该物种的全部遗传信息，从而具备发\n育成完整植株的遗传能力。植物细胞全能性是植物组织培养的理论基\n础。","chapterNo":5,"chapterTitle":"细胞分裂与细胞分化","source":"term_doc","answerStatus":"reference","qid":"TERM-0129"},{"term":"植物组织培养","answer":"又称离体培养，是指利用植物体离体的器官、组织或细胞，在适宜条\n件下经脱分化诱导出愈伤组织，愈伤组织在一定条件下再分化出胚状\n体，形成完整植株的技术。","chapterNo":5,"chapterTitle":"细胞分裂与细胞分化","source":"term_doc","answerStatus":"reference","qid":"TERM-0130"},{"term":"再生医学","answer":"再生医学是指利用生物学及工程学的理论方法创造丢失或功能损害\n的组织和器官，使其具备正常组织和器官的结构和功能。(目前，再\n生医学领域正在探索的3大策略包括：通过移植细胞悬浮体或聚合体\n来替代受损组织；实验室生产的能够替代天然组织的生物化人工组织\n或器官的植入；通过药物手段，对损伤组织部分进行再生诱导。)","chapterNo":5,"chapterTitle":"细胞分裂与细胞分化","source":"term_doc","answerStatus":"reference","qid":"TERM-0131"},{"term":"管家基因、奢侈基因（2025 填空）//区分二者概念","answer":"细胞中的基因，并不都与分化有关。按照与分化的关系，基因可以分\n为两类。\n一类与细胞种类无关，在任何细胞中都表达，是维持细胞基本功能的\n必需基因，如编码催化糖酵解过程的酶、微管蛋白和组蛋白等，这些\n基因叫做管家基因。\n一类基因与分化细胞的特殊性状有关，如成红细胞中的珠蛋白基因、\n上皮细胞的角蛋白基因、骨骼肌细胞的MyoD 基因等，这些基因叫做\n组织特异性基因也叫奢侈基因，意思是它们并非细胞生存所必需。","chapterNo":5,"chapterTitle":"细胞分裂与细胞分化","source":"term_doc","answerStatus":"reference","qid":"TERM-0132"},{"term":"祖细胞/前体细胞（第五版教材新增）","answer":"干细胞早期分化后产生的细胞不再具有无限的自我更新能力，只能分\n裂有限次数，并随着分裂而进行分化，称之为祖细胞或前体细胞。","chapterNo":5,"chapterTitle":"细胞分裂与细胞分化","source":"term_doc","answerStatus":"reference","qid":"TERM-0133"},{"term":"密度制约的抑制作用","answer":"培养的细胞通常分裂到在培养皿内壁上形成一满层细胞后就停止，当\n细胞集群达到一定密度以后，每个细胞所得到的养分和生长因子都不\n够了，不足以维持细胞的继续生长。","chapterNo":5,"chapterTitle":"细胞分裂与细胞分化","source":"term_doc","answerStatus":"reference","qid":"TERM-0134"},{"term":"遗传变异（2014名词解释）","answer":"生物的亲代与子代之间，在形态、结构和功能上常常相似的现象，称\n为遗传。\n(遗传的本质是基因准确复制。)\n生物的亲代与子代之间，子代的不同个体之间，或多或少的存在着差\n异的现象，称为变异。\n(变异的本质是基因、基因组合变化。)\n遗传是相对的、保守的，保证物种相对稳定性；变异是绝对的、前进\n的，是进化的原材料。\n遗传和变异在生物的进化中同等重要。","chapterNo":6,"chapterTitle":"性状遗传的基本规律","source":"term_doc","answerStatus":"reference","qid":"TERM-0135"},{"term":"性状","answer":"生物体在形态、结构、生理等方面所具有的区别性特征。","chapterNo":6,"chapterTitle":"性状遗传的基本规律","source":"term_doc","answerStatus":"reference","qid":"TERM-0136"},{"term":"相对性状","answer":"同种生物同一性状的不同表现类型，叫做相对性状。","chapterNo":6,"chapterTitle":"性状遗传的基本规律","source":"term_doc","answerStatus":"reference","qid":"TERM-0137"},{"term":"显性性状与隐性性状","answer":"在遗传学上，把杂种F1中显现出来的那个亲本性状叫做显性性状。\n杂种F1中未显现出来的那个亲本性状叫做隐性性状。","chapterNo":6,"chapterTitle":"性状遗传的基本规律","source":"term_doc","answerStatus":"reference","qid":"TERM-0138"},{"term":"性状分离","answer":"在杂种后代中显现不同性状的现象，叫做性状分离。","chapterNo":6,"chapterTitle":"性状遗传的基本规律","source":"term_doc","answerStatus":"reference","qid":"TERM-0139"},{"term":"显性基因","answer":"控制显性性状的基因，叫做显性基因。","chapterNo":6,"chapterTitle":"性状遗传的基本规律","source":"term_doc","answerStatus":"reference","qid":"TERM-0140"},{"term":"隐性基因","answer":"控制隐性性状的基因，叫做隐性基因。","chapterNo":6,"chapterTitle":"性状遗传的基本规律","source":"term_doc","answerStatus":"reference","qid":"TERM-0141"},{"term":"等位基因（2019年名词解释）","answer":"在一对同源染色体的同一基因座上的，控制着相对性状的基因，叫做\n等位基因。","chapterNo":6,"chapterTitle":"性状遗传的基本规律","source":"term_doc","answerStatus":"reference","qid":"TERM-0142"},{"term":"复等位基因（2023 年名词解释）","answer":"是指在群体中，占据同源染色体同一基因座的、两个以上的决定同一\n性状的基因系列。如控制ABO 血型的基因。","chapterNo":6,"chapterTitle":"性状遗传的基本规律","source":"term_doc","answerStatus":"reference","qid":"TERM-0143"},{"term":"表型","answer":"生物个体所表现出来的性状。如菌落的颜色、大小和形状等。\n(表型是由基因型决定的，并且受到环境的影响，是由遗传与环境共\n同作用的结果。表型的分子基础是不同的基因通过编码产生一系列不\n同功能的蛋白质，来实现其独特的表型特征的。)","chapterNo":6,"chapterTitle":"性状遗传的基本规律","source":"term_doc","answerStatus":"reference","qid":"TERM-0144"},{"term":"基因型","answer":"是指与表型有关的基因组成。在表示基因型时，一般只将突变的基因\n或与所研究相关的基因列出。","chapterNo":6,"chapterTitle":"性状遗传的基本规律","source":"term_doc","answerStatus":"reference","qid":"TERM-0145"},{"term":"纯合体","answer":"由含有相同基因的配子结合成的合子发育而成的个体。纯合体自交后\n代不发生性状分离。","chapterNo":6,"chapterTitle":"性状遗传的基本规律","source":"term_doc","answerStatus":"reference","qid":"TERM-0146"},{"term":"杂合体","answer":"由含有不同基因的配子结合成的合子发育而成的个体。杂合体自交后\n代要发生性状分离。\n(注：如果考到2~13 题，自己在后面举个例子凑字数。)","chapterNo":6,"chapterTitle":"性状遗传的基本规律","source":"term_doc","answerStatus":"reference","qid":"TERM-0147"},{"term":"基因的分离定律","answer":"成对的遗传因子在杂合状态时互不干扰，保持独立性，在配子形成时，\n等位基因随着同源染色体的分开而分离，分离到不同的配子中去，独\n立地随着配子遗传给后代。\n(在一般情况下，F1配子分离比是1:1,F2基因型分离比是1:2:1,F2\n表型分离比是3:1。这就是基因分离定律。)","chapterNo":6,"chapterTitle":"性状遗传的基本规律","source":"term_doc","answerStatus":"reference","qid":"TERM-0148"},{"term":"测交","answer":"将F1杂种与纯合隐性亲本进行杂交的方法，来证明F1杂种产生两种\n不同但数目相等配子，实质上是用隐性亲本来测验F1杂种基因型的\n一种回交。(遗传学上常用此法测定个体的基因类型。)","chapterNo":6,"chapterTitle":"性状遗传的基本规律","source":"term_doc","answerStatus":"reference","qid":"TERM-0149"},{"term":"基因的自由组合定律","answer":"制两对相对性状的两对等位基因分别位于不同的同源染色体上，在配\n子形成时，等位基因随着同源染色体的分开而分离，非等位基因随着\n非同源染色体的自由组合而自由组合，分别进入配子细胞中。\n(在一般情况下，F1配子分离比是1:1:1:1,F2基因型分离比是(1:2:1)\n²,F2表型分离比是(3:1)²。这就是基因自由组合定律。)","chapterNo":6,"chapterTitle":"性状遗传的基本规律","source":"term_doc","answerStatus":"reference","qid":"TERM-0150"},{"term":"基因重组","answer":"是指控制不同性状的基因的重新组合。\n(基因重组的主要包括两种：非等位基因随着非同源染色体的自由组\n合而自由组合，使得雌雄配子结合；同源染色体的非姐妹染色单体之\n间发生局部交换。)","chapterNo":6,"chapterTitle":"性状遗传的基本规律","source":"term_doc","answerStatus":"reference","qid":"TERM-0151"},{"term":"性别决定","answer":"一般是指雌雄异体的生物决定性别的方式。(例如，人类的性别是在\n受精时的一刹那时间内，由性染色体的不同组合而决定的。受精卵的\n染色体组成是性别决定的物质基础。)","chapterNo":6,"chapterTitle":"性状遗传的基本规律","source":"term_doc","answerStatus":"reference","qid":"TERM-0152"},{"term":"伴性遗传","answer":"性染色体上的基因，所控制的遗传性状与性别相联系，这种遗传方式\n叫做伴性遗传。许多生物都有伴性遗传现象。","chapterNo":6,"chapterTitle":"性状遗传的基本规律","source":"term_doc","answerStatus":"reference","qid":"TERM-0153"},{"term":"连锁","answer":"位于同一染色体上的基因总是倾向于联系在一起共同遗传的现象。\n(重组类型的产生，是由于配子形成过程中，同源染色体的非姐妹染\n色单体间发生局部交换的结果，重组频率的大小与连锁基因在染色体\n上的位置有关。)","chapterNo":6,"chapterTitle":"性状遗传的基本规律","source":"term_doc","answerStatus":"reference","qid":"TERM-0154"},{"term":"细胞核遗传与细胞质遗传","answer":"细胞核遗传指由细胞核的遗传物质控制的遗传现象。细胞核遗传遵循\n孟德尔的遗传定律。\n细胞质遗传又称核外遗传、染色体外遗传、非孟德尔式。指由细胞质\n(线粒体和叶绿体)中的遗传物质控制的遗传现象。细胞质遗传不遵循\n孟德尔的遗传定律。核外基因所表达的性状在F1通常只表达母方的\n性状，后代一般不出现一定比例的分离。","chapterNo":6,"chapterTitle":"性状遗传的基本规律","source":"term_doc","answerStatus":"reference","qid":"TERM-0155"},{"term":"镶嵌显性","answer":"具有相对性状的纯合亲本杂交后，F1在不同部位分别表现出双亲的\n性状，形成镶嵌图式的现象。比如异色瓢虫的鞘翅色斑遗传，黑缘型\n(鞘翅前部为黑色)和纯种均色型(鞘翅后部为黑色)杂交的F1表现为\n鞘翅的前后都有黑色。","chapterNo":6,"chapterTitle":"性状遗传的基本规律","source":"term_doc","answerStatus":"reference","qid":"TERM-0156"},{"term":"共显性","answer":"具有相对性状的纯合亲本杂交后，F1在同一部位、同时同等地表现\n出双亲的性状的现象。比如人类的MN血型系统，MN型血的人是杂合\n子，他们的血细胞上既有M 型抗原，又有N型抗原，两个基因同时表\n达。","chapterNo":6,"chapterTitle":"性状遗传的基本规律","source":"term_doc","answerStatus":"reference","qid":"TERM-0157"},{"term":"不完全显性","answer":"具有相对性状的纯合亲本杂交后，F1显现中间类型的现象。比如说\n纯合的红花和白花杂交，F1代表现为粉花。","chapterNo":6,"chapterTitle":"性状遗传的基本规律","source":"term_doc","answerStatus":"reference","qid":"TERM-0158"},{"term":"完全显性","answer":"具有相对性状的纯合体亲本杂交后，F1只表现一个亲本性状的现象。\n即外显率为100%。例如，豌豆种子的圆形(RR)和皱形(rr)亲本杂交\n得F1种子(Rr),由于R 对r 为完全显性，所以F1的表现与RR亲本完\n全相同，即为圆形显性性状。","chapterNo":6,"chapterTitle":"性状遗传的基本规律","source":"term_doc","answerStatus":"reference","qid":"TERM-0159"},{"term":"非等位基因的重叠作用","answer":"基因互作是指非等位基因之间通过相互作用影响同一性状表现的现\n象。非等位基因间相互作用包括6 种：互补作用、积加作用、重叠作\n用、显性上位作用、隐性上位作用、抑制作用。\n(1)互补作用：两对基因均为显性时，共同决定一种性状；当只有一\n对基因为显性，或两对基因都是隐性时，表现出另一种性状。F2产\n生9:7的比例。\n(2)积加作用：两对基因均为显性时，共同决定一种性状；当只有一\n对基因为显性时，表现出另一种性状；两对基因均为隐性时，表现出\n第三种性状。F2产生9:6:1的比例。\n(3)重叠作用：两对基因均为显性，或有一对基因为显性时表现为一\n种性状；两对基因均为隐性时表现出另一种性状。,F2产生15:1 的\n比例。\n(4)显性上位作用：在两对互作的基因中，某一对显性基因对另一对\n基因有遮盖作用，并表现出自身所控制的性状。当该对基因为显性时，\n表现出一种性状；当该对基因为隐性而另一对基因为显性时，表现出\n另一种性状；两对基因均为隐性时，表现出第三种性状。F2产生\n12:3:1的比例。\n(5)隐性上位作用：在两对互作的基因中，某一对隐性基因对另一对\n基因有遮盖作用，并表现出自身所控制的性状。当该对基因为隐性时，\n表现出一种性状；当该对基因为显性而另一对基因为隐性时，表现出\n另一种性状；当两对基因均为显性时，表现出第三种性状。F2产生\n9:3:4的比例。\n(6)抑制作用：在两对互作的基因中，其中一对显性基因本身并不控\n制性状的表现，但对另一对基因的表现有抑制作用。当起抑制作用的\n基因为显性，另一对基因为隐性时表现另一种形状。F2产生13:3的\n比例。","chapterNo":6,"chapterTitle":"性状遗传的基本规律","source":"term_doc","answerStatus":"reference","qid":"TERM-0160"},{"term":"正交与反交","answer":"表现型不同的两种个体A和B。若以A为母本B 为父本的杂交称为正\n交，以B 为母本A为父本的杂交则称为反交。","chapterNo":6,"chapterTitle":"性状遗传的基本规律","source":"term_doc","answerStatus":"reference","qid":"TERM-0161"},{"term":"系谱分析法","answer":"遗传学家采用分析系谱的方法来研究人类简单的孟德尔式遗传。","chapterNo":6,"chapterTitle":"性状遗传的基本规律","source":"term_doc","answerStatus":"reference","qid":"TERM-0162"},{"term":"颗粒遗传理论","answer":"是指在有性生殖的二倍体生物中，每一个基因都是一个相对独立的功\n能单位，控制成对性状的基因是成对的，在形成配子时，成对的等位\n基因相对分离并传递给子代。颗粒遗传理论是孟德尔学说的核心，与\n融合遗传的观点相对立。","chapterNo":6,"chapterTitle":"性状遗传的基本规律","source":"term_doc","answerStatus":"reference","qid":"TERM-0163"},{"term":"融合遗传理论","answer":"融合遗传是达尔文提出的，他主张两亲代的相对性状在杂种后代中融\n合而成为新的性状而出现，也即子代的性状是亲代性状的平均结果，\n且杂合子后代中没有一定的分离比例。","chapterNo":6,"chapterTitle":"性状遗传的基本规律","source":"term_doc","answerStatus":"reference","qid":"TERM-0164"},{"term":"质量性状","answer":"质量性状是指由一对或者两对等位基因决定，每对基因在表型上有明\n显差异的遗传现象。如红与白、有与无。","chapterNo":6,"chapterTitle":"性状遗传的基本规律","source":"term_doc","answerStatus":"reference","qid":"TERM-0165"},{"term":"数量性状","answer":"数量性状是指一个群体内的各个体间由多对基因决定的表现为连续\n变异的性状。如动植物的高度或长度、人的肤色。","chapterNo":6,"chapterTitle":"性状遗传的基本规律","source":"term_doc","answerStatus":"reference","qid":"TERM-0166"},{"term":"微效基因","answer":"微效基因是指决定数量性状多对基因中每一对基因只有较小表型效\n应的基因。","chapterNo":6,"chapterTitle":"性状遗传的基本规律","source":"term_doc","answerStatus":"reference","qid":"TERM-0167"},{"term":"多基因遗传","answer":"多基因遗传是指受多对非等位基因控制的遗传现象。如肤色、身高。","chapterNo":6,"chapterTitle":"性状遗传的基本规律","source":"term_doc","answerStatus":"reference","qid":"TERM-0168"},{"term":"遗传的染色体学说","answer":"萨顿和博韦里提出，孟德尔的遗传因子(基因)与性细胞在减数分裂过\n程中的染色体行为有着平行的关系，即染色体是基因的载体。","chapterNo":6,"chapterTitle":"性状遗传的基本规律","source":"term_doc","answerStatus":"reference","qid":"TERM-0169"},{"term":"性连锁基因","answer":"是指定位在性染色体上的基因。","chapterNo":6,"chapterTitle":"性状遗传的基本规律","source":"term_doc","answerStatus":"reference","qid":"TERM-0170"},{"term":"连锁交换定律/遗传学第三定律（2013名词解释）","answer":"摩尔根及其学生提出连锁交换定律。处在同一染色体上的两对或两对\n以上的基因遗传时，联合在一起共同出现在后代中的频率大于重新组\n合的频率，重组类型的产生是由于配子形成过程中，同源染色体的非\n姐妹染色单体间发生局部交换的结果。重组频率的大小与连锁基因在\n染色体上的相对位置有关。","chapterNo":6,"chapterTitle":"性状遗传的基本规律","source":"term_doc","answerStatus":"reference","qid":"TERM-0171"},{"term":"完全连锁","answer":"由于不发生非姐妹染色单体之间的交换，同一染色体上的两个非等位\n基因总是联系在一起遗传的现象。","chapterNo":6,"chapterTitle":"性状遗传的基本规律","source":"term_doc","answerStatus":"reference","qid":"TERM-0172"},{"term":"不完全连锁","answer":"由于发生非姐妹染色单体的互换，导致位于同源染色体上的非等位基\n因的杂合体在形成配子时除有亲本型配子外，还有少数的重组型配子\n产生的现象。","chapterNo":6,"chapterTitle":"性状遗传的基本规律","source":"term_doc","answerStatus":"reference","qid":"TERM-0173"},{"term":"连锁群","answer":"连锁群是指位于同一对染色体上的基因群。","chapterNo":6,"chapterTitle":"性状遗传的基本规律","source":"term_doc","answerStatus":"reference","qid":"TERM-0174"},{"term":"基因定位","answer":"基因定位是指利用重组率来确定染色体上基因之间相对距离的方法。\n重组率=重组型数目/子代总数。","chapterNo":6,"chapterTitle":"性状遗传的基本规律","source":"term_doc","answerStatus":"reference","qid":"TERM-0175"},{"term":"连锁图","answer":"连锁图即染色体图，是指确定基因在染色体上的相对位置和排列顺序\n后绘制的简单的线性示意图","chapterNo":6,"chapterTitle":"性状遗传的基本规律","source":"term_doc","answerStatus":"reference","qid":"TERM-0176"},{"term":"ABC模型（新增）","answer":"科学家研究拟南芥花的突变体时，发现了控制花的各部分发生的基因，\n提出了其分子调控模型：ABC模型。该模型认为，正常的花器官发育\n涉及A、B、C 三类基因，A 类基因在花萼和花瓣中表达，B 类基因在\n花瓣和雄蕊中表达，C类基因在雄蕊和雌蕊中表达。A 类和C 类基因\n相互拮抗。无论哪类基因突变，都会引起相对应的表型的改变","chapterNo":6,"chapterTitle":"性状遗传的基本规律","source":"term_doc","answerStatus":"reference","qid":"TERM-0177"},{"term":"基因多效性/一因多效，多因一效（新增）","answer":"基因不仅存在复等位现象，每一个基因的功能也不一定是单一的，而\n是有可能决定多种不同的性状，这种现象称为基因多效性，或称“一\n因多效”。例如导致镰刀型细胞贫血症的基因突变（影响血红蛋白），\n除了引起贫血，还可能导致生长迟缓、易感染、器官损伤等多种症状\n“多因一效”\n指多个基因（通常指多个不同的基因位点）共同作用决定同一个表型\n性状的现象。这个性状通常是数量性状，表现为连续变异（如身高、\n体重、肤色、产量等）。","chapterNo":6,"chapterTitle":"性状遗传的基本规律","source":"term_doc","answerStatus":"reference","qid":"TERM-0178"},{"term":"上位效应，上位基因，下位基因，隐性上位，显性上位","answer":"（1）上位效应：\n两个或多个基因相互作用时，一个基因（上位基因）的表达抑制或修\n饰了\n另一个基因（下位基因）的表型表现。基因间的非加性互作，导致经\n典孟德尔比例（如9:3:3:1）\n发生改变。例子：\n南瓜果色的遗传（经典模型）：\n基因A（控制色素合成）：显性A→白色，隐性aa→有色。\n基因B（控制色素类型）：显性B→黄色，隐性bb→绿色。\n当A存在（AA/Aa）时，无论B 如何，果色均为白色（A掩盖了B 的\n作用）。\n（2）上位基因：在互作中起主导作用的基因，其表型效应会抑制其\n他基因（下位基因）的表达。上述南瓜例子中，基因A 是上位基因—\n—只要A 存在（显性），果色即为白色，无视基因B的状态。\n（3）下位基因：在互作中被上位基因掩盖的基因，其表型效应无法\n显现。南瓜例子中，基因B是下位基因——当A存在时，B无法表达\n其控制色素类型的功能。\n（4）显性上位：上位基因的显性等位基因抑制下位基因的表达。两\n对基因杂交时（如AaBb×AaBb），经典比例为12:3:1（修改自9:3:3:1）。\n（5）隐性上位：上位基因的隐性纯合子（aa）抑制下位基因的表达。\n杂交后代比例为9:3:4（修改自9:3:3:1）。","chapterNo":6,"chapterTitle":"性状遗传的基本规律","source":"term_doc","answerStatus":"reference","qid":"TERM-0179"},{"term":"数量遗传与多基因性状","answer":"数量性状是由多个微效基因共同控制、表型呈现连续变异且显著受环\n境影响的性状。例如人类身高（160cm~190cm连续变化）\n多基因性状是由两个或以上基因共同调控的性状，其遗传基础本质上\n是\"多基因控制\"，但不必然表现为连续变异。\n所有数量性状都是多基因性状（由多基因+环境作用）。但多基因性\n状不一定是数量性状（若基因数少且互作强，可表现为质量性状）","chapterNo":6,"chapterTitle":"性状遗传的基本规律","source":"term_doc","answerStatus":"reference","qid":"TERM-0180"},{"term":"前导链","answer":"由于DNA 聚合酶只能催化5’→3’方向合成，所以在以3’→5’方\n向的母链为模板时，DNA沿5’→3’方向连续复制，复制速度较快，\n完成复制较早，称为前导链。在DNA复制时，前导链的复制是连续进\n行的。","chapterNo":7,"chapterTitle":"基因与基因组","source":"term_doc","answerStatus":"reference","qid":"TERM-0181"},{"term":"后随链","answer":"在以5’→3’方向的母链为模板合成3’→5’互补链时，由于不能\n按3’→5’方向进行，必须先按 5’→3’方向合成一系列较短的冈\n崎片段，然后在DNA连接酶作用下，众多的冈崎片段连接成完整的单\n链，该复制过程较复杂，完成时间较慢，称为后随链。","chapterNo":7,"chapterTitle":"基因与基因组","source":"term_doc","answerStatus":"reference","qid":"TERM-0182"},{"term":"冈崎片段","answer":"在以5’→3’方向的母链为模板合成3’→5’互补链时，由于不能\n按3’→5’方向进行，必须先按 5’→3’方向合成一系列较短的核\n苷酸片段，称为冈崎片段。然后在DNA连接酶的作用下，众多的冈崎\n片段连接成完整的单链。","chapterNo":7,"chapterTitle":"基因与基因组","source":"term_doc","answerStatus":"reference","qid":"TERM-0183"},{"term":"DNA复制","answer":"是指亲代DNA分子的双链解旋分开后，分别作为复制的模板，以四种\n脱氧核糖核苷酸作为底物，通过DNA聚合酶，依照碱基互补配对原则\n进行的DNA合成过程。","chapterNo":7,"chapterTitle":"基因与基因组","source":"term_doc","answerStatus":"reference","qid":"TERM-0184"},{"term":"半保留复制（2024 名词解释）","answer":"是一种双链DNA 的复制模型，指子代 DNA分子都保留了原来DNA分子\n中的一条链。(亲代DNA分子的双链解旋分开后，分别作为复制的模\n板，以四种脱氧核糖核苷酸作为底物，通过DNA聚合酶，依照碱基互\n补配对原则进行的DNA 合成过程。)","chapterNo":7,"chapterTitle":"基因与基因组","source":"term_doc","answerStatus":"reference","qid":"TERM-0185"},{"term":"基因","answer":"是控制生物性状的遗传物质的功能单位和结构单位，是有遗传效应的\n核酸片段。基因在染色体上呈线性排列，每个基因中可以含有成百上\n千个核苷酸。","chapterNo":7,"chapterTitle":"基因与基因组","source":"term_doc","answerStatus":"reference","qid":"TERM-0186"},{"term":"遗传信息","answer":"指生物为复制与自己相同的东西、由亲代传递给子代、或各细胞每次\n分裂时由细胞传递给细胞的信息，即碱基对的排列顺序。","chapterNo":7,"chapterTitle":"基因与基因组","source":"term_doc","answerStatus":"reference","qid":"TERM-0187"},{"term":"半不连续复制","answer":"DNA复制时，前导链以3’→5’链为模板进行连续复制，而后随链按\n5’→3’方向以冈崎片段不连续方式合成的。因此，称为半不连续复\n制。","chapterNo":7,"chapterTitle":"基因与基因组","source":"term_doc","answerStatus":"reference","qid":"TERM-0188"},{"term":"朊病毒/朊粒","answer":"阮粒是一种感染性蛋白质颗粒，它不是传递遗传信息的载体，也不能\n进行自我复制。","chapterNo":7,"chapterTitle":"基因与基因组","source":"term_doc","answerStatus":"reference","qid":"TERM-0189"},{"term":"DNA损伤修复","answer":"指在多种酶的作用下，生物细胞内的 DNA分子受到损伤后恢复结构的\n现象，这是生物体长期进化中获得的一种重要的安全保护机制。主要\n的损伤修复方式包括切除修复、错配修复、重组修复、易错修复、光\n复活修复等，最常见的是切除修复。","chapterNo":7,"chapterTitle":"基因与基因组","source":"term_doc","answerStatus":"reference","qid":"TERM-0190"},{"term":"切除修复","answer":"是指在一系列酶作用下，将DNA分子受损伤的部位切除，以另一条完\n整的单链作为模板合成被切除的部分，使DNA恢复正常结构的过程。\n主要过程如下：核酸内切酶识别DNA的损伤部位，并在了端作一切口，\n再在外切酶的作用下从5，端到3，端方向切除损伤；然后在DNA聚\n合酶的作用下，以损伤处相对应的互补链为模板合成新的 DNA单链片\n段以填补切除后留下的空隙：最后再在DNA连接酶的作用下将新合成\n的单链片段与原有的单链以磷酸二酯键相接而完成","chapterNo":7,"chapterTitle":"基因与基因组","source":"term_doc","answerStatus":"reference","qid":"TERM-0191"},{"term":"基因组","answer":"基因组是生物体遗传信息的完整集合，包含其发育、生存和繁殖所需\n的全部遗传指令。\n人类基因组\n人类基因组是指人的基因组，由23对染色体组成，其中包括22对体\n染色体、1条X染色体和1 条Y染色体。人类基因组含有约30亿个\nDNA碱基对，碱基对是以氢键相结合的两个含氮碱基，以胸腺嘧啶（T）、\n腺嘌呤（A）、胞嘧啶（C）和鸟嘌呤（G）四种碱基排列成碱基序列，\n其中A 与T之间由两个氢键连接，G与C 之间由三个氢键连接，碱基\n对的排列在DNA 中也只能是A 对T，G 对C。人类基因组有两层意义：\n遗传信息和遗传物质。","chapterNo":7,"chapterTitle":"基因与基因组","source":"term_doc","answerStatus":"reference","qid":"TERM-0192"},{"term":"结构基因组学（5 版新增）","answer":"是基因组学的一个分支学科，其核心目标是在基因组规模上，系统性\n地测定生物大分子（主要是蛋白质，也包括RNA和DNA）的三维结构，\n并利用这些结构信息来理解生物功能、进化关系和疾病机制。","chapterNo":7,"chapterTitle":"基因与基因组","source":"term_doc","answerStatus":"reference","qid":"TERM-0193"},{"term":"C值/C 值悖理（5 版新增）","answer":"C值指一个生物单倍体基因组的DNA总量。C值悖论指基因组大小（C\n值）与生物进化复杂性不相关甚至矛盾的现象。","chapterNo":7,"chapterTitle":"基因与基因组","source":"term_doc","answerStatus":"reference","qid":"TERM-0194"},{"term":"转座，转座因子（5 版新增）","answer":"转座指转座因子在基因组中改变自身位置的过程（从一位点移动到另\n一位点），甚至跳跃到另一染色体上。\n转座因子指基因组中可自主移动的DNA片段，又称“跳跃基因”","chapterNo":7,"chapterTitle":"基因与基因组","source":"term_doc","answerStatus":"reference","qid":"TERM-0195"},{"term":"基因沙漠（5 版新增）","answer":"基因沙漠指基因组中缺乏蛋白质编码基因的大片连续区域，如同基因\n组中的“荒漠”。","chapterNo":7,"chapterTitle":"基因与基因组","source":"term_doc","answerStatus":"reference","qid":"TERM-0196"},{"term":"线粒体夏娃（5 版新增）","answer":"通过追踪现存人类的线粒体突变，回溯到的一位女性共同祖先。她并\n非当时唯一女性，而是唯一成功延续至今的母系血脉的起点。其科学\n基础母系遗传：线粒体DNA仅由母亲传给后代。","chapterNo":7,"chapterTitle":"基因与基因组","source":"term_doc","answerStatus":"reference","qid":"TERM-0197"},{"term":"内含子","answer":"位于基因的DNA 序列中，在初始转录产物（前体mRNA）中存在，但\n在成熟的、具有功能的mRNA中被移除的片段。内含子本身通常不直\n接编码蛋白质的氨基酸序列。","chapterNo":7,"chapterTitle":"基因与基因组","source":"term_doc","answerStatus":"reference","qid":"TERM-0198"},{"term":"外显子","answer":"位于基因的DNA 序列中，在初始转录产物（前体mRNA）中存在，并\n且在成熟的mRNA 中得以保留的片段。外显子包含编码蛋白质氨基酸\n序列的信息（编码区），以及成熟mRNA 两端的非翻译区。","chapterNo":7,"chapterTitle":"基因与基因组","source":"term_doc","answerStatus":"reference","qid":"TERM-0199"},{"term":"基因突变","answer":"突变是基因在DNA序列、组成与结构上的异常改变，属于遗传物质的\n异常变异，广义的突变可以归为两类：小范围的“基因突变”与大尺\n度的“染色体畸变”基因突变专指发生在基因上的突变，根据对碱基\n类型、数量的影响可分为点突变和小片段的插入/缺失。","chapterNo":8,"chapterTitle":"遗传物质的突变","source":"term_doc","answerStatus":"reference","qid":"TERM-0200"},{"term":"点突变","answer":"狭义的点突变一般是指DNA。上仅涉及一个碱基的异常改变,包括单\n个碱基的替换插入或缺失。更严格的定义仅指单碱基替换。单碱基替\n换是最简单的一种突变,称为碱基置换，或者更确切地说，应该是碱\n基对置换，或者核苷酸对置换。碱基置换分为转换和颠换。","chapterNo":8,"chapterTitle":"遗传物质的突变","source":"term_doc","answerStatus":"reference","qid":"TERM-0201"},{"term":"同义突变","answer":"DNA链中某一个碱基被另一个所替换，由于密码子的简并性，如果这\n种替换的结果不影响其所编码的氨基酸，则这种突变称为同义突变。","chapterNo":8,"chapterTitle":"遗传物质的突变","source":"term_doc","answerStatus":"reference","qid":"TERM-0202"},{"term":"无义突变","answer":"当单个碱基置换导致出现终止密码子（UAG、UAA、UGA）时，肽链将\n提前终止合成，所产生的蛋白质大都失去活性或丧失正常功能，此种\n突变称为无义突变。","chapterNo":8,"chapterTitle":"遗传物质的突变","source":"term_doc","answerStatus":"reference","qid":"TERM-0203"},{"term":"移码突变","answer":"移码突变是指DNA链上插入或缺失1 个、2个甚至多个碱基（但非3\n个碱基或3的整数倍的碱基），导致在插入或缺失碱基部位以后的密\n码子顺序和组成发生相应改变由于原来的密码子移位，终止密码子常\n常推后或提前出现，结果造成新合成的肽链延长或缩短。","chapterNo":8,"chapterTitle":"遗传物质的突变","source":"term_doc","answerStatus":"reference","qid":"TERM-0204"},{"term":"终止密码突变","answer":"当DNA中一个终止密码发生突变成为编码氨基酸的密码子时，肽链的\n合成将不能正常终止。肽链将继续延长直至遇到下一个终止密码子，\n因而形成了延长的异常肽链，这种突变称为终止密码突变。","chapterNo":8,"chapterTitle":"遗传物质的突变","source":"term_doc","answerStatus":"reference","qid":"TERM-0205"},{"term":"染色体结构畸变","answer":"染色体的结构畸变指的是由于基因组序列和结构的大范围变动所导\n致的部分染色体增加减少、重排等异常改变,这种畸变往往会造成基\n因组中基因数目的增减、基因位置的改变,或者基因排列顺序的变化。","chapterNo":8,"chapterTitle":"遗传物质的突变","source":"term_doc","answerStatus":"reference","qid":"TERM-0206"},{"term":"缺失","answer":"染色体丢失了一个片段，导致这个片段上的基因也随之丢失。（\"猫\n叫综合征”）","chapterNo":8,"chapterTitle":"遗传物质的突变","source":"term_doc","answerStatus":"reference","qid":"TERM-0207"},{"term":"重复","answer":"一条染色体的某一片段出现两份或两份以上。","chapterNo":8,"chapterTitle":"遗传物质的突变","source":"term_doc","answerStatus":"reference","qid":"TERM-0208"},{"term":"倒位","answer":"同一染色体上某一个片段作180°的颠倒，导致染色体上基因顺序的\n重排。","chapterNo":8,"chapterTitle":"遗传物质的突变","source":"term_doc","answerStatus":"reference","qid":"TERM-0209"},{"term":"易位","answer":"一条染色体臂的一段移接到另一非同源染色体臂上。","chapterNo":8,"chapterTitle":"遗传物质的突变","source":"term_doc","answerStatus":"reference","qid":"TERM-0210"},{"term":"染色体数目畸变","answer":"染色体数目的改变一般源自细胞分裂中染色体分离的异常,包括染色\n体不分离和染色体丢失。例如同源染色体或姐妹染色单体不分离，或\n提前分离，或丢失，从而造成染色体数目的增加或减少。包括非整倍\n体变异和中整倍体变异。","chapterNo":8,"chapterTitle":"遗传物质的突变","source":"term_doc","answerStatus":"reference","qid":"TERM-0211"},{"term":"插入/缺失突变","answer":"插人/缺失突变一般特指基因组某个位点上碱基序列异常增加、异常\n减少，或者既有增加又有減少的情况。广义的插人/缺失突变也包括\n单个碱基的插入和单个碱基的缺失。研究发现，插入/缺失突变比碱\n基置换突变更常见。","chapterNo":8,"chapterTitle":"遗传物质的突变","source":"term_doc","answerStatus":"reference","qid":"TERM-0212"},{"term":"基本染色体组","answer":"一个物种的祖先种（基本种）中的染色体组称该物种的基本染色体组，\n又称染色体基数，记为x。这实际上指的是一套具有不同大小、形态、\n结构以及连锁基因的非同源染色体，相当于一套不能配对的染色体。\n由一套基本染色体组构成的细胞或个体称为一倍体或单元单倍体；由\n两套基本染色体组构成的细胞或个体称为二倍体，可记为2x；由三\n套或三套以上基本染色体组构成的细胞或个体则称为多倍体。","chapterNo":8,"chapterTitle":"遗传物质的突变","source":"term_doc","answerStatus":"reference","qid":"TERM-0213"},{"term":"基因型","answer":"即遗传（基因）组成，是指生物的遗传型，即控制性状的基因组合类\n型，也代表DNA（或RNA）上碱基排列的顺序。","chapterNo":9,"chapterTitle":"遗传性状的决定和形成——从基因型到","source":"term_doc","answerStatus":"reference","qid":"TERM-0214"},{"term":"表型","answer":"具有特定基因型的生物体，在一定环境条件下，所表现出来的性状特\n征的总和。其分子基础是不同的基因通过编码产生一系列不同功能的\n蛋白质来实现其独特的表型特征。因此表型是由基因型决定的。","chapterNo":9,"chapterTitle":"遗传性状的决定和形成——从基因型到","source":"term_doc","answerStatus":"reference","qid":"TERM-0215"},{"term":"基因","answer":"控制生物性状的遗传物质的功能单位和结构单位，通常是有遗传效应\n的DNA片段。","chapterNo":9,"chapterTitle":"遗传性状的决定和形成——从基因型到","source":"term_doc","answerStatus":"reference","qid":"TERM-0216"},{"term":"等位基因","answer":"在一对同源染色体的同一位置上的，控制着相对性状的基因。","chapterNo":9,"chapterTitle":"遗传性状的决定和形成——从基因型到","source":"term_doc","answerStatus":"reference","qid":"TERM-0217"},{"term":"基因文库","answer":"人工克隆基因的总称，广义的基因文库指来源于一种生物基因组的全\n部DNA克隆，理想情况下应含有这一基因组的全部DNA序列；狭义的\n基因文库有基因组文库和cDNA文库之分;基因文库中不同的DNA序列\n片段分别被克隆在适当的载体上，基因文库可用于研究基因的结构、\n功能和筛选基因工程目的基因等。","chapterNo":9,"chapterTitle":"遗传性状的决定和形成——从基因型到","source":"term_doc","answerStatus":"reference","qid":"TERM-0218"},{"term":"基因表达","answer":"通过DNA 的转录和翻译而产生蛋白质产物，或转录后直接产生RNA产\n物的过程。即遗传信息的转录和翻译过程。","chapterNo":9,"chapterTitle":"遗传性状的决定和形成——从基因型到","source":"term_doc","answerStatus":"reference","qid":"TERM-0219"},{"term":"转录","answer":"是指DNA 分子的双链解旋分开后，以一条链作为转录的模板，以四种\n核糖核苷酸作为底物，通过RNA聚合酶，依照碱基互补配对原则进行\n的RNA合成过程。","chapterNo":9,"chapterTitle":"遗传性状的决定和形成——从基因型到","source":"term_doc","answerStatus":"reference","qid":"TERM-0220"},{"term":"三联体密码","answer":"信使RNA 上由3 个碱基组合在一起的编码方式。除了线粒体等极少情\n况外，三联体密码是所有生物通用的。","chapterNo":9,"chapterTitle":"遗传性状的决定和形成——从基因型到","source":"term_doc","answerStatus":"reference","qid":"TERM-0221"},{"term":"翻译","answer":"在核糖体上，以mRNA 为模板，tRNA 为运载工具，合成具有一定氨基\n酸顺序的蛋白质的过程。是蛋白质生物合成过程中的第二步(转录为\n第一步)。","chapterNo":9,"chapterTitle":"遗传性状的决定和形成——从基因型到","source":"term_doc","answerStatus":"reference","qid":"TERM-0222"},{"term":"中心法则（2013年名词解释）","answer":"克里克提出将遗传信息的传递途径称为中心法则，包括遗传信息流从\nDNA传递给RNA,再从RNA传递给蛋白质的转录和翻译过程，以及遗传\n信息从DNA传递给DNA 的复制过程。后发现，某些病毒中RNA同样可\n以反过来决定DNA,为逆转录，在实验室中还可以使DNA直接翻译成\n蛋白质，是对“中心法则\"的补充和完善。","chapterNo":9,"chapterTitle":"遗传性状的决定和形成——从基因型到","source":"term_doc","answerStatus":"reference","qid":"TERM-0223"},{"term":"基因表达调控","answer":"基因调控是生物体内控制基因表达的机制，其一般是某一个体系在需\n要时被打开，主要发生在三个水平上，即DNA水平上的调控、转录控\n制和翻译控制，关键环节是转录水平的调控；微生物通过基因调控可\n以改变代谢方式以适应环境的变化，一般是短暂的和可逆的；多细胞\n生物的基因调控是细胞分化、形态发生和个体发育的基础，一般是长\n期的和不可逆的,是基因选择性表达的结果。","chapterNo":9,"chapterTitle":"遗传性状的决定和形成——从基因型到","source":"term_doc","answerStatus":"reference","qid":"TERM-0225"},{"term":"操纵子","answer":"存在于原核生物中，是指由在功能上彼此有关的几个结构基因和控制\n区组成的DNA片段，控制区包括启动子和操纵基因。","chapterNo":9,"chapterTitle":"遗传性状的决定和形成——从基因型到","source":"term_doc","answerStatus":"reference","qid":"TERM-0226"},{"term":"断裂基因","answer":"细胞内的结构基因并非全部由编码序列组成，而是在编码序列中间插\n入了无编码作用的碱基序列，这类基因称为断裂基因。断裂基因实质\n上就是由一系列交替存在的外显子和内含子构成的基因。","chapterNo":9,"chapterTitle":"遗传性状的决定和形成——从基因型到","source":"term_doc","answerStatus":"reference","qid":"TERM-0227"},{"term":"调节基因（2024年名词解释）","answer":"是指一类参与其他基因表达和调控的RNA和蛋白质的编码基因，通常\n处在受调节基因的上游。在乳糖操纵子模型中，当无乳糖存在时，调\n节基因编码的阻遏蛋白与操纵基因结合，使得RNA聚合酶不能与启动\n子结合，阻遏了下游结构基因的编码。","chapterNo":9,"chapterTitle":"遗传性状的决定和形成——从基因型到","source":"term_doc","answerStatus":"reference","qid":"TERM-0228"},{"term":"启动子","answer":"是指标志转录起始位点的一段短的核苷酸序列，RNA聚合酶在这一位\n点与DNA 接触并开始进行转录。","chapterNo":9,"chapterTitle":"遗传性状的决定和形成——从基因型到","source":"term_doc","answerStatus":"reference","qid":"TERM-0229"},{"term":"操纵基因（2023年名词解释）","answer":"是指DNA 上不编码任何蛋白质的一小段序列。在乳糖操纵子模型中，\n当无乳糖存在时，调节基因编码的阻遏蛋白与操纵基因结合，使得\nRNA聚合酶不能与启动子结合，阻遏了下游结构基因的编码。","chapterNo":9,"chapterTitle":"遗传性状的决定和形成——从基因型到","source":"term_doc","answerStatus":"reference","qid":"TERM-0230"},{"term":"结构基因","answer":"是指一类蛋白质和RNA 的编码基因。它的转录是在调节基因的产物—\n—阻遏蛋白的作用下，通过操纵子基因控制的。在乳糖操纵子模型中，\n当无乳糖存在时，调节基因编码的阻遏蛋白与操纵基因结合，使得\nRNA聚合酶不能与启动子结合，阻遏了下游结构基因的编码。","chapterNo":9,"chapterTitle":"遗传性状的决定和形成——从基因型到","source":"term_doc","answerStatus":"reference","qid":"TERM-0231"},{"term":"诱导酶","answer":"指只有在某些特定的物质或诱导物存在时，才能产生的酶。如大肠杆\n菌分解乳糖的酶。","chapterNo":9,"chapterTitle":"遗传性状的决定和形成——从基因型到","source":"term_doc","answerStatus":"reference","qid":"TERM-0232"},{"term":"组成酶","answer":"指与化学环境无关，无论某种特定物质是否存在，它们都可以不断地\n被合成的酶。如大肠杆菌分解葡萄糖的酶。","chapterNo":9,"chapterTitle":"遗传性状的决定和形成——从基因型到","source":"term_doc","answerStatus":"reference","qid":"TERM-0233"},{"term":"增强子","answer":"能增强真核基因转录的一类调节序列，离基因较远。","chapterNo":9,"chapterTitle":"遗传性状的决定和形成——从基因型到","source":"term_doc","answerStatus":"reference","qid":"TERM-0234"},{"term":"沉默子","answer":"不同于增强子，位于结构基因附近，能降低基因启动子的转录活性从\n而抑制该基因转录表达的DNA 序列。","chapterNo":9,"chapterTitle":"遗传性状的决定和形成——从基因型到","source":"term_doc","answerStatus":"reference","qid":"TERM-0235"},{"term":"转录因子","answer":"开启转录的调节蛋白，转录因子与RNA聚合酶II形成转录起始复合\n体，共同参与转录起始的过程。它包括能与基因上游的调节性DNA序\n列相结合从而激活基因转录的一类蛋白质——激活剂和其他蛋白因\n子。","chapterNo":9,"chapterTitle":"遗传性状的决定和形成——从基因型到","source":"term_doc","answerStatus":"reference","qid":"TERM-0236"},{"term":"内含子（2025年名词解释）","answer":"是指不能够转录为相应的mRNA，不能编码蛋白质的无编码作用的碱\n基序列，其阻断了基因的线性表达。与外显子交替排列构成断裂基因，\n在mRNA加工过程中被剪切掉。","chapterNo":9,"chapterTitle":"遗传性状的决定和形成——从基因型到","source":"term_doc","answerStatus":"reference","qid":"TERM-0237"},{"term":"外显子","answer":"是能够转录为相应mRNA，进而指导蛋白质合成，能被翻译成为蛋白\n质的区段，与内含子交替排列构成断裂基因，在mRNA 加工过程中被\n保存下来。","chapterNo":9,"chapterTitle":"遗传性状的决定和形成——从基因型到","source":"term_doc","answerStatus":"reference","qid":"TERM-0238"},{"term":"异位表达","answer":"是指基因在原本不表达的细胞中表达，即基因表达的时间和空间的模\n式发生变化的现象。例如，果蝇在原先长触角的部位长出了两条腿。","chapterNo":9,"chapterTitle":"遗传性状的决定和形成——从基因型到","source":"term_doc","answerStatus":"reference","qid":"TERM-0239"},{"term":"同源异形基因","answer":"突变后使器官异位表达的基因，称同源异形基因。同源异形基因在染\n色体上的排列顺序和体节特征结构的空间表达的顺序相对应。在体节\n形成后，同源异形基因决定每一节特有的器官结构的发生与形成。","chapterNo":9,"chapterTitle":"遗传性状的决定和形成——从基因型到","source":"term_doc","answerStatus":"reference","qid":"TERM-0240"},{"term":"癌基因","answer":"癌基因是控制细胞生长和分裂的正常基因，其突变能引起正常细胞癌\n变。可分为病毒癌基因和细胞癌基因两大类。\nb.病毒癌基因，编码病毒癌基因的主要有DNA病毒和RNA病毒，病毒\n癌基因能使宿主细胞发生恶性转化，形成肿瘤；\nc.细胞癌基因，即原癌基因，是存在于人或动物的正常基因组中，是\n细胞正常生长、分化所必需的，具有转变为癌基因潜力的正常基因。","chapterNo":9,"chapterTitle":"遗传性状的决定和形成——从基因型到","source":"term_doc","answerStatus":"reference","qid":"TERM-0241"},{"term":"抑癌基因","answer":"抑癌基因也称为肿瘤抑制基因。编码的蛋白抑制细胞生长，并阻止细\n胞癌变。每一种肿瘤抑制基因都有两个拷贝，只有当两个拷贝都丢失\n或失活后才使细胞失去对增殖的控制，引起细胞癌变。只要有一个拷\n贝是正常的，就能够正常调节细胞的周期。","chapterNo":9,"chapterTitle":"遗传性状的决定和形成——从基因型到","source":"term_doc","answerStatus":"reference","qid":"TERM-0242"},{"term":"表观遗传调控","answer":"表观遗传调控一般仅指DNA化学修饰和染色质结构与组蛋白修饰介\n导的基因表达调控机制。基因表达调控可以发生在基因表达过程中的\n任何阶段,其中转录是基因表达调控的核心与关键,据此可以把基因\n表达调控粗略地划分成转录调控和转录后调控两大层级。","chapterNo":9,"chapterTitle":"遗传性状的决定和形成——从基因型到","source":"term_doc","answerStatus":"reference","qid":"TERM-0243"},{"term":"RNA剪接","answer":"RNA剪接是指从DNA模板链转录出的最初转录产物中除去内含子，并\n将外显子连接起来形成一个连续的RNA分子的过程；不同的剪接方式，\n从同一个RNA转录物产生不同的成熟mRNA分子，从而翻译出不同的\n蛋白质，这种调控方式成为RNA的选择性剪接或可变剪接。","chapterNo":9,"chapterTitle":"遗传性状的决定和形成——从基因型到","source":"term_doc","answerStatus":"reference","qid":"TERM-0244"},{"term":"微mRNA 调控分子（microRNA）","answer":"为一类新的非常重要的基因表达调控分子。人类至少一半的基因都受\n到该类分子的调控。miRNA基因也是由RNA聚合酶II转录,产生miRNA\n前体(pre-miRNA),经初步加工后被转运到细胞质中,在胞质中再经过\nDicer酶切割,形成21~22bp的双链miRNA;随后其中的一条链被降解,\n余下的单链miRNA跟特定的蛋白质形成复合体,通过碱基互补配对的\n方式寻找mRNA并调控其表达，引起与其完全匹配的 mRNA降解，或者\n抑制与其不完全匹配的mRNA的翻译。","chapterNo":9,"chapterTitle":"遗传性状的决定和形成——从基因型到","source":"term_doc","answerStatus":"reference","qid":"TERM-0245"},{"term":"顺式作用元件","answer":"顺式作用元件是指位于编码基因两侧，可影响自身基因表达活性的\nDNA序列，它们通过与转录因子结合而调控基因转录的精确起始和转\n录效率。包括启动子、增强子、沉默子等。","chapterNo":9,"chapterTitle":"遗传性状的决定和形成——从基因型到","source":"term_doc","answerStatus":"reference","qid":"TERM-0246"},{"term":"肿瘤干细胞","answer":"是一群存在于某些肿瘤组织中的干细胞样细胞。","chapterNo":9,"chapterTitle":"遗传性状的决定和形成——从基因型到","source":"term_doc","answerStatus":"reference","qid":"TERM-0247"},{"term":"模板链/非编码链/反义链/负链（参与转录）（新增）","answer":"转录只发生在DNA双螺旋的一条链上。为RNA提供序列信息使其通过\n碱基互补配对完成转录的那条DNA链称为模板链，又称为编码链，反\n义链或负链。跟模板链反向互补的那条链由于跟 RNA序列相同，因此\n称为编码链，又称有义链或正链。每条染色体（DNA 分子）都包含了\n多个基因，模板链对于每一个基因而言都是固定的，但是不同的基因\n有可能采用不同的单链作为自己的模板链，也就是说，对于整条DNA\n分子而言，并没有模板链和非模板链的区分，具体哪条链是模板链因\n基因而异。","chapterNo":9,"chapterTitle":"遗传性状的决定和形成——从基因型到","source":"term_doc","answerStatus":"reference","qid":"TERM-0248"},{"term":"编码基因，信息RNA/编码 RNA（新增）","answer":"根据基因及其转录产生的RNA 分子的最终功能，可以将其粗略地分成\n两大类。\n一类基因转录的RNA仅仅作为信息分子用来指导蛋白质产生，它们属\n于有编码功能的基因，其RNA产物为一种信息RNA。mRNA就属于这类\nRNA分子。","chapterNo":9,"chapterTitle":"遗传性状的决定和形成——从基因型到","source":"term_doc","answerStatus":"reference","qid":"TERM-0249"},{"term":"非编码基因，非编码 RNA（新增）","answer":"另一类基因转录的RNA 则没有携带指导蛋白质产生的信息，而是RNA\n产物本身作为一种功能性分子直接发挥作用，因此这类基因称为非编\n码基因。其RNA产物称为非编码RNA。rRNA、tRNA 就属于非编码RNA\n分子。细胞中大多数基因都属于编码基因，均转录产生mRNA，但是，\n细胞中非编码的功能性RNA的数量却在总RNA中占有绝对优势。","chapterNo":9,"chapterTitle":"遗传性状的决定和形成——从基因型到","source":"term_doc","answerStatus":"reference","qid":"TERM-0250"},{"term":"初级转录物（新增）","answer":"为了跟最终形成的RNA 分子相区分，真核生物中直接以基因为模板转\n录出来的原始RNA转录物一般称为初级转录物。","chapterNo":9,"chapterTitle":"遗传性状的决定和形成——从基因型到","source":"term_doc","answerStatus":"reference","qid":"TERM-0251"},{"term":"多核糖体（新增）","answer":"无论是原核生物还是真核生物，一条mRNA分子上往往会结合多个核\n糖体同时进行翻译，这种由一条mRNA 及串联其上的多个核糖体共同\n组成的结构称为多核糖体。","chapterNo":9,"chapterTitle":"遗传性状的决定和形成——从基因型到","source":"term_doc","answerStatus":"reference","qid":"TERM-0252"},{"term":"模式生物","answer":"生物学研究离不开合适的实验材料，在长期的科研实践中，人们逐渐\n积累了一批体积小、世代周期短、易于在实验室养殖、易于进行实验\n操作的物种作为实验系统开研究，这类物种统称模式生物。其中酿酒\n酵母是单细胞真核生物的模式物种，拟南芥是研究被子植物的模式生\n物，而秀丽隐杆线虫、黑腹果蝇、斑鱼和小鼠是四种最有代表性的用\n于发育研究的模式动物。","chapterNo":9,"chapterTitle":"遗传性状的决定和形成——从基因型到","source":"term_doc","answerStatus":"reference","qid":"TERM-0253"},{"term":"真核生物三类RNA 聚合酶","answer":"RNA聚合酶I：合成大部分rRNA\nRNA聚合酶II：合成mrna\nRNA聚合酶III：合成trna 和5srRna","chapterNo":9,"chapterTitle":"遗传性状的决定和形成——从基因型到","source":"term_doc","answerStatus":"reference","qid":"TERM-0254"},{"term":"聚合酶链反应（PCR）","answer":"PCR是指一种在DNA聚合酶的催化下，以母链DNA为模板，以特定引\n物为延伸起点，通过高温变性、低温退火、适温延伸等步骤，体外复\n制出与模板DNA 互补的子链DNA的过程。是一项DNA体外合成放大技\n术，能快速特异地在体外扩增任何目的DNA。可用于基因分离克隆，\n序列分析，基因表达调控，基因多态性研究等许多方面。","chapterNo":10,"chapterTitle":"DNA技术及生物信息学分析简介","source":"term_doc","answerStatus":"reference","qid":"TERM-0255"},{"term":"DNA测序","answer":"指获得某一段DNA分子的4 种碱基排列顺序的过程。吉尔伯特和桑格\n因发明DNA测序方法而获得诺贝尔化学奖。吉尔伯特发明的是用化学\n裂解法测序,而桑格发明的是双脱氧链终止测序法,称桑格-库森法，\n简称桑格法。桑格法操作相对容易,是测序首选方法。","chapterNo":10,"chapterTitle":"DNA技术及生物信息学分析简介","source":"term_doc","answerStatus":"reference","qid":"TERM-0256"},{"term":"生物信息学（新增）","answer":"是在数据采集的基础上利用计算与信息科学的方法与手段(包括应用\n数学、计算机科学以及统计学等)挖掘、分析、解读生物分子、尤其\n是生物大分子信息的科学,是计算科学和生命科学交叉产生的一个分\n支科学。","chapterNo":10,"chapterTitle":"DNA技术及生物信息学分析简介","source":"term_doc","answerStatus":"reference","qid":"TERM-0257"},{"term":"蛋白质序列和结构分析（新增）","answer":"蛋白质的一级序列决定了蛋白质的二级、三级结构，最终决定蛋白的\n功能。即线性排列的氨基酸组成的蛋白质经过折叠形成特定的空间结\n构，才具有相应的生物化学活性和生物学功能。","chapterNo":10,"chapterTitle":"DNA技术及生物信息学分析简介","source":"term_doc","answerStatus":"reference","qid":"TERM-0258"},{"term":"DNA技术（新增）","answer":"指常用的涉及DNA操作的技术方法，如DNA 合成、DNA扩增、DNA序\n列测定。","chapterNo":10,"chapterTitle":"DNA技术及生物信息学分析简介","source":"term_doc","answerStatus":"reference","qid":"TERM-0259"},{"term":"读码框（新增）","answer":"也称为可读框，指从5’端翻译起始密码子（ATG）到终止密码子（TAA、\nTAG、TGA）的蛋白质编码碱基序列。","chapterNo":10,"chapterTitle":"DNA技术及生物信息学分析简介","source":"term_doc","answerStatus":"reference","qid":"TERM-0260"},{"term":"结构基因组学（新增）","answer":"采用重组DNA和测序技术对整个基因组DNA 进行序列测定，然后通过\n生物信息学手段组装出完整的基因组序列，同时通过分析所有的DNA\n序列，结合基因结构、表达、功能等信息对基因组进行注释与预测，\n勾画出所有基因在基因组上的分布与表达情况。","chapterNo":10,"chapterTitle":"DNA技术及生物信息学分析简介","source":"term_doc","answerStatus":"reference","qid":"TERM-0261"},{"term":"C值（新增）","answer":"一个物种的基因组大小和组成是相对固定的，相应地，一个物种的基\n因组DNA 含量也是相对恒定的，基因组DNA的含量通常称为该物种的\nC值。不同物种的基因组大小差异很大，不难理解，C 值一般会随着\n物种结构与功能的复杂程度而增加。","chapterNo":10,"chapterTitle":"DNA技术及生物信息学分析简介","source":"term_doc","answerStatus":"reference","qid":"TERM-0262"},{"term":"C值悖理（新增）","answer":"真核生物的基因组大小跟物种的复杂程度并不总是相关，不同物种之\n间的基因组含量在倍数上的差异远远超出其在形态结构方面的差异\n程度，有时亲缘关系很近、形态结构相似的物种之间的C值也会出现\n十倍甚至上百倍的差异，这种现象称为C 值悖理。例如，水稻和玉米\n拥有相似的基因数，但是玉米的基因组是水稻的6 倍。","chapterNo":10,"chapterTitle":"DNA技术及生物信息学分析简介","source":"term_doc","answerStatus":"reference","qid":"TERM-0263"},{"term":"基因克隆技术","answer":"DNA重组技术（又称基因/分子克隆、基因/遗传工程）：是指在离体\n条件下，通过人工操作，将不同来源的DNA重新组合，即有目的地将\n一个个体细胞（供体细胞）内的某特定的基因（目的基因）通过载体\n或其他手段送入受体细胞，构建成一个新功能DNA分子，并使它们在\n适当的细胞中增殖和表达的一种遗传学操作。目的是获得用一般方法\n难以获得的产品。","chapterNo":10,"chapterTitle":"DNA技术及生物信息学分析简介","source":"term_doc","answerStatus":"reference","qid":"TERM-0264"},{"term":"限制性内切核酸酶","answer":"限制性内切核酸酶是指一类在特定的DNA位点水解DNA分子骨架的磷\n酸二酯键，将完整的DNA分子切割成若干片段的酶。","chapterNo":10,"chapterTitle":"DNA技术及生物信息学分析简介","source":"term_doc","answerStatus":"reference","qid":"TERM-0265"},{"term":"黏性末端","answer":"指切割DNA后两条链上的断裂位置是交错的，但又是围绕一个轴线对\n称排列的，其结果产生两个互补的单链末端。","chapterNo":10,"chapterTitle":"DNA技术及生物信息学分析简介","source":"term_doc","answerStatus":"reference","qid":"TERM-0266"},{"term":"平齐末端","answer":"又称钝性末端，即在识别序列内同一位置上的核苷酸处进行切割，没\n有突出的单链的双链DNA分子末端。","chapterNo":10,"chapterTitle":"DNA技术及生物信息学分析简介","source":"term_doc","answerStatus":"reference","qid":"TERM-0267"},{"term":"DNA连接酶","answer":"DNA连接酶是一种能够催化DNA中相邻的3′-OH和5′-P末端之间\n形成磷酸二酯键并将这两段配对DNA 切口拼接起来的核酸酶。","chapterNo":10,"chapterTitle":"DNA技术及生物信息学分析简介","source":"term_doc","answerStatus":"reference","qid":"TERM-0268"},{"term":"逆转录酶","answer":"反转录酶是指从逆转录病毒中制备得到的，以DNA或RNA为模板，以\n具有3′-OH 的DNA 或RNA 为引物，以5′→3′方向聚合生成DNA链\n的酶。","chapterNo":10,"chapterTitle":"DNA技术及生物信息学分析简介","source":"term_doc","answerStatus":"reference","qid":"TERM-0269"},{"term":"载体","answer":"载体是一种可连接外源DNA片段并将其送入宿主细胞进行扩增或表\n达的运载工具，这种工具通常也是一个DNA分子。常见的克隆载体有\n质粒、噬菌体及人工染色体。基因表达载体至少要包括目的基因、标\n记基因、启动子、终止子、复制原点和限制酶切割位点。","chapterNo":10,"chapterTitle":"DNA技术及生物信息学分析简介","source":"term_doc","answerStatus":"reference","qid":"TERM-0270"},{"term":"质粒","answer":"质粒是一些在细菌中独立存在于其染色体之外、具有自我复制能力的\n小型双链环状DNA分子。只有酵母中的杀伤质粒是RNA分子。","chapterNo":10,"chapterTitle":"DNA技术及生物信息学分析简介","source":"term_doc","answerStatus":"reference","qid":"TERM-0271"},{"term":"花粉管通道法","answer":"花粉管通道法有多种操作方式。例如，可以用微量注射器将含目的基\n因的DNA 溶液直接注入子房中；可以在植物受粉后的一定时间，剪去\n柱头，将DNA溶液滴加在花柱切面上，使得目的基因借助花粉管通道\n进人胚囊。","chapterNo":10,"chapterTitle":"DNA技术及生物信息学分析简介","source":"term_doc","answerStatus":"reference","qid":"TERM-0272"},{"term":"农杆菌转化法","answer":"转化指目的基因进入受体细胞内，并且在受体细胞内维持稳定和表达\n的过程。转化作用，就可以使目的基因进入植物细胞。","chapterNo":10,"chapterTitle":"DNA技术及生物信息学分析简介","source":"term_doc","answerStatus":"reference","qid":"TERM-0273"},{"term":"功能基因组学","answer":"围绕已有的海量基因组序列信息，全面破解基因在生命活动中的内在\n作用和运动规律，在基因组水平上阐明DNA序列的功能，系统地认识\n各基因及蛋白质的功能和相互关联等，是后功能基因组学研究的主要\n内容。","chapterNo":10,"chapterTitle":"DNA技术及生物信息学分析简介","source":"term_doc","answerStatus":"reference","qid":"TERM-0274"},{"term":"细胞工程","answer":"指在细胞水平上的筛选或改造，获得具有商业价值的细胞株或细胞系，\n再通过规模培养，获得特殊商品的技术和过程；它包含有动物细胞工\n程和植物细胞工程两部分，它们都以细胞培养为主要过程和内容。","chapterNo":10,"chapterTitle":"DNA技术及生物信息学分析简介","source":"term_doc","answerStatus":"reference","qid":"TERM-0275"},{"term":"发酵工程","answer":"是指通过对微生物菌株的选择、培育或改造，对发酵罐和反应器的设\n计和对发酵工艺的改进，实现目标工程菌或细胞的规模化发酵培养，\n最终从发酵液或细胞中分离提取所需要的生物工程产品。","chapterNo":10,"chapterTitle":"DNA技术及生物信息学分析简介","source":"term_doc","answerStatus":"reference","qid":"TERM-0276"},{"term":"基因文库","answer":"大量的、代表某生物体整个基因组的DNA片段插入到载体DNA中，转\n化受体细胞后收集在一起作永久保存的遗传物质库。包括基因组文库\n和部分基因文库(如cDNA文库)。","chapterNo":10,"chapterTitle":"DNA技术及生物信息学分析简介","source":"term_doc","answerStatus":"reference","qid":"TERM-0277"},{"term":"基因治疗","answer":"向受体细胞中引人具有正常功能的基因，用以纠正或补偿基因的缺陷，\n或是利用引人基因以杀死体内的病原体或恶性细胞的一种治疗方法。\n(包括体细胞的基因治疗和生殖细胞的基因治疗。)","chapterNo":10,"chapterTitle":"DNA技术及生物信息学分析简介","source":"term_doc","answerStatus":"reference","qid":"TERM-0278"},{"term":"基因诊断","answer":"是利用现代分子生物学和分子遗传学的技术方法，直接检测基因结构\n及其表达水平是否正常，从而对疾病做出诊断的方法。","chapterNo":10,"chapterTitle":"DNA技术及生物信息学分析简介","source":"term_doc","answerStatus":"reference","qid":"TERM-0279"},{"term":"Ti质粒","answer":"Ti质粒是在根瘤土壤感菌细胞中存在的，独立于染色体之外能自我\n复制的小型双链环状DNA分子。其特定部位与植物核内DNA组合来表\n达信息，使植物细胞肿瘤化。","chapterNo":10,"chapterTitle":"DNA技术及生物信息学分析简介","source":"term_doc","answerStatus":"reference","qid":"TERM-0280"},{"term":"微卫星 DNA:","answer":"由1—4个核苷酸的重复单元串联而成，可长达几十个到几百个碱基\n对，在基因的间隔区和内含子等非编码区广泛存在的串联重复序列之\n一。(广泛分布于基因组中。其中富含A-T碱基对，是在研究DNA多\n态性标记过程中发现的。)","chapterNo":10,"chapterTitle":"DNA技术及生物信息学分析简介","source":"term_doc","answerStatus":"reference","qid":"TERM-0281"},{"term":"转基因生物","answer":"是指运用基因工程技术将人们需要的目的基因经过分离、重组后导入\n并整合到动物或植物的基因组中，所获得的重组外源基因能够获得的\n新的特征、特性并通过繁殖而将其传递给它们的后代的生物。","chapterNo":10,"chapterTitle":"DNA技术及生物信息学分析简介","source":"term_doc","answerStatus":"reference","qid":"TERM-0282"},{"term":"分子探针","answer":"是指一段带有检测标记，且顺序已知，能与目的基因互补的单链DNA\n或RNA片段，又称基因探针或核酸探针。","chapterNo":10,"chapterTitle":"DNA技术及生物信息学分析简介","source":"term_doc","answerStatus":"reference","qid":"TERM-0283"},{"term":"生物技术（2015、17、19、20 年名词解释）","answer":"指人们以现代生命科学为基础,结合其他基础科学的科学原理，采用\n先进的科学技术手段,按照预先的设计对生物体（包括微生物，动物\n细胞和植物细胞）进行改造或加工其组成部分（细胞器和酶）来为人\n类生产出所需产品或达到某种目的，从而服务于社会的技术。包括基\n因工程、蛋白质工程、酶工程、细胞工程等。","chapterNo":10,"chapterTitle":"DNA技术及生物信息学分析简介","source":"term_doc","answerStatus":"reference","qid":"TERM-0284"},{"term":"人工选择效应","answer":"人工选择的效应是自然选择的一个有用的佐证。人工选择的效应是指\n微小变异积累成显著变异，人们根据经济或观赏要求选择具有目标性\n状的个体作为亲本来繁育后代，经过连续的选择，培育对象就会发生\n巨大的变化，以至于和他们作为由来的野生物种很少相似，例如金鱼\n是由野生鲫鱼变异后人为选择而来的。","chapterNo":11,"chapterTitle":"演化理论和微演化","source":"term_doc","answerStatus":"reference","qid":"TERM-0285"},{"term":"基因频率（2020名词解释）","answer":"基因频率是指一个基因座位上的不同等位基因在群体中的频率，又称\n为等位基因频率。","chapterNo":11,"chapterTitle":"演化理论和微演化","source":"term_doc","answerStatus":"reference","qid":"TERM-0286"},{"term":"基因型频率","answer":"不同基因型的个体在全部个体中所占的比率。","chapterNo":11,"chapterTitle":"演化理论和微演化","source":"term_doc","answerStatus":"reference","qid":"TERM-0287"},{"term":"群体遗传结构","answer":"群体遗传结构是指群体中各种等位基因的频率，以及它们在各种基因\n型中的数量分布。","chapterNo":11,"chapterTitle":"演化理论和微演化","source":"term_doc","answerStatus":"reference","qid":"TERM-0288"},{"term":"理想群体","answer":"在理想群体中，世代之间群体的遗传结构保持不变。理想群体所具备\n的条件：\n①种群足够大；②和其他群体完全隔离，无基因交流；③没有突变；\n④个体间随机交配；⑤没有自然选择。","chapterNo":11,"chapterTitle":"演化理论和微演化","source":"term_doc","answerStatus":"reference","qid":"TERM-0289"},{"term":"基因流","answer":"是指同一物种的不同种群之间隔离的不完全，所导致的不同种群间不\n同程度的基因交流过程。","chapterNo":11,"chapterTitle":"演化理论和微演化","source":"term_doc","answerStatus":"reference","qid":"TERM-0290"},{"term":"近交","answer":"近交是指两个亲缘关系密切的个体之间的交配或配子的结合。其遗传\n效应是群体中纯合基因型的增多；近交本身没有改变基因频率，但是\n近交与自然选择协同作用会使隐性等位基因频率下降，降低群体的变\n异性和多样性；近交后代大多出现衰退现象:个体生活力低下，抗逆\n性减低，往往出现畸形，存活率与繁殖率下降。","chapterNo":11,"chapterTitle":"演化理论和微演化","source":"term_doc","answerStatus":"reference","qid":"TERM-0291"},{"term":"远交","answer":"远交是指亲缘关系相对较远的个体之间的相互交配。其遗传效应是增\n加群体的杂合性；杂合性的增加有助于保护基因库的多样性，并且某\n些杂合基因型还有超过显性纯合基因型的有利效应。","chapterNo":11,"chapterTitle":"演化理论和微演化","source":"term_doc","answerStatus":"reference","qid":"TERM-0292"},{"term":"适合度","answer":"适合度是指一个生物能存活并把它的基因传给下一代的能力，可以用\n相对增长率予以测度，适合度越大，个体成活的机会和繁殖成功的机\n会也越大，反之则相反。","chapterNo":11,"chapterTitle":"演化理论和微演化","source":"term_doc","answerStatus":"reference","qid":"TERM-0293"},{"term":"达尔文主义","answer":"达尔文创立的以自然选择学说为中心的生物进化理论，认为现代所有\n的生物都是从过去的生物进化而来的；进化是一个渐进的过程。","chapterNo":11,"chapterTitle":"演化理论和微演化","source":"term_doc","answerStatus":"reference","qid":"TERM-0294"},{"term":"同源器官（2018年名词解释）","answer":"不同物种某些器官的功能不同，但从它们的结构和发育可以看出它们\n来自共同祖先，称为同源器官。(例如人的上肢、马的前蹄、海豚的\n鳍肢、蝙蝠的翼手，功能不同，外部形态也有显著差别，但是它们有\n一个共同的来源，都来自原始陆生脊椎动物5趾型的的肢体。)","chapterNo":11,"chapterTitle":"演化理论和微演化","source":"term_doc","answerStatus":"reference","qid":"TERM-0295"},{"term":"同功器官（2018年名词解释）","answer":"指在功能上相同，有时形状也相似，但其来源与基本结构均不同的器\n官。(如鱼鳃与陆栖脊椎动物的肺，均为呼吸器官，但鱼鳃鳃丝来自\n外胚层，而肺来自内胚层。)","chapterNo":11,"chapterTitle":"演化理论和微演化","source":"term_doc","answerStatus":"reference","qid":"TERM-0296"},{"term":"古生物学","answer":"是研究地质历史时期生物的发生、发展、分类、演化、分布等规律的\n科学，它的研究对象是保存在地层中的古代生物的遗体、遗迹或遗物\n——化石。","chapterNo":11,"chapterTitle":"演化理论和微演化","source":"term_doc","answerStatus":"reference","qid":"TERM-0297"},{"term":"胚胎学","answer":"是研究动植物的胚胎形成和发育过程的科学，叙述怎样从一个受精卵\n发育成胚胎，从而了解各种动植物发育的特点和规律的生物学分支学\n科。\n(也可广义地理解为研究精子、卵子的发生、成熟和受精，以及受精\n卵发育到成体的过程的学科。)","chapterNo":11,"chapterTitle":"演化理论和微演化","source":"term_doc","answerStatus":"reference","qid":"TERM-0298"},{"term":"比较解剖学","answer":"是对各类脊椎动物的器官和系统进行解剖和比较研究的科学。(在研\n究过程中，也根据古脊椎动物的化石找到器官的同功或同源的依据，\n从而阐明脊椎动物各类别间的系统演化关系。为生物进化理论提供证\n据。)","chapterNo":11,"chapterTitle":"演化理论和微演化","source":"term_doc","answerStatus":"reference","qid":"TERM-0299"},{"term":"生存斗争","answer":"生物个体(同种或异种的)之间的相互斗争，以及生物与无机自然条件\n(如干旱、寒冷)之间的斗争，赖以维持个体生存并繁衍种族的自然现\n象。","chapterNo":11,"chapterTitle":"演化理论和微演化","source":"term_doc","answerStatus":"reference","qid":"TERM-0300"},{"term":"自然选择（2013、15、17年填空题）（2013名词解释）","answer":"生物群体由于存在可遗传变异和繁殖过剩，因此群体的个体之间存在\n生存斗争，最终具有有益性状的个体将获得更多存活和生存的机会，\n即适者生存。这一过程就是自然选择。","chapterNo":11,"chapterTitle":"演化理论和微演化","source":"term_doc","answerStatus":"reference","qid":"TERM-0301"},{"term":"物种","answer":"简称“种”。在有性生殖的生物中，物种是互交繁殖的自然群体一个\n物种和其他物种在生殖上互相隔离。在无性生殖的生物中，物种是具\n有一定的形态特征和生理特征以及一定的自然分布区的生物类群。是\n生物分类的基本单位。","chapterNo":11,"chapterTitle":"演化理论和微演化","source":"term_doc","answerStatus":"reference","qid":"TERM-0302"},{"term":"小演化","answer":"又称微演化，是指一个物种内的进化现象。(它是在以世代为单位的\n生物学时间尺度里发生的进化事件，人们可以对它进行直接观测，可\n以用实验的方法探索其进化的机制和规律。)","chapterNo":11,"chapterTitle":"演化理论和微演化","source":"term_doc","answerStatus":"reference","qid":"TERM-0303"},{"term":"大演化","answer":"又称宏演化，是指物种和物种以上的高级分类群的进化现象。(它是\n在地质时间尺度里发生的进化事件，人们不能对它进行直接观测，主\n要依靠化石记录、形态解剖学方面的比较、DNA生物大分子的比较等\n方法来探索其进化的机制和规律。)","chapterNo":11,"chapterTitle":"演化理论和微演化","source":"term_doc","answerStatus":"reference","qid":"TERM-0304"},{"term":"哈迪-温伯格平衡（2013、2014名词解释）","answer":"对于一个大且随机交配的种群，基因频率和基因型频率在没有迁移、\n突变和选择的条件下会保持不变。","chapterNo":11,"chapterTitle":"演化理论和微演化","source":"term_doc","answerStatus":"reference","qid":"TERM-0305"},{"term":"遗传漂变（2025填空）/（2013名词解释）","answer":"基因频率在小群体里随机增减的现象。一般情况下，种群的生物个体\n的数量越少，种群中基因就越容易发生遗传漂变。","chapterNo":11,"chapterTitle":"演化理论和微演化","source":"term_doc","answerStatus":"reference","qid":"TERM-0306"},{"term":"基因库","answer":"是一种生物群体全部遗传基因的集合，其中每个个体所含的基因只是\n基因库的一部分。基因库它决定了下一代的遗传性状。","chapterNo":11,"chapterTitle":"演化理论和微演化","source":"term_doc","answerStatus":"reference","qid":"TERM-0307"},{"term":"现代综合论(综合进化论):","answer":"又称为现代达尔文主义，它是在达尔文的自然选择学说、基因学说以\n及群体遗传学的基础上，结合生命科学其他分支学科的新成就而发展\n起来的。它认为进化是在群体(种群)中实现的，进化的原料是突变，\n生物类型改变的遗传根据在于种群中基因频率的改变，通过突变和自\n然选择的综合作用，就可以导致生物新类型的产生。","chapterNo":11,"chapterTitle":"演化理论和微演化","source":"term_doc","answerStatus":"reference","qid":"TERM-0308"},{"term":"种群遗传学","answer":"群体遗传学是研究群体的遗传结构及其变化规律的学科，研究群体中\n基因的分布、基因频率和基因型频率的维持和变化。其研究对象是生\n物群体，它是由同一物种组成的较大的有性繁殖群体。群体内的个体\n间是随机交配的，遵循孟德尔遗传规律。","chapterNo":11,"chapterTitle":"演化理论和微演化","source":"term_doc","answerStatus":"reference","qid":"TERM-0309"},{"term":"选择压","answer":"是指基因对表型产生的效应。某些效应对生物体的生存和生殖是有利\n的，称为正选择压；另外的一些效应是不利的，称为负选择压。一个\n特定的基因频率在世代之间是增加还是降低，取决于它的正选择压之\n和是大于还是小于负选择压之和，与环境条件有很大关系。","chapterNo":11,"chapterTitle":"演化理论和微演化","source":"term_doc","answerStatus":"reference","qid":"TERM-0310"},{"term":"协同进化","answer":"两个相互作用的物种在进化过程中发展的相互适应的共同进化。一个\n物种由于另一物种影响而发生遗传进化的进化类型。例如一种植物由\n于食草昆虫所施加的压力而发生遗传变化，这种变化又导致昆虫发生\n遗传性变化。","chapterNo":11,"chapterTitle":"演化理论和微演化","source":"term_doc","answerStatus":"reference","qid":"TERM-0311"},{"term":"稳定性选择","answer":"稳定选择是自然选择的一种类型。选择的部位为中间类型，淘汰的部\n位为两个极端类型，选择的结果使生物类型保持相对稳定。例如有人\n在马铃薯叶中发现，能过冬的是那些常态型个体，而变异较大的个体\n都容易在越冬中死亡。","chapterNo":11,"chapterTitle":"演化理论和微演化","source":"term_doc","answerStatus":"reference","qid":"TERM-0312"},{"term":"单向选择(定向选择):","answer":"单向选择是自然选择的一种类型。选择的部位为变异曲线的一个尾部，\n淘汰的部位为变异曲线的另一个尾部，选择的结果使变异曲线的均值\n稳定增高。例如桦尺蛾工业黑化现象。","chapterNo":11,"chapterTitle":"演化理论和微演化","source":"term_doc","answerStatus":"reference","qid":"TERM-0313"},{"term":"分裂性选择","answer":"分裂性选择是自然选择的一种类型。选择的部位为两个极端类型，淘\n汰的部位为中间常态类型，选择的结果使中间类型频率降低，两个极\n端类型各出现一个峰值。例如美国卡茨基尔山有轻巧型和粗壮型两种\n狼。","chapterNo":11,"chapterTitle":"演化理论和微演化","source":"term_doc","answerStatus":"reference","qid":"TERM-0314"},{"term":"趋同演化","answer":"两种亲缘关系很远的物种有时会具有非常相似的外观和行为，这种相\n似性不是由它们之间的同源性造成的，而是由于它们在各自的演化过\n程中有相似的演化趋势。这种现象称为趋同演化。","chapterNo":11,"chapterTitle":"演化理论和微演化","source":"term_doc","answerStatus":"reference","qid":"TERM-0315"},{"term":"同功器官","answer":"同功器官指在功能上相同，有时形状也相似，但其来源和基本结构均\n不同的器官。例如蝶翼与鸟翼均为飞翔器官，但蝶翼是膜状结构，由\n皮肤扩展形成，而鸟翼是脊椎动物前肢形成，内有骨骼外有羽毛。","chapterNo":11,"chapterTitle":"演化理论和微演化","source":"term_doc","answerStatus":"reference","qid":"TERM-0316"},{"term":"中性演化理论（新增）","answer":"中性突变：指对生物体的生存和繁殖既非有利也非不利，而是中性的，\n因而称为中性突变；这些突变的基因在种群中的频率由突变率和遗传\n漂变而定，甚至与种群的大小都没有关系。","chapterNo":11,"chapterTitle":"演化理论和微演化","source":"term_doc","answerStatus":"reference","qid":"TERM-0317"},{"term":"恐龙起源假说（新增）","answer":"是一种关于鸟类起源的学说，该学说认为小型兽脚类恐龙是鸟类祖先。\n中国科学家在中国发现了大量带羽毛的恐龙和早期鸟类的化石，对这\n些化石的研究得出了一个鸟类演化谱系，支持了该学说","chapterNo":11,"chapterTitle":"演化理论和微演化","source":"term_doc","answerStatus":"reference","qid":"TERM-0318"},{"term":"冠群（新增）","answer":"是系统发生重建研究中的一个术语，定义为最近共同祖先及其衍生的\n所有后代（包括现存和已经灭绝的所有成员）所组成的一个单系类群。","chapterNo":11,"chapterTitle":"演化理论和微演化","source":"term_doc","answerStatus":"reference","qid":"TERM-0319"},{"term":"选择系数（新增）","answer":"可以理解为被淘汰的概率，其范围为0~1，它与适合度的关系是s=1-f。\n适合度和选择系数都是一种相对的概念，是两种或两种以上表型或基\n因型相比较的结果，用来定量地描述不同表型或基因型在自然选择作\n用下对特定环境适应的程度。","chapterNo":11,"chapterTitle":"演化理论和微演化","source":"term_doc","answerStatus":"reference","qid":"TERM-0320"},{"term":"同源蛋白质","answer":"在不同的生物类群中，行使相同或相似的功能，并具有明显相似的氨\n基酸序列的蛋白质，称为同源蛋白质，可通过比较同源蛋白质的相似\n和差别程度，判定生物亲缘关系的远近。\n细胞色素c是一种在生物氧化过程中起电子传递作用的蛋白质，多种\n真核生物的细胞色素c 的氨基酸序列很相似，从分子层次上说明有共\n同祖先。人类和黑猩猩细胞色素c 的氨基酸序列完全相同。","chapterNo":11,"chapterTitle":"演化理论和微演化","source":"term_doc","answerStatus":"reference","qid":"TERM-0321"},{"term":"物种","answer":"在有性生殖的生物中，物种是互交繁殖的自然群体。同一物种具有共\n同基因库，与其他类群有生殖隔离。物种是生物分类和宏进化的基本\n单位，物种之间在空间上不连续，在时间上是连续的。","chapterNo":12,"chapterTitle":"物种形成与灭绝","source":"term_doc","answerStatus":"reference","qid":"TERM-0322"},{"term":"隔离：","answer":"是指在自然界中生物不能自由交配或交配后不能产生可育后代的现\n象。(隔离是生物进化的重要因素，尤其对物种形成起着重要作用；","chapterNo":12,"chapterTitle":"物种形成与灭绝","source":"term_doc","answerStatus":"reference","qid":"TERM-0323"},{"term":"地理隔离","answer":"同种群的基因库发生改变，形成生殖隔离，导致新物种的形成。","chapterNo":12,"chapterTitle":"物种形成与灭绝","source":"term_doc","answerStatus":"reference","qid":"TERM-0324"},{"term":"邻地种形成","answer":"初始种群的地理分布区相邻接，种群间的个体在边界区有某种程度的\n基因交流，但最终仍导致新种的产生。","chapterNo":12,"chapterTitle":"物种形成与灭绝","source":"term_doc","answerStatus":"reference","qid":"TERM-0325"},{"term":"同地种形成","answer":"初始种群的地理分布区相重叠，没有地理上的隔离，这种情况下的新\n种产生就是同地种形成。","chapterNo":12,"chapterTitle":"物种形成与灭绝","source":"term_doc","answerStatus":"reference","qid":"TERM-0326"},{"term":"异地种形成","answer":"初始种群的地理分布区完全隔开、互不重叠，这种情况下的新种形成\n就是异地种形成。","chapterNo":12,"chapterTitle":"物种形成与灭绝","source":"term_doc","answerStatus":"reference","qid":"TERM-0327"},{"term":"杂种不活性","answer":"即杂种合子不能发育或不能发育到性成熟而死亡。例如牛、蛙的卵和\n豹蛙的精子能融合成合子，还能发育一段时间，但不久就死亡。","chapterNo":12,"chapterTitle":"物种形成与灭绝","source":"term_doc","answerStatus":"reference","qid":"TERM-0328"},{"term":"杂种不育性","answer":"即杂种合子能发育，个体能达到性成熟且是强壮，但却是不育的。例\n如马和驴产生后代骡，但骡是不育的，所以马和驴的基因库仍然是隔\n离的。","chapterNo":12,"chapterTitle":"物种形成与灭绝","source":"term_doc","answerStatus":"reference","qid":"TERM-0329"},{"term":"杂种破落","answer":"即第一代杂种能存活而且能育，但当这些杂种彼此间交配或同任一亲\n本交配，其子代却是衰弱的或者不育的。例如属于不同物种的棉花，\n能杂交并产生一代能育的后代，但在在下一代就出现破落，在种子阶\n段，杂种就死亡，或者生长出衰落而残缺的植株。","chapterNo":12,"chapterTitle":"物种形成与灭绝","source":"term_doc","answerStatus":"reference","qid":"TERM-0330"},{"term":"平行物种形成/并行物种形成","answer":"同一物种的后裔在不同地方彼此独立地形成具有相似适应性状的物\n种的现象。例如，不同湖中的丽鱼有相似的形态结构。","chapterNo":12,"chapterTitle":"物种形成与灭绝","source":"term_doc","answerStatus":"reference","qid":"TERM-0331"},{"term":"生态位","answer":"生态位是指物种利用群落中各种资源的总和，以及该物种与群落中其\n他物种相互关系的总和。物种利用群落中各种资源的总和，以及该物\n种与群落中其他物种相互关系的总和。表示物种在群落中的地位、作\n用和重要性。一个物种按其生理上的要求及所需的资源可能占领的全\n部生态位，实际上由于种间竞争实际，生态位比基本生态位要窄。","chapterNo":12,"chapterTitle":"物种形成与灭绝","source":"term_doc","answerStatus":"reference","qid":"TERM-0332"},{"term":"物种灭绝","answer":"广义的定义即当物种的最后一个个体死亡即标志着该物种的灭绝；狭\n义的定义即在过去50年里，在野外再也没有发现这个物种的个体。\n物种灭绝是内因和外因共同作用。外因可能由地球演变引起，内因可\n能由遗传多样性严重降低引起。","chapterNo":12,"chapterTitle":"物种形成与灭绝","source":"term_doc","answerStatus":"reference","qid":"TERM-0333"},{"term":"基因库","answer":"一个种群中全部个体所含有的全部基因叫做这个种群的基因库，它决\n定下一代的遗传性状。在一个种群基因库中，某个基因占全部等位基\n因数的比值，称为基因频率。","chapterNo":12,"chapterTitle":"物种形成与灭绝","source":"term_doc","answerStatus":"reference","qid":"TERM-0334"},{"term":"点断平衡模式","answer":"认为新种只能通过线系分支产生，只能以跳跃的方式快速形成；新种\n一旦形成就处于保守或进化停滞状态，直到下一次物种形成事件发生\n之前，表型上都不会有明显变化；进化是跳跃与停滞相间，不存在匀\n速、平滑、渐变的进化。","chapterNo":12,"chapterTitle":"物种形成与灭绝","source":"term_doc","answerStatus":"reference","qid":"TERM-0335"},{"term":"中性突变","answer":"对生物存活和生殖没有影响的突变。大部分对种群的遗传结构与进化\n有贡献的分子突变在自然选择的意义上都是中性或近中性的，因而自\n然选择对这些突变并不起作用；中性的进化是通过随机漂移，或被固\n定在种群中，或消失。","chapterNo":13,"chapterTitle":"生物进化与宏演化","source":"term_doc","answerStatus":"reference","qid":"TERM-0336"},{"term":"点断平衡论","answer":"从古生物学研究中提出的一个进化学说。认为新种只能通过线系分支\n产生，只能以跳跃的方式快速形成；新种一旦形成就处于保守或进化\n停滞状态，直到下一次物种形成事件发生之前，表型上都不会有明显\n变化；进化是跳跃与停滞相间，不存在匀速、平滑、渐变的进化。","chapterNo":13,"chapterTitle":"生物进化与宏演化","source":"term_doc","answerStatus":"reference","qid":"TERM-0337"},{"term":"常规绝灭","answer":"指生命史中各个时期都以一定的规模、经常性地发生的绝灭，表现为\n各分类群中部分物种的替代，即新种的产生和某些已有物种的消失。\n速率都要大大超过常规绝灭。在每一次大的集群性灭绝之后，接踵而\n至的往往是一次新的生物多样性的爆发。","chapterNo":13,"chapterTitle":"生物进化与宏演化","source":"term_doc","answerStatus":"reference","qid":"TERM-0338"},{"term":"趋同进化","answer":"两种或两种以上亲缘关系很远的生物，如果生活在同一类型的环境中，\n从而产生功能相同且形态相似的结构，以适应相同的条件。","chapterNo":13,"chapterTitle":"生物进化与宏演化","source":"term_doc","answerStatus":"reference","qid":"TERM-0339"},{"term":"趋异进化","answer":"又称为分歧进化，是指有些生物虽然同出一源，但由于生活在不同的\n环境中，有着不同的进化趋势，某些方面彼此变得很不相同的现象。\n趋异进化是分化式进化的基本方式，是生物多样化的基础。","chapterNo":13,"chapterTitle":"生物进化与宏演化","source":"term_doc","answerStatus":"reference","qid":"TERM-0340"},{"term":"适应辐射","answer":"一个祖先物种适合多种不同的环境，向着各种不同的方向发展而分化\n成多个在形态、生理和行为上不相同的种，形成一个同源的辐射状的\n进化系统，这种多方向的趋异称为适应辐射。","chapterNo":13,"chapterTitle":"生物进化与宏演化","source":"term_doc","answerStatus":"reference","qid":"TERM-0341"},{"term":"平行进化","answer":"亲缘关系很近的生物各自适应于相似的生活环境而独立发展成形态\n上相似的进化现象。(补充：平行进化与趋同进化不易区分，一般地\n说，两条线系比较，若后裔之间的相似程度大于祖先之间的相似程度，\n则属趋同；若后裔之间的相似程度与祖先之间相似程度大体一致，则\n属平行。平行进化所导致的相似性既是同源的，又是同功的。)","chapterNo":13,"chapterTitle":"生物进化与宏演化","source":"term_doc","answerStatus":"reference","qid":"TERM-0342"},{"term":"内共生学说","answer":"是关于真核细胞的一些细胞器起源的一种学说。该学说认为真核生物\n的线粒体和叶绿体是以内共生方式发展起来的。\n(该学说这样描述线粒体的起源：一种需氧的原核生物被某种厌氧原\n核生物吞入胞内，在进化过程中，吞食者与被吞食者之间发生了共生\n的关系，逐渐融合为一体，被吞食的原核生物演化为线粒体)按此学\n说，线粒体来自吞入的需氧的细菌，叶绿体来自吞入的蓝藻，这样就\n出现了真核细胞。内共生学说的一个主要依据是真核生物的线粒体和\n叶绿体都有自主性的活动，它们的DNA为环状，它们的核糖体为70s,\n这些都是和细菌、蓝藻相似的。","chapterNo":13,"chapterTitle":"生物进化与宏演化","source":"term_doc","answerStatus":"reference","qid":"TERM-0343"},{"term":"联适应","answer":"是指器官通过功能的变化所产生的对环境的适应。在联适应过程中，\n自然选择可能使结构变得更好地适应新的功能。(例如，从猿的力量\n型抓握到人的灵巧型抓握就是一种联适应。)","chapterNo":13,"chapterTitle":"生物进化与宏演化","source":"term_doc","answerStatus":"reference","qid":"TERM-0344"},{"term":"分子进化中性学说","answer":"日本人木村资生根据分子生物学的研究，主要是根据核酸、蛋白质中\n的核苷酸及氨基酸的置换速率，以及这些置换所造成的核酸及蛋白质\n分子的改变并不影响生物大分子的功能等事实，提出了分子进化中性\n学说。中性突变指对生物存活和生殖没有影响的突变，大部分对种群\n的遗传结构与进化有贡献的分子突变在自然选择的意义上都是中性\n或近中性的，因而自然选择对这些突变并不起作用；中性的进化是通\n过随机漂移，或被固定在种群或消失。","chapterNo":13,"chapterTitle":"生物进化与宏演化","source":"term_doc","answerStatus":"reference","qid":"TERM-0345"},{"term":"建立者效应(奠基者效应、创始者效应、始祖效应、定殖民者效","answer":"应)\n是遗传漂变的一种形式。\n(1)小种群中的几个或几十个个体迁移到它处定居下来，与原种群隔\n离开来，自行繁殖形成新的种群，由于有些等位基因没有带出来，导\n致新种群与原种群的基因频率的差异。\n(2)新种群的基因频率取决于建立者，即分离出来的几个或几十个个\n体。\n(3)意义：通过自然选择，有可能形成新物种。","chapterNo":13,"chapterTitle":"生物进化与宏演化","source":"term_doc","answerStatus":"reference","qid":"TERM-0346"},{"term":"化石","answer":"是先前生活的生物被保存在地层中的遗留物或者它的印迹，如动物的\n骨骼和牙齿、软体动物的壳、植物的树干都可能成为化石。","chapterNo":13,"chapterTitle":"生物进化与宏演化","source":"term_doc","answerStatus":"reference","qid":"TERM-0347"},{"term":"同源蛋白质","answer":"不同物种中具有相同或相似功能并具有明显相似的氨基酸序列的蛋\n白质。例如，通过细胞色素C 我们研究发现，人和猩猩的细胞色素C\n的氨基酸序列完全一样，说明人和猩猩的亲缘关系最近。","chapterNo":13,"chapterTitle":"生物进化与宏演化","source":"term_doc","answerStatus":"reference","qid":"TERM-0348"},{"term":"分子钟","answer":"DNA中核苷酸或蛋白质中氨基酸置换的数目与所研究物种间的分歧时\n间接近正线性关系，进而将分子水平的这种恒速变异称为“分子钟”。\nDNA、蛋白质等生物大分子中性突变相对恒定的速率起了分子钟的作\n用。例如，利用分子钟可揭示大熊猫与熊、小熊猫之间的演化关系。","chapterNo":13,"chapterTitle":"生物进化与宏演化","source":"term_doc","answerStatus":"reference","qid":"TERM-0349"},{"term":"水平进化","answer":"水平进化是指生物多样性增加，但其结构的复杂性并没有显著变化的\n进化。例如，加拉帕戈斯群岛的地雀。","chapterNo":13,"chapterTitle":"生物进化与宏演化","source":"term_doc","answerStatus":"reference","qid":"TERM-0350"},{"term":"垂直进化","answer":"垂直进化是指一些高级分类群特征的出现，如真核细胞细胞器的起源、\n两栖类呼吸器官的出现等，导致生物结构呈复杂性增长的进化。","chapterNo":13,"chapterTitle":"生物进化与宏演化","source":"term_doc","answerStatus":"reference","qid":"TERM-0351"},{"term":"分支系统学/支序分类学","answer":"法国昆虫学家亨尼希创立的支序分类学认为，要构建一个系统发育系\n统，必须考量物种间(或类群间)，在系统发育上，互相接近的相对程\n度，又称为共祖近度。","chapterNo":13,"chapterTitle":"生物进化与宏演化","source":"term_doc","answerStatus":"reference","qid":"TERM-0352"},{"term":"共祖近度","answer":"法国昆虫学家亨尼希创立的支序分类学认为，要构建一个系统发育系\n统，必须考量物种间(或类群间)，在系统发育上，互相接近的相对程\n度，又称为共祖近度。","chapterNo":13,"chapterTitle":"生物进化与宏演化","source":"term_doc","answerStatus":"reference","qid":"TERM-0353"},{"term":"衍征","answer":"一个物种的部分个体，经过异域的或同域的物种形成过程，产生的新\n物种的新的衍生性状。","chapterNo":13,"chapterTitle":"生物进化与宏演化","source":"term_doc","answerStatus":"reference","qid":"TERM-0354"},{"term":"祖征","answer":"产生的新物种所保留的原有性状。","chapterNo":13,"chapterTitle":"生物进化与宏演化","source":"term_doc","answerStatus":"reference","qid":"TERM-0355"},{"term":"共同衍征","answer":"在演化生物学中，一种两个或两个以上终端分类单元共有及从其最近\n共同祖先承袭的衍生性状。","chapterNo":13,"chapterTitle":"生物进化与宏演化","source":"term_doc","answerStatus":"reference","qid":"TERM-0356"},{"term":"单系群","answer":"是指通过分析共同衍征构建的类群，每一个物种分支都有一个共同祖\n先，一个包括所有祖先和祖先后代的类群。","chapterNo":13,"chapterTitle":"生物进化与宏演化","source":"term_doc","answerStatus":"reference","qid":"TERM-0357"},{"term":"并系群","answer":"是指依据共同祖征构建的类群。通过一些共同祖先逐步分支产生的一\n些物种只能并列的放在一个类群。此类群中的成员皆拥有共同祖先，\n但该群中并不包含此共同祖先的所有后代。","chapterNo":13,"chapterTitle":"生物进化与宏演化","source":"term_doc","answerStatus":"reference","qid":"TERM-0358"},{"term":"复系群","answer":"又称多系群，是指依据趋同现象构建的类群。类群中包含有系统关系\n甚远的物种。该分类群并不包含其所有成员的最近共同祖先。","chapterNo":13,"chapterTitle":"生物进化与宏演化","source":"term_doc","answerStatus":"reference","qid":"TERM-0359"},{"term":"分子系统学","answer":"是指通过比较不同物种的同源蛋白质、DNA、RNA的序列，甚至通过\n比较它们的基因组，来判断它们之间系统发育关系的远近，构建系统\n发育系统的学科。支序分类学和分子系统学使用的方法已经成为构建\n系统发育系统的两个主要方法。","chapterNo":13,"chapterTitle":"生物进化与宏演化","source":"term_doc","answerStatus":"reference","qid":"TERM-0360"},{"term":"原核生物（2014年名词解释）","answer":"原核生物是一类结构简单、个体微小的微生物，没有膜包被的细胞核，\n只有一个环状的DNA分子位于拟核区内，只有核糖体而无线粒体等其\n他细胞器。包括细菌、古细菌、蓝细菌、放线菌、立克次氏体、衣原\n体、支原体等。除支原体外，原核生物有细胞壁，主要成分是乙酰胞\n壁酸肽聚糖。","chapterNo":15,"chapterTitle":"原核生物多样性","source":"term_doc","answerStatus":"reference","qid":"TERM-0361"},{"term":"支原体","answer":"是最小的原核细胞型微生物，由于能形成丝状与分支形状，故称为支\n原体。革兰染色为阴性，但不易着色，一般用吉姆萨染色，染成淡紫\n色。支原体主要以二分裂方式繁殖，亦可以出芽方式繁殖。支原体广\n泛存在于人和动物体内，大多不致病，对人致病的支原体主要有肺炎\n支原体、溶脲脲原体、人型支原体、生殖器支原体等。","chapterNo":15,"chapterTitle":"原核生物多样性","source":"term_doc","answerStatus":"reference","qid":"TERM-0362"},{"term":"芽孢（2023名词解释/新增）","answer":"有些细菌在生活史的一定阶段产生特殊结构的休眠体，称芽孢。芽孢\n壁厚，有抗干燥、抗热、抗辐射、抗化学药物等特性，使细菌能在恶\n劣环境下存活，某些芽孢甚至可保持休眠状态几个世纪。","chapterNo":15,"chapterTitle":"原核生物多样性","source":"term_doc","answerStatus":"reference","qid":"TERM-0363"},{"term":"代谢共生/互养共栖（新增）","answer":"营养关系中还有一种特殊形式，就是代谢共生，也称互养共栖。当两\n种或两种以上微生物生活在同一空间、且代谢上彼此依赖互利，就形\n成了代谢共生关系。这种关系同共生关系相似，但是代谢共生更强调\n代谢途径和代谢产物。在自然界，这种代谢共生的关系极为普遍，可\n在细菌之间发生，可在古菌之间发生，也可在细菌和古菌之间发生。","chapterNo":15,"chapterTitle":"原核生物多样性","source":"term_doc","answerStatus":"reference","qid":"TERM-0364"},{"term":"两次氧气积累（新增）","answer":"整个积累过程中明显有两次快速增加：第一次由原核生物蓝细菌完成，\n这次氧气积累增加速度很快，被称为“氧气革命”；第二次主要由真\n核光合生物完成。","chapterNo":15,"chapterTitle":"原核生物多样性","source":"term_doc","answerStatus":"reference","qid":"TERM-0365"},{"term":"变形菌（新增）","answer":"变形菌是一大类革兰氏阴性菌，营养方式多样，包括光能自养、化能\n自养和异养。根据16SrRNA 序列特征，变形菌分为5个亚类，即α、\nβ、γ、δ、和ε。α变形菌如根瘤菌，β变形菌如亚硝化单胞菌，\nγ变形菌如大肠杆菌、δ变形菌如黏细菌，ε变形菌如幽门螺杆菌。","chapterNo":15,"chapterTitle":"原核生物多样性","source":"term_doc","answerStatus":"reference","qid":"TERM-0366"},{"term":"光合细菌（新增）","answer":"光合细菌是能够利用叶绿素进行光合作用的几类细菌的总称，本身不\n是一个自然分类群。根据最新的分类，细菌域的7个不同的门含有光\n合细菌。其中以蓝细菌最为带见和重要。","chapterNo":15,"chapterTitle":"原核生物多样性","source":"term_doc","answerStatus":"reference","qid":"TERM-0367"},{"term":"放线菌","answer":"真细菌类群中唯一的单细胞、呈分支的丝状体是放线菌，在土壤中分\n布最广，主要以孢子繁殖，其中最著名的是产生抗生素的链霉菌属。","chapterNo":15,"chapterTitle":"原核生物多样性","source":"term_doc","answerStatus":"reference","qid":"TERM-0368"},{"term":"内含体类型","answer":"（1）储藏物：糖原颗粒、聚羟基烷酯颗粒、多磷体\n（2）微隔室（微室）：羧化体/羧酶体\n（3）磁小体 （4）伪空胞","chapterNo":15,"chapterTitle":"原核生物多样性","source":"term_doc","answerStatus":"reference","qid":"TERM-0369"},{"term":"动物病毒病","answer":"动物身上寄生的病毒发生突变，成为了可以感染人的病毒。如乙肝肺\n炎、天花、流行性感冒、麻疹、狂犬病、登革热、艾滋病、SARS 和\n禽流感等。一些病毒在引起重大疾病之前不被人知，好像突然出现一\n样，这类病原病毒被称为新发病原病毒。如HIV、SARS-CoV-2 和寨卡\n病毒等。","chapterNo":16,"chapterTitle":"病毒","source":"term_doc","answerStatus":"reference","qid":"TERM-0370"},{"term":"植物病毒病","answer":"植物病毒需要在外力作用下使植物细胞壁受到损伤后才能入侵植物\n细胞。","chapterNo":16,"chapterTitle":"病毒","source":"term_doc","answerStatus":"reference","qid":"TERM-0371"},{"term":"类病毒和朊粒","answer":"（1）类病毒：没有蛋白质外壳，只有单链环状RNA分子，为专性寄\n生植物的病原体。\n（2）朊粒：是一类引起哺乳动物亚急性传染性海绵样脑病的致病因\n子，其组分和致病因子是蛋白质，而不是核酸。","chapterNo":16,"chapterTitle":"病毒","source":"term_doc","answerStatus":"reference","qid":"TERM-0372"},{"term":"海洋噬菌体","answer":"海洋病毒以DNA 病毒为主，RNA病毒比较少。海洋病毒多侵染海洋初\n级生产力的主要来源生物——蓝细菌。","chapterNo":16,"chapterTitle":"病毒","source":"term_doc","answerStatus":"reference","qid":"TERM-0373"},{"term":"原病毒/前病毒","answer":"在宿主细胞内，以病毒RNA为模版，由单链 RNA逆转录病毒携带的逆\n转录酶催化逆转录合成病毒双链DNA，双链DNA转移进细胞核内，整\n合至宿主染色体上成为原病毒，一旦受感染细胞被激活，原病毒DNA\n立即转录出病毒的RNA，同时也转录形成mRNA用于合成蛋白质。","chapterNo":16,"chapterTitle":"病毒","source":"term_doc","answerStatus":"reference","qid":"TERM-0374"},{"term":"疫苗（属于主动免疫）","answer":"疫苗是一种与某种病原相关的抗原分子，它可以刺激机体产生免疫反\n应，产生抗体，从而抵御相似病原的感染。现在，疫苗不仅被用来预\n防病原感染和传播，还被用于预防和治疗癌症。","chapterNo":16,"chapterTitle":"病毒","source":"term_doc","answerStatus":"reference","qid":"TERM-0375"},{"term":"内共生假说","answer":"内共生假说认为真核生物是由大型原核生物内吞其他几种类型的原\n核细胞，经功能分化，基因转移重组演化而来，如线粒体和叶绿体是\n以内共生方式发展而来。","chapterNo":17,"chapterTitle":"真核生物起源和原生生物多样性","source":"term_doc","answerStatus":"reference","qid":"TERM-0376"},{"term":"合并体假说","answer":"根据这个假说，真核生物是由一个古菌和一个细菌融合而产生，融合\n后才产生了细胞核和内膜系统以及线粒体。","chapterNo":17,"chapterTitle":"真核生物起源和原生生物多样性","source":"term_doc","answerStatus":"reference","qid":"TERM-0377"},{"term":"绿藻","answer":"绿藻形态多样,有单细胞、群体细胞或多细胞。有些绿藻与真菌共生,\n组成地衣。少数营养体和绝大多数生殖细胞有鞭毛。绿藻细胞载色体\n中叶绿素含量较多。绿藻的一些代表类群有衣藻属、团藻属、浒苔属。\n由于绿藻的叶绿体结构和色素组成与有胚植物的叶绿体极为相似,绿\n藻的鞭毛结构和某些植物的双鞭毛精子的鞭毛相似,生物学家曾认为\n绿藻和有胚植物是由它们的共同祖先--古绿藻演化而来的。","chapterNo":18,"chapterTitle":"绿色植物多样性","source":"term_doc","answerStatus":"reference","qid":"TERM-0378"},{"term":"孢子植物","answer":"生活史中不形成种子,主要利用孢子进行繁殖的植物。包括 藻类植物、\n菌类植物、地衣植物、苔藓植物和蕨类植物等。","chapterNo":18,"chapterTitle":"绿色植物多样性","source":"term_doc","answerStatus":"reference","qid":"TERM-0379"},{"term":"颈卵器植物","answer":"具有颈卵器结构的植物类群。包括苔鲜植物、蕨类植物和裸子植物。","chapterNo":18,"chapterTitle":"绿色植物多样性","source":"term_doc","answerStatus":"reference","qid":"TERM-0380"},{"term":"孢子体(2013、2017判断题)","answer":"植物无性世代中产生的、具有二倍数染色体的植物体。由合子 发育\n而来。不同的植物其孢子体的形态、大小和营养方式也不同。","chapterNo":18,"chapterTitle":"绿色植物多样性","source":"term_doc","answerStatus":"reference","qid":"TERM-0381"},{"term":"配子体(2016判断题)","answer":"植物有性世代中产生的、具有单倍数染色体的植物体。植物的配子体\n是由单倍体孢子经有丝分裂产生。","chapterNo":18,"chapterTitle":"绿色植物多样性","source":"term_doc","answerStatus":"reference","qid":"TERM-0382"},{"term":"原丝体","answer":"苔藓植物的孢子在适宜的环境中萌发成的配子体。原丝体能独立生活,\n它进一步分化形成具有性器官的配子体。原丝体细胞都为单倍体。","chapterNo":18,"chapterTitle":"绿色植物多样性","source":"term_doc","answerStatus":"reference","qid":"TERM-0383"},{"term":"原叶体","answer":"蕨类植物的孢子在适宜的环境中萌发成的配子体。原叶体从一个孢子\n形成。受精后,形成一个幼小的孢子体;由初生根、初生叶、茎原茎和\n一 个称为茎足的器官组成。","chapterNo":18,"chapterTitle":"绿色植物多样性","source":"term_doc","answerStatus":"reference","qid":"TERM-0384"},{"term":"颈卵器","answer":"苔藓植物、蕨类植物和裸子植物产生卵细胞的多细胞雌性生殖器官。\n外形似烧瓶,上部细狭的部分称为颈部,下部膨大的部分称为腹部。","chapterNo":18,"chapterTitle":"绿色植物多样性","source":"term_doc","answerStatus":"reference","qid":"TERM-0385"},{"term":"精子器","answer":"苔藓植物和蕨类植物产生精子的多细胞雄性生殖器官。精子器一般是\n由无生育力的细胞和产生精子的组织所组成的。","chapterNo":18,"chapterTitle":"绿色植物多样性","source":"term_doc","answerStatus":"reference","qid":"TERM-0386"},{"term":"维管植物","answer":"指那些发展出能较好的输导水分、无机盐、营养物质的输导组织的植\n物,它包括用孢子繁殖的低等维管植物(蕨类植物)和用种子繁殖的维\n管植物。","chapterNo":18,"chapterTitle":"绿色植物多样性","source":"term_doc","answerStatus":"reference","qid":"TERM-0387"},{"term":"世代交替","answer":"植物的生活史中有性世代与无性世代有规律地交替进行的现象。植物\n的有性世代从孢子开始,到由其萌发形成配子体,并行有丝分裂产生\n配子;无性世代从配子结合形成的合子开始,到由其萌发形成孢子体,\n直至行减数分裂产生孢子。","chapterNo":18,"chapterTitle":"绿色植物多样性","source":"term_doc","answerStatus":"reference","qid":"TERM-0388"},{"term":"原质体藻类","answer":"藻类中,仅蓝灰藻、红藻、绿藻和由绿藻演化出的链形藻属于原质体\n超类群(植物类),我们把这几类藻类称为原质体藻类。原质体藻类起\n源于原始内共生事件,它们与有胚植物一起形成一个单系群。","chapterNo":18,"chapterTitle":"绿色植物多样性","source":"term_doc","answerStatus":"reference","qid":"TERM-0389"},{"term":"蓝灰藻","answer":"其质体含有藻蓝蛋白、别藻蓝蛋白和叶绿素a,呈蓝绿色或者蓝灰色。\n质体还含有肽聚糖残体。","chapterNo":18,"chapterTitle":"绿色植物多样性","source":"term_doc","answerStatus":"reference","qid":"TERM-0390"},{"term":"成膜体藻类,成膜体植物","answer":"链形藻类中,轮藻、鞘毛藻和双星藻的细胞分裂方式与有胚植物的细\n胞分裂方式极其相似,所有被称为成膜体藻类,同有胚植物一起称为\n成膜体植物","chapterNo":18,"chapterTitle":"绿色植物多样性","source":"term_doc","answerStatus":"reference","qid":"TERM-0391"},{"term":"同形世代交替","answer":"在世代交替过程中,形态结构基本相同的孢子体与配子 体互相交替\n的现象。)如藻类植物的世代交替就是同形世代交替。","chapterNo":18,"chapterTitle":"绿色植物多样性","source":"term_doc","answerStatus":"reference","qid":"TERM-0392"},{"term":"异形世代交替","answer":"在世代交替过程中,形态结构明显不相同的孢子体与配 子体互相交\n替的现象。","chapterNo":18,"chapterTitle":"绿色植物多样性","source":"term_doc","answerStatus":"reference","qid":"TERM-0393"},{"term":"苔藓植物/非维管植物","answer":"苔藓植物已经具有了初步适应陆地的性状,但体内没有维管组织的分\n化,也没有真正的根,有性生殖过程不能脱离水湿环境,只能生活在阴\n湿的环境里,是植物由水生向陆生演化的过渡类型。","chapterNo":18,"chapterTitle":"绿色植物多样性","source":"term_doc","answerStatus":"reference","qid":"TERM-0394"},{"term":"蕨类植物/无种子维管植物","answer":"孢子体适应了陆地生活,对陆地环境比较适应,但有性生殖仍依赖水。\n被称为植物界的两栖类。","chapterNo":18,"chapterTitle":"绿色植物多样性","source":"term_doc","answerStatus":"reference","qid":"TERM-0395"},{"term":"种子植物","answer":"在蕨类植物的基础上摆脱了有性过程中对水的依赖,完全适应了陆地\n的生活。","chapterNo":18,"chapterTitle":"绿色植物多样性","source":"term_doc","answerStatus":"reference","qid":"TERM-0396"},{"term":"裸子植物","answer":"在蕨类植物的基础上摆脱了有性过程中对水的依赖,完全适应了陆地\n的生活。","chapterNo":18,"chapterTitle":"绿色植物多样性","source":"term_doc","answerStatus":"reference","qid":"TERM-0397"},{"term":"被子植物","answer":"在蕨类植物的基础上摆脱了有性过程中对水的依赖,完全适应了陆地\n的生活","chapterNo":18,"chapterTitle":"绿色植物多样性","source":"term_doc","answerStatus":"reference","qid":"TERM-0398"},{"term":"有胚植物","answer":"因其生活史中有胚的出现而得名，又因其生活在陆地上，常被称为陆\n生植物。主 要包括苔藓、蕨类、裸子植物、被子植物。","chapterNo":18,"chapterTitle":"绿色植物多样性","source":"term_doc","answerStatus":"reference","qid":"TERM-0399"},{"term":"【真菌】","answer":"真菌的主要类型:接合菌、子囊菌和担子菌,真菌细\n胞不含叶绿素,真菌营吸收式异养,营寄生或腐生\n生活,是生态系统的分解者,主要贮存糖原,真菌的\n细胞壁主要为壳多糖,除少数单细胞真菌,绝大多数真菌的生物体由\n菌丝构成。真菌属于真核生物,真菌可以通过产生大量的孢子来繁衍\n后代。","chapterNo":19,"chapterTitle":"真菌多样性","source":"term_doc","answerStatus":"reference","qid":"TERM-0400"},{"term":"子实体","answer":"高等真菌产生有性孢子的结构。由能育的菌丝和营养丝组成。子囊菌\n的子实体称子囊果,担子菌的子实体称担子果,其形状、大小与结构因\n种类而异。","chapterNo":19,"chapterTitle":"真菌多样性","source":"term_doc","answerStatus":"reference","qid":"TERM-0401"},{"term":"菌根（2026）","answer":"球囊菌是一类比较特殊的真菌。这类真菌与\n植物根系形成互利共生关系,即菌根,所以这\n类真菌也被称为菌根真菌。菌根分两类：外\n生菌根和丛枝菌根。外生菌根菌只侵人到植物根部细胞之间的区域,\n并不会进人细胞。而丛枝球囊菌的菌丝体会进人到根部细胞中。目前\n已知的球囊菌都与植物根部形成丛枝菌根,外生菌根由其他类群(如\n某些担子菌)的真菌形成。","chapterNo":19,"chapterTitle":"真菌多样性","source":"term_doc","answerStatus":"reference","qid":"TERM-0402"},{"term":"真菌","answer":"真菌没有叶绿素,不能进行光合作用,是一种吸收异养的生物。真菌可\n以分泌分解酶到体外基质中,使较大的有机分子分解为较小的分子,\n再吸收到体内作为食物。真菌绝大多数由长丝状的菌丝组成,菌丝反\n复分支形成菌丝体。其细胞壁成分是壳多糖(几丁质)。有丝分裂过程\n无核膜的破碎和重建,有丝分裂在核内进行。有性生殖方式通过不同\n交配型的菌丝相互接近、融合而实现有性过程。","chapterNo":19,"chapterTitle":"真菌多样性","source":"term_doc","answerStatus":"reference","qid":"TERM-0403"},{"term":"辐射对称","answer":"大部分棘皮动物、刺胞动物、海绵动物都是辐射对称的体型。即通过\n身体的中轴可以有二个或二个以上的切面把身体分成两个相等的部\n分。是一种原始的对称形式。","chapterNo":20,"chapterTitle":"动物多样性","source":"term_doc","answerStatus":"reference","qid":"TERM-0404"},{"term":"两侧对称","answer":"从扁形动物开始出现了两侧对称的体型。即通过动物体地中央轴,只\n有一个对称面(或说切面)将动物体分成左右相等的两部分,因此两侧\n对称也称为左右对称。两侧对称使动物有了前后、左右、背腹的区别,\n使其能够更好的适应环境的变化。","chapterNo":20,"chapterTitle":"动物多样性","source":"term_doc","answerStatus":"reference","qid":"TERM-0405"},{"term":"原体腔(假体腔、初生体腔)","answer":"是动物界最先出现的体腔形式,只有体壁中胚层,无肠壁中胚层。假体\n腔直接与肌肉为界,无中胚层形成的体腔膜和肠系膜,是一封闭的腔,\n充满体腔液。存在于线虫动物门中。(体腔的出现,促进肠道与体壁独\n立运动,使内脏器官具有稳定内环境。)","chapterNo":20,"chapterTitle":"动物多样性","source":"term_doc","answerStatus":"reference","qid":"TERM-0406"},{"term":"后体腔(真体腔、次生体腔)","answer":"是中胚层的体壁层和脏壁层分离后共同包围的腔。因为比来源于囊胚\n腔的原体腔出现得迟,故又称“次生体腔”。软体动物是最早出现真\n体腔的动物。(体腔的出现,促进肠道与体壁独立运动,使内脏器官具\n有稳定内环境。)","chapterNo":20,"chapterTitle":"动物多样性","source":"term_doc","answerStatus":"reference","qid":"TERM-0407"},{"term":"同律分节","answer":"环节动物身体分节,身体除头部外各体节基本相同,一些内部器官也\n依体节重复排列,这种分节方式称为同律分节。这是一种比较原始的\n分节现象。(体节的出现使动物身体的运动更加灵活,对促进动物体的\n新陈代谢,增强对环境的适应能力,有着重大意义。)","chapterNo":20,"chapterTitle":"动物多样性","source":"term_doc","answerStatus":"reference","qid":"TERM-0408"},{"term":"异律分节","answer":"节肢动物身体分节,不同的体节在一定程度上愈合,形成头部、胸部、\n腹部等形态不同的体区,完成不同的生理机能,这种分节方式称为异\n律分节。(异律分节提高了动物对环境条件的趋避能力,分节的附肢增\n强了身体运动的灵活性,扩大了运动和分布的范围。)","chapterNo":20,"chapterTitle":"动物多样性","source":"term_doc","answerStatus":"reference","qid":"TERM-0409"},{"term":"后口动物","answer":"在胚胎发育过程中,胚孔形成动物的肛门,在相反方向的一端由内胚\n层内陷形成口的动物。后口动物包括棘皮动物和脊索动物。","chapterNo":20,"chapterTitle":"动物多样性","source":"term_doc","answerStatus":"reference","qid":"TERM-0410"},{"term":"羊膜动物","answer":"胚胎发育中出现羊膜结构的脊椎动物,可以进行体内受精,进行胸式\n呼吸。包括爬行纲动物,鸟纲动物,哺乳纲动物。","chapterNo":20,"chapterTitle":"动物多样性","source":"term_doc","answerStatus":"reference","qid":"TERM-0411"},{"term":"脊索动物","answer":"是指那些凡是具有脊索,或在演化过程中脊索退化,被脊椎所取代的\n动物。脊索动物既可以分为原索动物和脊椎动物,也可分为尾索动物、\n头索动物和脊椎动物三个亚门。","chapterNo":20,"chapterTitle":"动物多样性","source":"term_doc","answerStatus":"reference","qid":"TERM-0412"},{"term":"革兰氏染色","answer":"一种根据细菌细胞壁结构的不同而将细菌区分为两大类的染色方法。\n染成红色的称为革兰氏阴性,染成紫色的称为革兰氏阳性。","chapterNo":20,"chapterTitle":"动物多样性","source":"term_doc","answerStatus":"reference","qid":"TERM-0413"},{"term":"体腔","answer":"动物体内各内脏器官周围的空隙叫体腔。体腔分为真体腔和假体腔两\n类。假体腔存在于线虫动物门,较低等;真体腔最早出现于软体动物。\n从胚胎发育看,真正的体腔是中胚层的脏壁和体壁分离后其间所形成\n的空腔。体腔的出现,促进肠道与体壁独立运动,使内脏器官具有稳定\n内环境。","chapterNo":20,"chapterTitle":"动物多样性","source":"term_doc","answerStatus":"reference","qid":"TERM-0414"},{"term":"完全变态","answer":"是昆虫变态的两种类型之一。昆虫在个体发育中,经过卵、幼虫、蛹\n和成虫等4个时期的叫完全变态。完全变态的幼虫与成虫在形态构造\n和生活习性上明显不同。例如,蝶、蚊则是经过完全变态而长成的昆\n虫。","chapterNo":20,"chapterTitle":"动物多样性","source":"term_doc","answerStatus":"reference","qid":"TERM-0415"},{"term":"不完全变态","answer":"是昆虫变态的两种类型之一。昆虫在个体发育中,只经过卵、幼虫和\n成虫等3 个时期的,叫做不完全变态。不完全变态包括渐变态和半变\n态两种,渐变态幼虫的形态和习性与成虫差别不大,半变态幼虫的形\n态和习性与成虫不同。蜻蜓的发育过程是不完全变态过程。","chapterNo":20,"chapterTitle":"动物多样性","source":"term_doc","answerStatus":"reference","qid":"TERM-0416"},{"term":"原口动物","answer":"在胚胎发育过程中,由原肠胚的胚孔形成口的动物,包括扁形动物、线\n虫动物、软体动物等。","chapterNo":20,"chapterTitle":"动物多样性","source":"term_doc","answerStatus":"reference","qid":"TERM-0417"},{"term":"无变态","answer":"幼虫和成虫相比较,除幼虫身体较小和性器官未成熟外,没有特别的\n差别,并且发育为成虫后仍蜕皮生长。","chapterNo":20,"chapterTitle":"动物多样性","source":"term_doc","answerStatus":"reference","qid":"TERM-0418"},{"term":"渐变态","answer":"除幼虫的翅和生殖腺未发育外,幼虫形态与成虫相差不大,生活环境\n和习性也相同,称为若虫(例如蝗虫)","chapterNo":20,"chapterTitle":"动物多样性","source":"term_doc","answerStatus":"reference","qid":"TERM-0419"},{"term":"半变态","answer":"幼虫的形态和习性与成虫不同,生活环境也不一样,称为稚虫(例如蜻\n蜓和蜉蝣的幼虫).","chapterNo":20,"chapterTitle":"动物多样性","source":"term_doc","answerStatus":"reference","qid":"TERM-0420"},{"term":"【多细胞动物的早期发育过程具有非常一致的规律性,受精卵的","answer":"早期发育一般都要经过桑葚胚、囊胚、原肠胚和胚层发生等阶段.】\n(1)卵裂期:受精卵分裂方式,分为完全卵裂/均等卵裂和不完全卵裂/\n不均等卵裂;\n(2)桑葚胚:分裂形成的多细胞实心球状体,形如桑葚;\n(3)囊胚:球形幼胚,包括滋养层细胞、内细胞团和囊胚腔;\n(4)原肠胚:只有一层细胞的囊胚发育成为有两层细胞的原肠胚。原肠\n的出现使动物的胚胎出现了外胚层和内胚层的分化;随着发育的进行,\n外胚层和内胚层之间将形成中胚层,分别分化成各种组织、\n(5)中胚层和神经胚的形成。","chapterNo":20,"chapterTitle":"动物多样性","source":"term_doc","answerStatus":"reference","qid":"TERM-0421"},{"term":"多地域起源假说","answer":"多地域起源假说主张现代智人是从原先分布于旧大陆各地的早期智\n人进化而来，不同地区的人都彼此平行地从直立人到早期智人再到现\n代人。","chapterNo":21,"chapterTitle":"人类的演化","source":"term_doc","answerStatus":"reference","qid":"TERM-0422"},{"term":"单一起源假说","answer":"单一起源假说认为现代智人起源于 10 万年前的非洲，再从非洲扩散\n出去，最后完全代替了尼人和原来生活在其他各地的早期\n\n============================================================\n按“数字+顿号/句号”编号统计，约提取 425 条编号名词解释；部分“补充/新增”条目可能未采用数字编号，因此不计入该数字。","chapterNo":21,"chapterTitle":"人类的演化","source":"term_doc","answerStatus":"reference","qid":"TERM-0423"},{"term":"分生组织","answer":"是指在植物体内某些特定的部位具有持续性或周期性分裂能力的细\n\n胞群，这些细胞分裂产生更多的细胞，使植物生长。分生组织按位置\n\n可分为顶端分生组织、侧生分生组织、居间分生组织，按来源的性质\n\n可分为原分生组织、初生分生组织、次生分生组织。","chapterNo":22,"chapterTitle":"植物的结构与生殖","source":"term_doc","answerStatus":"reference","qid":"TERM-0424"},{"term":"平周分裂和垂周分裂","answer":"平周分裂即切向分裂，是细胞分裂产生的新壁与器官表面最近处切线\n\n相平行，子细胞的新壁为切向壁。平周分裂使器官加厚。垂周分裂即\n\n径向分裂，是细胞分裂产生的新壁与器官表面最近处切线相垂直，子\n\n细胞的新壁为径向壁。垂周分裂使器官增粗。","chapterNo":22,"chapterTitle":"植物的结构与生殖","source":"term_doc","answerStatus":"reference","qid":"TERM-0425"},{"term":"定根和不定根","answer":"发生位置固定的根，称为定根，包括主根和侧根两种。在主根和主根\n\n所产生的侧根以外的部分，如茎、叶、老根或胚轴上生出的根，因其\n\n着生位置不固定，故称不定根。","chapterNo":22,"chapterTitle":"植物的结构与生殖","source":"term_doc","answerStatus":"reference","qid":"TERM-0426"},{"term":"直根系和须根系","answer":"有明显的主根和侧根区分的根系称直根系，如松、棉、油菜等植物的\n\n根系。\n\n无明显的主根和侧根区分的根系，或根系全部由不定根和它的分枝组\n\n成，粗细相近，无主次之分，而呈须状的根系称须根系，如禾本科植\n\n物稻、麦的根系。","chapterNo":22,"chapterTitle":"植物的结构与生殖","source":"term_doc","answerStatus":"reference","qid":"TERM-0427"},{"term":"初生生长","answer":"来自顶端分生组织产生的细胞使植物体的长度增加，称为初生生长。\n\n在木本植物体内，初生生长仅限于最幼嫩的部分，例如根尖、茎尖。","chapterNo":22,"chapterTitle":"植物的结构与生殖","source":"term_doc","answerStatus":"reference","qid":"TERM-0428"},{"term":"初生结构","answer":"在植物体的初生生长过程中所产生的各种成熟组织，共同组成的结构\n\n称为初生结构。(初生结构是低等维管植物和草本种子植物的主要组\n\n成部分，担负着吸收、光合、蒸腾和生殖等重要功能。)","chapterNo":22,"chapterTitle":"植物的结构与生殖","source":"term_doc","answerStatus":"reference","qid":"TERM-0429"},{"term":"形成层","answer":"多年生植物根、茎内部围绕中轴排成一环分生组织层，称为形成层。\n\n分为维管形成层和木栓形成层。","chapterNo":22,"chapterTitle":"植物的结构与生殖","source":"term_doc","answerStatus":"reference","qid":"TERM-0430"},{"term":"维管组织（2022 年名词解释）","answer":"又称输导组织，是由多种类型的细胞组成的复合组织，分布于植物的\n\n根、茎和叶脉中，起着物质运输的作用，分为木质部和韧皮部两部分。\n\n木质部：\n\n①从根部向上运送水分及可溶的矿物质\n\n②由管胞、导管分子、木纤维、木薄壁细胞等构成，其中水分输导细\n\n胞有管胞与导管分子\n\n③有含木质素的次生壁\n\n④成熟时，管胞和导管分子都是死细胞，留下的只是细胞壁。\n\n⑤木质部的汁液只能自下而上，从根到地上流动。\n\n韧皮部：\n\n①将有机物从叶或贮藏组织运送到植物的其他部位\n\n②由伴胞或筛胞、筛管分子、韧皮纤维、韧皮薄壁细胞等构成。食管\n\n疏导细胞即筛管分子。\n\n③有薄的初生壁，没有次生壁。\n\n④成熟时，仍然是活的。\n\n⑤韧皮部的汁液可以沿着各种方向流动。\n\n(可以用于答对比题)","chapterNo":22,"chapterTitle":"植物的结构与生殖","source":"term_doc","answerStatus":"reference","qid":"TERM-0431"},{"term":"维管束","answer":"由原形成层分化而来，以输导为主的复合组织，由木质部和韧皮部或\n\n加上形成层共同构成的束状结构。(在单子叶植物茎中，维管束分散\n\n在基本组织系统之中，在双子叶植物茎中，维管束排列成圆筒状，基\n\n本组织系统由此形成两部分。)","chapterNo":22,"chapterTitle":"植物的结构与生殖","source":"term_doc","answerStatus":"reference","qid":"TERM-0432"},{"term":"维管组织系统","answer":"植物体各器官中的由维管束构成的一个连续统一的系统，主要行使输\n\n导水分、矿物质和有机物的功能。包括输导水分和矿物质的木质部和\n\n输导有机物的韧皮部。","chapterNo":22,"chapterTitle":"植物的结构与生殖","source":"term_doc","answerStatus":"reference","qid":"TERM-0433"},{"term":"次生生长","answer":"侧生分生组织，即维管形成层和木栓形成层分裂、分化形成各种成熟\n\n组织，使根、茎等器官加粗，称为次生生长。(在木本植物体内，次\n\n生生长发生在茎和根的较老部分，具顶端稍远处。)","chapterNo":22,"chapterTitle":"植物的结构与生殖","source":"term_doc","answerStatus":"reference","qid":"TERM-0434"},{"term":"次生结构","answer":"在植物体的次生生长过程中所产生的各种成熟组织，共同组成的结构\n\n称为次生结构。包括次生维管组织和周皮。(次生结构可增强植物体\n\n的支持、输导和贮藏等功能。)","chapterNo":22,"chapterTitle":"植物的结构与生殖","source":"term_doc","answerStatus":"reference","qid":"TERM-0435"},{"term":"凯氏带","answer":"双子叶植物和裸子植物在根的内皮层细胞处于初生状态时，其细胞的\n\n径向壁和横向壁上形成一条带有栓质和木质素的带，称为凯氏带。水\n\n分和溶液不能通过这条带，只能通过质膜进入内皮层细胞内。对根内\n\n水分吸收和运输具有控制作用。","chapterNo":22,"chapterTitle":"植物的结构与生殖","source":"term_doc","answerStatus":"reference","qid":"TERM-0436"},{"term":"树皮","answer":"双子叶植物木本茎的维管形成层以外的部分，包括木栓层、木栓形成\n\n层，栓内层、次生韧皮部。","chapterNo":22,"chapterTitle":"植物的结构与生殖","source":"term_doc","answerStatus":"reference","qid":"TERM-0437"},{"term":"年轮（2016 年名词解释）","answer":"多年生的木本植物茎干横断面上由于维管形成层细胞的分裂活动受\n\n季节的影响出现的若干同心轮纹，由春材(早材)和秋材(晚材)组成。","chapterNo":22,"chapterTitle":"植物的结构与生殖","source":"term_doc","answerStatus":"reference","qid":"TERM-0438"},{"term":"髓射线","answer":"初生维管束之间的薄壁组织，由原形成层之间的基本分生组织分化而\n\n来的径向薄壁组织组成，位于皮层和髓之间，呈辐射状分布，其作用\n\n是内外横向运输和贮藏营养物质。","chapterNo":22,"chapterTitle":"植物的结构与生殖","source":"term_doc","answerStatus":"reference","qid":"TERM-0439"},{"term":"花","answer":"被子植物的生殖器官，由花柄、花托、花萼、花冠、雌蕊群和雄蕊群\n\n五个部分组成的花称为完全花，缺少一种或几种花器官的的花称为不\n\n完全花。\n\n(既有雌蕊又有雄蕊的花，称为两性花(雌雄同株);缺少雌蕊或缺少雄\n\n蕊的花称为单性花(雌雄异株)。)","chapterNo":22,"chapterTitle":"植物的结构与生殖","source":"term_doc","answerStatus":"reference","qid":"TERM-0440"},{"term":"花序","answer":"植物的花聚生成簇，按一定的排列格式，生长在共同的花轴之上，称\n\n为花序。(花序可分为有限花序和无限花序。花序常被作为被子植物\n\n分类鉴定的一种依据。)","chapterNo":22,"chapterTitle":"植物的结构与生殖","source":"term_doc","answerStatus":"reference","qid":"TERM-0441"},{"term":"心皮","answer":"心皮是构成雌蕊的单位，是具生殖作用的变态叶。(雌蕊的三个组成\n\n部分即子房、花柱、柱头都是由心皮所构成的。心皮是植物界进化的\n\n产物，是被子植物特有的器官。)","chapterNo":22,"chapterTitle":"植物的结构与生殖","source":"term_doc","answerStatus":"reference","qid":"TERM-0442"},{"term":"传粉","answer":"指花粉粒由花粉囊中散出，经媒介的作用而传送到柱头上的过程。\n\n(传粉是高等维管植物的特有现象，雄配子借花粉管传送到雌配子体，\n\n使植物受精不再以水为媒介，这对适应陆生环境具有重大意义。在自\n\n然条件下，传粉包括自花传粉和异花传粉两种形式。)","chapterNo":22,"chapterTitle":"植物的结构与生殖","source":"term_doc","answerStatus":"reference","qid":"TERM-0443"},{"term":"双受精（2017、18、21 年名词解释）","answer":"花粉管到达胚囊后，释放两个精子，一个精子与卵子结合形成二倍体\n\n的受精卵，另一个精子与两个极核（或次生核）融合，形成三倍体的\n\n初生胚乳核，卵细胞和极核同时和两个精子分别完成融合的过程称为\n\n双受精。双受精是被子植物有性生殖特有的现象\n\n①花粉粒由花粉囊中散出，经媒介的作用而传送到柱头上；\n\n②营养细胞质从花粉壁的萌发孔突出形成花粉管并穿入柱头；\n\n③营养细胞、生殖细胞的细胞质和核进入花粉管，花粉管在花柱中延\n\n伸到子房，同时生殖细胞发生有丝分裂，产生 2 个精子；\n\n④当花粉管到达胚珠时，从胚孔进入胚囊，花粉管到达胚囊后、释放\n\n出二精子，一个与卵细胞融合，成为二倍体的受精卵(合子),另一个\n\n与两个极核(或次生核)融合形成三倍体的胚乳母细胞。\n\n这样卵细胞和极核同时和二精子分别完成融合的过程称双受精。双受\n\n精是被子植物有性生殖特有的现象。","chapterNo":22,"chapterTitle":"植物的结构与生殖","source":"term_doc","answerStatus":"reference","qid":"TERM-0444"},{"term":"单性结实","answer":"不经过受精作用，子房就发育成果实，这种现象称单性结实。单性结\n\n实过程中，子房不经过传粉或任何其他刺激，便可形成无子果实，称\n\n为营养单性结实，如香蕉。若子房必须通过诱导作用才能形成无子果\n\n实，则称为诱导单性结实(或刺激单性结实),如以马铃薯的花粉刺激\n\n番茄的柱头可得到无籽果实。","chapterNo":22,"chapterTitle":"植物的结构与生殖","source":"term_doc","answerStatus":"reference","qid":"TERM-0445"},{"term":"上位子房","answer":"花萼、花冠和雄蕊都着生于子房之下，称之为子房上位或称下位花。\n\n如油菜、毛莨、牡丹、蚕豆等的花。","chapterNo":22,"chapterTitle":"植物的结构与生殖","source":"term_doc","answerStatus":"reference","qid":"TERM-0446"},{"term":"下位子房","answer":"花托凹下成各种形状，子房隐陷于托内，花萼、花冠和雄蕊都着生于\n\n子房之上，称之为子房下位或称上位花。如梨、瓜类、向日葵和仙人\n\n掌等的花。","chapterNo":22,"chapterTitle":"植物的结构与生殖","source":"term_doc","answerStatus":"reference","qid":"TERM-0447"},{"term":"真果","answer":"仅由子房发育形成的果实。如桃、棉的果实。","chapterNo":22,"chapterTitle":"植物的结构与生殖","source":"term_doc","answerStatus":"reference","qid":"TERM-0448"},{"term":"假果","answer":"除了子房外，花的其他部分如花托、花萼、花冠及整个花序等其他结\n\n构共同参与果实形成，如苹果的肉质部分主要来自花托。","chapterNo":22,"chapterTitle":"植物的结构与生殖","source":"term_doc","answerStatus":"reference","qid":"TERM-0449"},{"term":"聚花果","answer":"果实由整个花序发育而来，花序也参与果实的组成部分，称为聚花果\n\n或花序果、复果，如桑椹、菠萝、无花果等植物的果。","chapterNo":22,"chapterTitle":"植物的结构与生殖","source":"term_doc","answerStatus":"reference","qid":"TERM-0450"},{"term":"聚合果","answer":"一朵花中有许多离生雌蕊，以后每一雌蕊形成一个小果，相聚在同一\n\n花托之上，称为聚合果，如白玉兰、莲、草莓的果。","chapterNo":22,"chapterTitle":"植物的结构与生殖","source":"term_doc","answerStatus":"reference","qid":"TERM-0451"},{"term":"世代交替","answer":"生物的生活史中有性世代与无性世代有规律地交替进行的现象。植物\n\n的有性世代从孢子开始，到由其萌发形成配子体，并行有丝分裂产生\n\n配子；无性世代从配子结合形成的合子开始，到由其萌发形成孢子体，\n\n直至行减数分裂产生孢子。","chapterNo":22,"chapterTitle":"植物的结构与生殖","source":"term_doc","answerStatus":"reference","qid":"TERM-0452"},{"term":"生活史","answer":"生物在一生中所经历的发育和繁殖阶段，前后相继，有规律地循环的\n\n全部过程，称为生活史。从种子开始至新一代种子形成所经历的全过\n\n程，称为种子植物的生活史或是生活周期。)所有植物的生活周期的\n\n特点是有世代交替。","chapterNo":22,"chapterTitle":"植物的结构与生殖","source":"term_doc","answerStatus":"reference","qid":"TERM-0453"},{"term":"变态","answer":"在有些生物的个体发育中，其形态和构造上经历阶段性剧烈变化。有\n\n些器官退化消失，有些器官有变化、得到改造。主要由自身基因与外\n\n环境控制，这种现象统称为变态。例如，昆虫结束幼虫期进入成虫期；\n\n植物的叶片变化为花朵。","chapterNo":22,"chapterTitle":"植物的结构与生殖","source":"term_doc","answerStatus":"reference","qid":"TERM-0454"},{"term":"内起源","answer":"植物的侧根通常起源于母根的中柱鞘，发生于根的内部组织，这种起\n\n源方式称为内起源。","chapterNo":22,"chapterTitle":"植物的结构与生殖","source":"term_doc","answerStatus":"reference","qid":"TERM-0455"},{"term":"外起源","answer":"叶原基和芽原基在顶端分生组织的表面发生，这种起源方式成为外起\n\n源。","chapterNo":22,"chapterTitle":"植物的结构与生殖","source":"term_doc","answerStatus":"reference","qid":"TERM-0456"},{"term":"内皮层","answer":"皮层最内的一层，排列整齐紧密，无胞间隙，称为内皮层。内皮层细\n\n胞的径向壁和横向壁上形成一条带有栓质和木质素的带，称为凯氏带，\n\n水分和溶液不能通过这条带，只能通过质膜进入内皮层细胞内。因此，\n\n内皮层是一个选择性的屏障，它决定皮层的其他部分和维管组织之间\n\n物质的通过。","chapterNo":22,"chapterTitle":"植物的结构与生殖","source":"term_doc","answerStatus":"reference","qid":"TERM-0457"},{"term":"中柱鞘","answer":"在维管柱的最外层，紧贴着内皮层细胞有一层薄壁细胞，称为中柱鞘，\n\n中柱鞘细胞可以再度转变为分生细胞，重新分裂。","chapterNo":22,"chapterTitle":"植物的结构与生殖","source":"term_doc","answerStatus":"reference","qid":"TERM-0458"},{"term":"顶端分生组织","answer":"维管植物根和茎顶端的分生组织。是植物初生生长的来由。作用是使\n\n根和茎长度增加，使根在土壤中广泛分布，使枝叶繁茂，尽可能多地\n\n接受阳光和二氧化碳。在禾本植物内，顶端分生组织位于幼嫩部分，\n\n如根尖、茎尖。","chapterNo":22,"chapterTitle":"植物的结构与生殖","source":"term_doc","answerStatus":"reference","qid":"TERM-0459"},{"term":"侧生分生组织","answer":"维管植物根和茎的周围靠近器官边缘的分生组织。是植物次生生长的\n\n来由。作用是使根和茎加粗加固。在木本植物体内，侧生分生组织位\n\n于茎和根较老的部分，距顶端稍远处。(侧生分生组织包括维管形成\n\n层和木栓形成层，维管形成层产生次生木质部和次生韧皮部，木栓形\n\n成层产生周皮，替代表皮，起保护作用。)","chapterNo":22,"chapterTitle":"植物的结构与生殖","source":"term_doc","answerStatus":"reference","qid":"TERM-0460"},{"term":"居间分生组织","answer":"是位于成熟组织之间的、由顶端分生组织遗留下来的初生分生组织。\n\n这些分生组织的活动导致了已经分化的组织区域仍能进行伸长生长，\n\n这种生长方式称为居间生长。","chapterNo":22,"chapterTitle":"植物的结构与生殖","source":"term_doc","answerStatus":"reference","qid":"TERM-0461"},{"term":"配子生殖","answer":"配子生殖是指由亲本产生的有性生殖细胞——配子，两两相配成对，\n\n互相结合，成为合子，再由合子发育成新全体的生殖方式。这种生殖\n\n方式又可分为：同配生殖、异配生殖和卵式生殖，其中最常见的是卵\n\n式生殖。","chapterNo":22,"chapterTitle":"植物的结构与生殖","source":"term_doc","answerStatus":"reference","qid":"TERM-0462"},{"term":"植物的胚囊","answer":"是种子植物的雌配子体，是胚珠中的大孢子母细胞产生的大孢子经有\n\n丝分裂形成的一个多细胞结构。胚囊一般为 8 核、7 细胞的结构，包\n\n括 1 个卵细胞、2 个助细胞、1 个中央细胞(两个极核)和 3 个反足细\n\n胞。受精后，受精卵在胚囊内发育成胚，受精的极核发育成胚乳。","chapterNo":22,"chapterTitle":"植物的结构与生殖","source":"term_doc","answerStatus":"reference","qid":"TERM-0463"},{"term":"完全花：","answer":"具有全部花器官（花瓣、萼片、雄蕊和雌蕊）的花。","chapterNo":22,"chapterTitle":"植物的结构与生殖","source":"term_doc","answerStatus":"reference","qid":"TERM-0464"},{"term":"不完全花","answer":"缺少一种或几种花器官的花称为不完全花。","chapterNo":22,"chapterTitle":"植物的结构与生殖","source":"term_doc","answerStatus":"reference","qid":"TERM-0465"},{"term":"两性花","answer":"在一朵花中雌蕊和雄蕊同时存在，但不一定都有花瓣和萼片。","chapterNo":22,"chapterTitle":"植物的结构与生殖","source":"term_doc","answerStatus":"reference","qid":"TERM-0466"},{"term":"单性花","answer":"在一朵花中只存在雄蕊或雌蕊，分别为雄花和雌花。","chapterNo":22,"chapterTitle":"植物的结构与生殖","source":"term_doc","answerStatus":"reference","qid":"TERM-0467"},{"term":"雌雄同株","answer":"指一株植物的花有雌蕊，也有雄蕊。","chapterNo":22,"chapterTitle":"植物的结构与生殖","source":"term_doc","answerStatus":"reference","qid":"TERM-0468"},{"term":"雌雄异株","answer":"指具有单性花的种子植物中，雄花和雌花分别生长在不同的株体。","chapterNo":22,"chapterTitle":"植物的结构与生殖","source":"term_doc","answerStatus":"reference","qid":"TERM-0469"},{"term":"花粉粒","answer":"花药中的小孢子母细胞进行减数分裂，产生 4 个单倍体小孢子。每一\n\n个孢子发生有丝分裂，产生 2 个单倍体细胞，即营养细胞(粉管细胞)\n\n和生殖细胞，这两个细胞组成花粉粒，从花药中释放出来。","chapterNo":22,"chapterTitle":"植物的结构与生殖","source":"term_doc","answerStatus":"reference","qid":"TERM-0470"},{"term":"种子休眠","answer":"成熟时，种子发生脱水作用而进入休眠状态，这是一种降低代谢速率\n\n而中断一切生长发育过程的状态，是植物抵御不良环境的一种自身保\n\n护性的生物学特性。\n\n种子休眠的原因有:\n\na.种皮障碍(不透水不透气等)。\n\nb.种子未完全成熟。\n\nc.胚未完全发育。\n\nd.含有抑制萌发的物质。","chapterNo":22,"chapterTitle":"植物的结构与生殖","source":"term_doc","answerStatus":"reference","qid":"TERM-0471"},{"term":"打破休眠","answer":"是使种子恢复其生长发育的过程，常常需要特定的环境条件。\n\n打破休眠的方法有:\n\n①低温处理。如松科、柏科的种子可采用沙土层积法，在低温、湿润\n\n和通气良好的层积下经\n\n过一段时间便可萌发。\n\n②干燥处理。如大麦种子在 40°C 高温下处理 3~7 天可促进萌发。\n\n③曝光处理。如莴苣种子发芽需要曝光。\n\n④冲洗处理。通过浸泡冲洗种子，可促进发芽。\n\n⑤机械处理。对硬实种子采用机械处理种皮可打破其休眠。\n\n⑥药剂处理。如三叶草种子可用极低浓度的乙烯解除休眠。","chapterNo":22,"chapterTitle":"植物的结构与生殖","source":"term_doc","answerStatus":"reference","qid":"TERM-0472"},{"term":"种子萌发","answer":"种子萌发是生活周期的继续。萌发从种子的吸水开始。种子吸水后膨\n\n胀破裂，并引发胚中的代谢变化，种子重新开始生长发育。有些植物\n\n是子叶出土萌发，另一些则是子叶留土萌发。","chapterNo":22,"chapterTitle":"植物的结构与生殖","source":"term_doc","answerStatus":"reference","qid":"TERM-0473"},{"term":"子叶出土萌发","answer":"萌发时下胚轴伸长，将子叶和胚芽推出土面。例如，大豆，棉花的种\n\n子。","chapterNo":22,"chapterTitle":"植物的结构与生殖","source":"term_doc","answerStatus":"reference","qid":"TERM-0474"},{"term":"子叶留土萌发","answer":"萌发时下胚轴不伸长，子叶留在土中，上胚轴或中胚轴和胚芽伸出土\n\n面，例如豌豆，蚕豆的种子。","chapterNo":22,"chapterTitle":"植物的结构与生殖","source":"term_doc","answerStatus":"reference","qid":"TERM-0475"},{"term":"营养繁殖","answer":"植物的营养繁殖是指植物由亲本或其营养体一部分与母体分离(有时\n\n不分离)直接形成新个体的繁殖方式。许多植物的胞芽、茎段、块根、\n\n块茎、根状茎、球茎、鳞茎、叶、芽等，在外界条件适合下可以产生\n\n新植株。园艺上利用的营养繁殖方式有许多种：扦插、压条、嫁接和\n\n细胞的组织培养等。","chapterNo":22,"chapterTitle":"植物的结构与生殖","source":"term_doc","answerStatus":"reference","qid":"TERM-0476"},{"term":"储藏根，呼吸根(新增）","answer":"是植物为了适应特定环境或功能需求，由普通根变态（形态和功能发\n\n生改变）而形成的。\n\n（1）储藏根\n\n储存大量的营养物质，如淀粉、糖类、水分等，以供植物在休眠期（如\n\n冬季或旱季）或繁殖时使用。通常变得粗大、肥厚，形态多样。例如\n\n胡萝卜肥大的主根，里面储藏了大量的糖分；红薯的块根是由不定根\n\n膨大形成的，储藏了大量的淀粉。\n\n（2）呼吸根\n\n帮助生长在淤泥或水中、根系缺氧的植物进行呼吸作用，交换气体。\n\n向上生长，露出水面或地面，内部常有发达的通气组织（气腔），像\n\n海绵一样，便于输送和储存空气。例如红树植物（如海桑、白骨壤）\n\n生长在海岸潮间带的淤泥中，土壤缺氧且盐度高。它们的呼吸根像一\n\n根根筷子或手指一样从淤泥中直立向上伸出，在退潮时暴露于空气中，\n\n吸收氧气，输送到地下部分。","chapterNo":22,"chapterTitle":"植物的结构与生殖","source":"term_doc","answerStatus":"reference","qid":"TERM-0477"},{"term":"辐射对称花，两侧对称花，不对称花（新增）","answer":"花的对称性是由花冠（所有花瓣的总称）的形态和排列方式决定的，\n\n它是植物分类的重要依据，也与传粉方式密切相关。\n\n（1）辐射对称花\n\n又称整齐花。指通过花的中心可以作出多个对称面，将花分为两个以\n\n上完全相等的部分。像星星、车轮一样均匀辐射开来。其特点为形状\n\n通常为圆形、星形或漏斗形。花瓣的形态、大小基本一致。是最原始\n\n和常见的花对称类型。\n\n（2）两侧对称花\n\n又称不整齐花。指通过花的中心只能作出一个对称面，将花分为左右\n\n两个互相对称的部分。形状通常不规则，如唇形、蝶形等。花瓣的形\n\n态和大小可能不同。是更进化的类型，通常与特定的传粉者（如昆虫、\n\n鸟类）高度协同进化。\n\n（3）不对称花\n\n指通过花的中心无法作出任何对称面，花的左右两侧无法被分成相同\n\n的两部分。","chapterNo":22,"chapterTitle":"植物的结构与生殖","source":"term_doc","answerStatus":"reference","qid":"TERM-0478"},{"term":"ABC 模型（新增）","answer":"科学家研究拟南芥花的突变体时，发现了控制花的各部分发生的基因，\n\n提出了其分子调控模型：ABC 模型。该模型认为，正常的花器官发育\n\n涉及 A、B、C 三类基因：\n\nA 类基因在花萼和花瓣中表达，B 类基因在花瓣和雄蕊中表达，C 类\n\n基因在雄蕊和雌蕊中表达。A 类和 C 类基因相互拮抗。无论哪类基因\n\n突变，都会引起相对应的表型的改变。","chapterNo":22,"chapterTitle":"植物的结构与生殖","source":"term_doc","answerStatus":"reference","qid":"TERM-0479"},{"term":"真果，假果，单果，聚合果，聚花果（复果）（新增）","answer":"（1）果实的分类根据来源\n\n①真果\n\n：单纯由子房发育而成的果实。如桃子、番茄。\n\n②假果\n\n：除了子房外，花的其他部分也可以参与果实的形成，这样形成的果\n\n实就是假果。例如苹果的花，其子房与被丝托贴生，密不可分，我们\n\n食用的苹果的肉质部分主要来自膨大、肉质的被丝托。内果皮来自子\n\n房壁，成熟时为软骨质，俗称苹果核，种子被包裹在其中。\n\n（2）根据形态结构\n\n①单果\n\n果实是由花中仅有的一个子房发育而成。根据其果皮肉质或干燥可分\n\n为肉果和干果。\n\n前者如桃、西红柿等，后者如大豆、芝麻等。（单花单雌蕊）\n\n②聚合果\n\n一朵花的雌蕊由多个离生的子房构成，其发育而成的果实称聚合果，\n\n如草莓和莲蓬。（单花多雌蕊）\n\n③聚花果（复果）\n\n整个花序上的很多花发育成一个果实的聚合体，就称为聚花果。如桑\n\n葚和菠萝。（多花多雌蕊）","chapterNo":22,"chapterTitle":"植物的结构与生殖","source":"term_doc","answerStatus":"reference","qid":"TERM-0480"},{"term":"双子叶植物茎、单子叶植物茎结构及特点，双子植物和单子叶植物茎的结构有","answer":"什么不同。","chapterNo":22,"chapterTitle":"植物的结构和生殖（补充拓展）","source":"term_doc","answerStatus":"reference","qid":"TERM-0481"},{"term":"何为被子植物？其生活史有哪些特点？论述被子植物的生活史，为什么说被","answer":"子植物的生活史有世代交替的现象？","chapterNo":22,"chapterTitle":"植物的结构和生殖（补充拓展）","source":"term_doc","answerStatus":"reference","qid":"TERM-0482"},{"term":"蒸腾作用","answer":"植物的叶或其他暴露在外面的部分丢失水分的过程。\n\n(蒸腾作用不仅受外界环境条件的影响，而且还受植物本身的调节和\n\n控制，因此它是一种复杂的生理过程。其主要过程为：土壤中的水分\n\n→根毛→根内导管→茎内导管→叶内导管→气孔→大气。植物幼小时，\n\n暴露在空气中的全部表面都能蒸腾。)","chapterNo":23,"chapterTitle":"植物的营养","source":"term_doc","answerStatus":"reference","qid":"TERM-0483"},{"term":"共质体","answer":"细胞间通过胞间连丝将原生质连接成的整体。(它与外部介质相通，\n\n是水分和养分可以自由出入的地方，养分迁移速率较快。在共质体运\n\n输中，胞间连丝起着沟通相邻细胞间养分运输的桥梁作用。)","chapterNo":23,"chapterTitle":"植物的营养","source":"term_doc","answerStatus":"reference","qid":"TERM-0484"},{"term":"根压","answer":"根细胞会主动将无机离子泵入木质部，而内皮层会使离子在木质部中\n\n积累。当离子积累到一定程度时，水分就会通过渗透作用进人木质部，\n\n从而推动木质部汁液向上移动的压力。","chapterNo":23,"chapterTitle":"植物的营养","source":"term_doc","answerStatus":"reference","qid":"TERM-0485"},{"term":"压流模型","answer":"植物体内有机分子在韧皮部运输的机制；运输的动力来源是运输的两\n\n端存在蔗糖浓度的压力差；受蔗糖浓度的压力差驱动，蔗糖液从浓度\n\n高处向浓度低处流动；同时可不断从运输途径的周围组织补充水分，\n\n确保运输流不断流动。","chapterNo":23,"chapterTitle":"植物的营养","source":"term_doc","answerStatus":"reference","qid":"TERM-0486"},{"term":"必需元素","answer":"是在生物的生活中，不可代替的、不可缺少的元素。例如，人体有\n\n25 种必需元素，植物有 17 种必需元素。必需元素包括大量元素和微\n\n量元素，大量元素包括 C、H、O、N、P、S、K、Ca、Mg 等，微量元素\n\n包括 Fe、Mn、Zn、Cu、B、Mo 等。","chapterNo":23,"chapterTitle":"植物的营养","source":"term_doc","answerStatus":"reference","qid":"TERM-0487"},{"term":"水培法","answer":"将植物的根部浸泡在溶液中并通入空气进行培养的方法。可以用来确\n\n定植物的必需元素。","chapterNo":23,"chapterTitle":"植物的营养","source":"term_doc","answerStatus":"reference","qid":"TERM-0488"},{"term":"根瘤植物","answer":"根上常形成各种形状的瘤状突起，称为根瘤。根瘤是土壤中的固氮菌\n\n与植物根的共生体。这种共生体是双方互惠的，植物供给固氮菌以光\n\n合产物，固氮菌所固定的氮供应本身和寄主植物的需要，还将多余的\n\nNH4+分泌到土壤中，增加土壤肥力。","chapterNo":23,"chapterTitle":"植物的营养","source":"term_doc","answerStatus":"reference","qid":"TERM-0489"},{"term":"菌根","answer":"土壤中某些真菌与植物根的共生体。这种共生体是双方互惠的，植物\n\n供给真菌以光合产物，真菌帮助植物吸收更多的水分和养分，还可能\n\n保护植物免受病原微生物的侵害。","chapterNo":23,"chapterTitle":"植物的营养","source":"term_doc","answerStatus":"reference","qid":"TERM-0490"},{"term":"非共质体途径","answer":"土壤中的溶液浸渗到根毛及根表皮细胞的细胞壁，在相邻细胞的细胞\n\n壁和细胞间隙中运行的途径。只有遇到内皮层时，这条途径才被打断。\n\n亦称作质体外途径。","chapterNo":23,"chapterTitle":"植物的营养","source":"term_doc","answerStatus":"reference","qid":"TERM-0491"},{"term":"共质体途径","answer":"指水分从一个细胞的细胞质经过胞间连丝，移动到另一个细胞的细胞\n\n质，形成一个细胞质的连续体，移动速度较慢。","chapterNo":23,"chapterTitle":"植物的营养","source":"term_doc","answerStatus":"reference","qid":"TERM-0492"},{"term":"传递细胞","answer":"是一种特化的薄壁组织细胞，其细胞壁向胞腔内突入，形成许多不规\n\n则突起，使质膜的表面积增加，并且富有胞间连丝，有利于物质的运\n\n送传递。这类细胞多分布在植物体内溶质大量集中、短距离运输频繁\n\n的部位。","chapterNo":23,"chapterTitle":"植物的营养","source":"term_doc","answerStatus":"reference","qid":"TERM-0493"},{"term":"蒸腾拉力","answer":"由于植物的蒸腾作用而产生一系列水势梯度，使导管中的水分上升的\n\n一种力量。","chapterNo":23,"chapterTitle":"植物的营养","source":"term_doc","answerStatus":"reference","qid":"TERM-0494"},{"term":"内聚力学说","answer":"蒸腾作用(日光能等)拉动一长串水分子，内聚力使这串水分子连在一\n\n起，而黏附力则有助于其向上的移动。植物并不需要消耗自身的能量\n\n使汁液上运，使之上运行的是外力，即内聚力和黏附力，尤其重要的\n\n是日光能，这些力量使水分和溶于其中的溶质从根部运到上部。","chapterNo":23,"chapterTitle":"植物的营养","source":"term_doc","answerStatus":"reference","qid":"TERM-0495"},{"term":"无机离子泵学说/K+泵学说","answer":"当保卫细胞从周围的细胞中得到 k+时，水就会由于渗透作用进入其\n\n液泡内，于是细胞呈膨胀状态；由于保卫细胞的壁厚度不均匀，细胞\n\n吸水后，较薄的壁膨胀较多，细胞弓起来，使气孔张开；当保卫细胞\n\n丢失 k+，水分也丢失，细胞失去膨胀状态，气孔关闭。","chapterNo":23,"chapterTitle":"植物的营养","source":"term_doc","answerStatus":"reference","qid":"TERM-0496"},{"term":"固氮菌","answer":"能将大气中的 N2 转化为铵(NH4＋)的细菌，这个过程称为固氮作用。","chapterNo":23,"chapterTitle":"植物的营养","source":"term_doc","answerStatus":"reference","qid":"TERM-0497"},{"term":"固氮作用","answer":"能将大气中的 N2 转化为铵(NH4＋)的细菌，这个过程称为固氮作用。","chapterNo":23,"chapterTitle":"植物的营养","source":"term_doc","answerStatus":"reference","qid":"TERM-0498"},{"term":"氨化细菌","answer":"能够使土壤中的有机物分解产物最终转变为 NH4＋的细菌。","chapterNo":23,"chapterTitle":"植物的营养","source":"term_doc","answerStatus":"reference","qid":"TERM-0499"},{"term":"异养植物","answer":"必须依靠外界摄取有机物的植物，分为寄生植物和食虫植物。寄生植\n\n物是指从绿色植物获取养分的植物，如菟丝子。食虫植物是指从动物\n\n(昆虫)获取养分的植物，如猪笼草。","chapterNo":23,"chapterTitle":"植物的营养","source":"term_doc","answerStatus":"reference","qid":"TERM-0500"},{"term":"顶端优势","answer":"植物顶芽分泌抑制腋芽生长的激素，而导致只有顶芽更易生长的现象。\n\n(为了促使主干长得又高又直，就要维护植物的顶端优势，任它自由\n\n生长并及时除去侧芽。)","chapterNo":24,"chapterTitle":"植物的调控系统","source":"term_doc","answerStatus":"reference","qid":"TERM-0501"},{"term":"向光性","answer":"植物的枝叶向着光的生长称为向光性。向光性是植物的一种适应特性，\n\n使得植物能够获得最大量的光，有效地进行光合作用。(它是由于植\n\n物背光侧的生长素分布较多，使得背光侧的细胞较大，向光侧的细胞\n\n较小而引起的。)","chapterNo":24,"chapterTitle":"植物的调控系统","source":"term_doc","answerStatus":"reference","qid":"TERM-0502"},{"term":"春化作用","answer":"一些植物必须经历一定的低温，才能形成花原基，进行花芽分化。低\n\n温诱导花原基形成的作用称为春化作用。","chapterNo":24,"chapterTitle":"植物的调控系统","source":"term_doc","answerStatus":"reference","qid":"TERM-0503"},{"term":"光敏素（2025 名词解释）","answer":"一种对红光和远红光的吸收有逆转效应、参与光形态建成、调节植物\n\n发育的色素蛋白。(有两种形式，一种形式吸收红光称为 Pr,另一种\n\n形式吸收远红光，称为 Pfr,Pr 吸收红光后转变为 Pfr,Pfr 吸收远红\n\n光后转变为 Pr,白天照射的太阳光中红光比远红光多得多，Pr 都转化\n\n为 Pfr,在夜间，Pfr 缓慢转变为 Pr。植物的光敏素可测知夜间的长\n\n短，其转变不仅引发开花的响应，也引发其它生理过程，如气孔开关、\n\n种子萌发等的响应","chapterNo":24,"chapterTitle":"植物的调控系统","source":"term_doc","answerStatus":"reference","qid":"TERM-0504"},{"term":"光周期（2013、15、17、18、19 年名词解释）","answer":"光周期是昼夜周期中光照期和暗期长短的交替变化。(植物通过光周\n\n期，即昼夜的长短来感觉一年中时间的变化，昼夜长短的变化影响着\n\n植物的许多过程，其中最显著的和最重要的就是开花过程，控制植物\n\n开花的并不是日照的长度，而是夜间的长度。根据开花与光周期的关\n\n系，可把植物划分为长夜植物和短夜植物。)","chapterNo":24,"chapterTitle":"植物的调控系统","source":"term_doc","answerStatus":"reference","qid":"TERM-0505"},{"term":"长日植物(短夜植物)","answer":"在 24 小时昼夜周期中，只有黑暗时间短于一定的长度才会开花的植\n\n物。如延长光照或在暗期短期照光可促进或提早开花；相反，如延长\n\n黑暗则推迟开花或不能成花。典型的长日照植物有天仙子、小麦等。","chapterNo":24,"chapterTitle":"植物的调控系统","source":"term_doc","answerStatus":"reference","qid":"TERM-0506"},{"term":"短日植物(长夜植物)","answer":"在 24 小时昼夜周期中，只有黑暗时间长于一定的长度才会开花的植\n\n物。如延长黑暗或缩短光照可促进或提早开花；相反，如延长日照则\n\n推迟开花或不能成花。典型的短日植物有晚稻、菊花等。","chapterNo":24,"chapterTitle":"植物的调控系统","source":"term_doc","answerStatus":"reference","qid":"TERM-0507"},{"term":"成花素","answer":"植物营养生长过程中，叶片在合成碳水化合物和含氮化合物的同时，\n\n也合成一种成长激素，称为成花素。当成花素达到一定浓度时，能诱\n\n导碳水化合物贮藏在生长点细胞的原生质中，引起变质，形成花芽。\n\n这就是成花素学说。","chapterNo":24,"chapterTitle":"植物的调控系统","source":"term_doc","answerStatus":"reference","qid":"TERM-0508"},{"term":"生物节律","answer":"植物和动物在自然界中的活动都是有节律的，以日为周期的昼夜节律，\n\n以月为周期的月周期节律，或年为周期的年节律。生物节律是在生物\n\n长期进化过程中适应地球的自然条件，如昼夜、冬夏、潮汐等而发生\n\n的。节律是生物的基本特征之一，广泛存在的节律使生物能更好地适\n\n应外环境，并通过适配的相位关系保持生命过程的协调统一。","chapterNo":24,"chapterTitle":"植物的调控系统","source":"term_doc","answerStatus":"reference","qid":"TERM-0509"},{"term":"光周期现象","answer":"光周期现象是植物对昼夜光暗循环格局的反应。植物在生长发育进程\n\n中必须经过一定时间的适宜光周期后才能开花，否则一直处于营养生\n\n长状态。这种昼夜长短影响植物开花的效应叫做光周期现象。","chapterNo":24,"chapterTitle":"植物的调控系统","source":"term_doc","answerStatus":"reference","qid":"TERM-0510"},{"term":"光周期诱导","answer":"在一定时间内给予适宜的光周期影响，以后即使置于不适宜的光周期\n\n条件下，而光周期的影响仍可持续下去，这种现象称为光周期诱导。\n\n(如短日照植物的大豆经过 2—3 次、苍耳经过 1 次、菊花经过 8—30\n\n次的短日照处理，以后即使在长日照条件下花芽也能分化。长日照植\n\n物的天仙子属经 72 小时连续光照，然后即使放在短日照条件下花芽\n\n也能分化。）","chapterNo":24,"chapterTitle":"植物的调控系统","source":"term_doc","answerStatus":"reference","qid":"TERM-0511"},{"term":"生长素","answer":"生长素的本质是吲哚乙酸(IAA)。IAA 主要是在植物茎尖、根尖、幼\n\n叶、胚中合成，然后由形态学上端向形态学下端运输，使细胞伸长从\n\n而促进茎或根的生长。其作用机制是生长素使细胞壁环境酸化，增加\n\n可塑性，从而引起其伸长，也能促进茎的长粗。","chapterNo":24,"chapterTitle":"植物的调控系统","source":"term_doc","answerStatus":"reference","qid":"TERM-0512"},{"term":"酸生长学说","answer":"生长素刺激植物细胞膜中的质子泵，把质子(H+)泵入细胞壁，导致细\n\n胞壁基质溶液的 PH 下降。在酸性条件下，H＋又活化某种酶使之打断\n\n细胞壁中的纤维素分子交联起来的氢键，使细胞壁变得松散。由于细\n\n胞壁变得松散，细胞的压力势下降，细胞吸水，体积增大而发生不可\n\n逆增长。细胞进一步合成壁物质和细胞质，使细胞继续伸长。","chapterNo":24,"chapterTitle":"植物的调控系统","source":"term_doc","answerStatus":"reference","qid":"TERM-0513"},{"term":"细胞分裂素","answer":"可促进细胞分裂，延迟花和果实的衰老。在植物体内，细胞分裂素的\n\n作用常受生长素浓度的影响，来自顶芽的生长素和来自根的细胞分裂\n\n素相互对抗，分别促进顶芽与侧芽的生长，于是出现了不同的生长形\n\n式。","chapterNo":24,"chapterTitle":"植物的调控系统","source":"term_doc","answerStatus":"reference","qid":"TERM-0514"},{"term":"赤霉素","answer":"赤霉素主要作用是促进茎和叶的生长，加强生长素的作用；赤霉素和\n\n生长素在一起，能影响果实的发育，形成无籽果实；赤霉素对许多植\n\n物的种子萌发很重要，能调动休眠胚中的代谢过程，使胚恢复生长；\n\n有些植物中，赤霉素和其他激素(如脱落酸)之间有拮抗作用。","chapterNo":24,"chapterTitle":"植物的调控系统","source":"term_doc","answerStatus":"reference","qid":"TERM-0515"},{"term":"脱落酸","answer":"对于多数植物而言，脱落酸是影响种子休眠最重要的因素，它是生长\n\n抑制剂，赤霉素与脱落酸之比决定种子萌发和芽的休眠；脱落酸也起\n\n着“胁迫激素”的作用，帮助植物协调不利的环境。","chapterNo":24,"chapterTitle":"植物的调控系统","source":"term_doc","answerStatus":"reference","qid":"TERM-0516"},{"term":"乙烯","answer":"乙烯引发果实的成熟，包括细胞壁的降解、颜色的变化，有时还有失\n\n水；乙烯促进落叶。引发落叶的环境因素有秋季的短日照和低温，它\n\n们会引起乙烯与生长素比例的变化，而乙烯促进一些分解细胞壁物质\n\n的酶的形成。","chapterNo":24,"chapterTitle":"植物的调控系统","source":"term_doc","answerStatus":"reference","qid":"TERM-0517"},{"term":"组织","answer":"是由一种或多种细胞组合而成的细胞群体，在机体中起着某种特定的\n\n作用。脊椎动物体内有上皮组织、结缔组织、肌肉组织和神经组织 4\n\n种基本组织。","chapterNo":25,"chapterTitle":"脊椎动物的结构与功能","source":"term_doc","answerStatus":"reference","qid":"TERM-0518"},{"term":"器官","answer":"多细胞动物中由多种组织组成，以完成一种或几种特定功能。例如胃\n\n是由浆膜层、肌肉层、黏膜下层、黏膜层组成，可见，胃是由上皮组\n\n织、肌肉组织、结缔组织、神经组织构成的。","chapterNo":25,"chapterTitle":"脊椎动物的结构与功能","source":"term_doc","answerStatus":"reference","qid":"TERM-0519"},{"term":"系统","answer":"多个相关的器官组成的能完成特定功能的集合体。人体至少可以分为\n\n11 个功能系统，包括皮肤系统、骨骼系统、肌肉系统、消化系统、\n\n呼吸系统、排泄系统、生殖系统、神经系统、内分泌系统、循环系统、\n\n淋巴和免疫系统。","chapterNo":25,"chapterTitle":"脊椎动物的结构与功能","source":"term_doc","answerStatus":"reference","qid":"TERM-0520"},{"term":"内环境","answer":"内环境是指细胞在体内直接所处的环境，即细胞外液，包括血浆、组\n\n织液、淋巴等。内环境的稳定是独立自由的生命的条件，这主要是由\n\n于细胞的代谢过程基本上都是酶促反应，要求最合适的温度、PH,要\n\n求一定的离子浓度、底物浓度等，失去了这些条件，代谢活动就不能\n\n正常进行，细胞的生存就会出现危机。","chapterNo":25,"chapterTitle":"脊椎动物的结构与功能","source":"term_doc","answerStatus":"reference","qid":"TERM-0521"},{"term":"结缔组织","answer":"结缔组织是脊椎动物的四种基本组织之一。结缔组织由结缔组织细胞、\n\n3 种蛋白质纤维和无定型基质构成。其特点是有发达的细胞间质，细\n\n胞分散于细胞介质之中。结缔组织可分为疏松结缔组织、致密结缔组\n\n织、软骨、骨、脂肪组织、血液和淋巴，起着连接和支持其他组织的\n\n作用。","chapterNo":25,"chapterTitle":"脊椎动物的结构与功能","source":"term_doc","answerStatus":"reference","qid":"TERM-0522"},{"term":"神经组织","answer":"神经组织是脊椎动物的四种基本组织之一。神经组织由神经细胞(神\n\n经元)和神经胶质细胞构成。神经细胞包括胞体和突起两部分，突起\n\n又分为树突与轴突，作用是感受刺激并传导神经冲动；神经胶质细胞\n\n也有突起，但无树突和轴突之分，对神经元起着支持、营养和屏障作\n\n用。","chapterNo":25,"chapterTitle":"脊椎动物的结构与功能","source":"term_doc","answerStatus":"reference","qid":"TERM-0523"},{"term":"上皮组织","answer":"上皮组织是脊椎动物的四种基本组织之一。上皮组织由上皮细胞构成，\n\n上皮细胞与上皮细胞之间紧密连接，形成连续的片状结构，覆盖在人\n\n体的外表面、体腔和各种管道的内表面，有多种类型，具有保护、吸\n\n收和分泌的作用。","chapterNo":25,"chapterTitle":"脊椎动物的结构与功能","source":"term_doc","answerStatus":"reference","qid":"TERM-0524"},{"term":"肌肉组织","answer":"肌肉细胞是脊椎动物的四种基本组织之一。肌肉组织由肌细胞构成，\n\n分为骨骼肌、心肌、平滑肌三种，在动物的运动中发挥作用。","chapterNo":25,"chapterTitle":"脊椎动物的结构与功能","source":"term_doc","answerStatus":"reference","qid":"TERM-0525"},{"term":"外环境","answer":"是指某一特定生物体以外的空间，及直接、间接影响该生物体生存的\n\n一切事物的总和，如大气中的氧气，二氧化碳，阳光等。","chapterNo":25,"chapterTitle":"脊椎动物的结构与功能","source":"term_doc","answerStatus":"reference","qid":"TERM-0526"},{"term":"疏松结缔组织","answer":"3 种蛋白质纤维交织成疏松的网形，其间是固定的细胞和无定形的基\n\n质。广泛存在于多种器官之中和组织之间，起着联络和固定的作用。\n\n如血液与脂肪组织。","chapterNo":25,"chapterTitle":"脊椎动物的结构与功能","source":"term_doc","answerStatus":"reference","qid":"TERM-0527"},{"term":"致密结缔组织","answer":"由密集的胶原纤维和丰富的成纤维细胞构成，弹性纤维和无定型基质\n\n少。如骨、软骨、骨韧带和肌腱。","chapterNo":25,"chapterTitle":"脊椎动物的结构与功能","source":"term_doc","answerStatus":"reference","qid":"TERM-0528"},{"term":"反馈（2021 名词解释）","answer":"反馈指在一个系统中,将输出改变后的效果送回一部分给敏感元件以\n\n调节输出的过程。反馈有两种:负反馈:指一个系统产物输出量增加的\n\n信息传送到敏感元件，引起这个系统的输出减少。正反馈:指一个系\n\n统产物输出量增加的信息传送到敏感元件，引起这个系统的输出增加。","chapterNo":25,"chapterTitle":"脊椎动物的结构与功能","source":"term_doc","answerStatus":"reference","qid":"TERM-0529"},{"term":"异养","answer":"生物自身不能从简单的无机物制造有机物，也不能从日光中获得能量，\n\n必须从外界环境中获得有机物，并从这些有机物中获得生命活动所需\n\n的能量的生活方式。如动物、真菌、和大多数细菌。","chapterNo":26,"chapterTitle":"营养与消化","source":"term_doc","answerStatus":"reference","qid":"TERM-0530"},{"term":"自养","answer":"生物只从外界吸收简单的无机物，利用光合作用制造有机物，提供本\n\n身代谢所需的能量，是生物自己供养自己，不需要其他生物的生活方\n\n式。如绝大多数绿色植物、蓝藻、光合细菌。","chapterNo":26,"chapterTitle":"营养与消化","source":"term_doc","answerStatus":"reference","qid":"TERM-0531"},{"term":"营养素","answer":"食物中能够被人体消化吸收和利用，可给人体提供能量、机体构成成\n\n分和组织修复以及生理调节功能的的物质。人体必需的营养素有水、\n\n糖类、蛋白质、脂质、维生素和矿物质等。(在消化过程中，糖类被\n\n分解为六碳糖，蛋白质分解为氨基酸，脂肪分解为甘油和脂肪酸。)","chapterNo":26,"chapterTitle":"营养与消化","source":"term_doc","answerStatus":"reference","qid":"TERM-0532"},{"term":"必需氨基酸","answer":"是指机体生命活动必不可少，但机体自身又不能合成，必须由食物供\n\n给的氨基酸。成人的必需氮基酸有：缬氨酸、异亮氨酸、亮氨酸、苯\n\n丙氨酸、甲硫氨酸、色氨酸、苏氨酸、赖氨酸。婴儿还需要组氨酸。","chapterNo":26,"chapterTitle":"营养与消化","source":"term_doc","answerStatus":"reference","qid":"TERM-0533"},{"term":"消化","answer":"摄入的食物经过机械作用粉碎和化学作用分解后形成的结构简单、溶\n\n于水的小分子物质的过程，即把食物变成可以被机体吸收养料的过程。\n\n根据消化类型的不同可以分为细胞外消化和细胞内消化。","chapterNo":26,"chapterTitle":"营养与消化","source":"term_doc","answerStatus":"reference","qid":"TERM-0534"},{"term":"吸收","answer":"机体从环境中摄取营养物质到体内，进而使简单的小分子穿过细胞膜\n\n进入细胞内的过程。食物在消化道内经过消化，最终分解成葡萄糖、\n\n氨基酸等能够被人体吸收的物质。","chapterNo":26,"chapterTitle":"营养与消化","source":"term_doc","answerStatus":"reference","qid":"TERM-0535"},{"term":"胞内消化","answer":"是指整个摄食过程，包括摄入、消化、吸收和排出都在一个细胞内进\n\n行的消化过程。单细胞原生动物都进行胞内消化。","chapterNo":26,"chapterTitle":"营养与消化","source":"term_doc","answerStatus":"reference","qid":"TERM-0536"},{"term":"胞外消化","answer":"是指食物在细胞外的消化腔或消化管中进行的消化过程。这一过程突\n\n破了只能摄取细胞所能吞噬的小颗粒食物的胞内消化限制，使动物可\n\n以利用的食物种类增加，有利于动物的生存和发展。多细胞动物进行\n\n胞外消化。","chapterNo":26,"chapterTitle":"营养与消化","source":"term_doc","answerStatus":"reference","qid":"TERM-0537"},{"term":"必须脂肪酸","answer":"是指机体生命活动必不可少，但机体自身又不能合成，必须由食物供\n\n给的多不饱和脂肪酸。必需脂肪酸主要包括亚麻酸和亚油酸。","chapterNo":26,"chapterTitle":"营养与消化","source":"term_doc","answerStatus":"reference","qid":"TERM-0538"},{"term":"维生素","answer":"维生素是一系列小分子有机化合物的统称。它们是生物体所需要的微\n\n量营养成分，而一般又无法由生物体自己生产，需要通过饮食等手段\n\n获得。维生素既不像糖类、蛋白质及脂肪那样是构成身体的原料，它\n\n也无法产生能量、组成细胞，但它们能够对生物体的新陈代谢起调节\n\n作用。","chapterNo":26,"chapterTitle":"营养与消化","source":"term_doc","answerStatus":"reference","qid":"TERM-0539"},{"term":"小肠微绒毛","answer":"是小肠的一种特殊的结构。小肠绒毛是小肠黏膜形成的指状突起，绒\n\n毛上的柱状上皮细胞面向肠腔的一端细胞膜突起，形成很多的小肠微\n\n绒毛。微绒毛的存在增大了吸收的表面积，有利于小肠大量吸收营养\n\n物质。","chapterNo":26,"chapterTitle":"营养与消化","source":"term_doc","answerStatus":"reference","qid":"TERM-0540"},{"term":"基础代谢率","answer":"基础代谢率是指如果人体不进行体力活动和脑力活动，只维持清醒状\n\n态，在单位时间内生命活动所需要的最低能量。这些能量绝大部分用\n\n于维持心脏、肝、肾、脑等重要内脏器官的活动。同一人的基础代谢\n\n率相当稳定。","chapterNo":26,"chapterTitle":"营养与消化","source":"term_doc","answerStatus":"reference","qid":"TERM-0541"},{"term":"不完全蛋白质","answer":"不含全部必需氨基酸的蛋白质称为不完全蛋白质，如某些植物蛋白质。","chapterNo":26,"chapterTitle":"营养与消化","source":"term_doc","answerStatus":"reference","qid":"TERM-0542"},{"term":"完全蛋白质","answer":"含全部必需氨基酸的蛋白质称为完全蛋白质，如动物蛋白质（除明胶\n\n蛋白质外）。","chapterNo":26,"chapterTitle":"营养与消化","source":"term_doc","answerStatus":"reference","qid":"TERM-0543"},{"term":"必需矿物质","answer":"是指那些必须由饮食供应的，对维持生命活动、促进生长和生殖有重\n\n要作用的无机物。缺了这些矿物质，人体的正常功能就会受到阻碍，\n\n引起疾病。","chapterNo":26,"chapterTitle":"营养与消化","source":"term_doc","answerStatus":"reference","qid":"TERM-0544"},{"term":"消化系统","answer":"消化系统实质上是从口到肛门的一条管道，包括口腔、咽、食道、胃、\n\n小肠、大肠及直肠等部分。食物进入消化系统后，被管道的运动所推\n\n动，在移动中逐步被分割、分解，直至成为简单的小分子，穿过细胞\n\n膜进入细胞，再被运送到全身。","chapterNo":26,"chapterTitle":"营养与消化","source":"term_doc","answerStatus":"reference","qid":"TERM-0545"},{"term":"分节运动","answer":"是小肠特有的一种混合性运动。小肠通过环行肌收缩和舒张的反复进\n\n行，使食糜与消化液充分混合，与肠壁广泛接触，有利于食物的消化\n\n与吸收。","chapterNo":26,"chapterTitle":"营养与消化","source":"term_doc","answerStatus":"reference","qid":"TERM-0546"},{"term":"蠕动冲","answer":"是一种行进速度很快、行进距离较长的蠕动，小肠黏膜在受到微生物\n\n和化学物质的强烈刺激时常会引起蠕动冲，它可以快速地将有刺激性\n\n的物质排出小肠。","chapterNo":26,"chapterTitle":"营养与消化","source":"term_doc","answerStatus":"reference","qid":"TERM-0547"},{"term":"集团运动","answer":"指横结肠和降结肠发生的一段长约 20cm 的收缩运动。在这一范围内\n\n将粪便压缩成团块并推动粪团到达直肠，从而使人产生排便的感觉。","chapterNo":26,"chapterTitle":"营养与消化","source":"term_doc","answerStatus":"reference","qid":"TERM-0548"},{"term":"反刍（chu）","answer":"部分草食哺乳动物具有“反刍”功能，如长颈鹿、鹿、骆驼、牛、绵\n\n羊、山羊等，多数反刍动物具有 4 个胃，即瘤胃、网胃、瓣胃和皱胃。\n\n反刍动物采食草茎，吞入瘤胃，休息时将瘤胃中的食物经食道送回口\n\n腔，经仔细咀嚼后再吞入胃内，在瘤胃中纤维素经微生物分解，产生\n\n的食糜进入瓣胃和皱胃，由反刍动物自身的消化液进行消化。","chapterNo":26,"chapterTitle":"营养与消化","source":"term_doc","answerStatus":"reference","qid":"TERM-0549"},{"term":"体液","answer":"体内以水作为基础的液体，按所在位置分为细胞内液和细胞外液。细\n\n胞内液是存在于细胞内的液体，细胞外液是存在于细胞外的液体，包\n\n括组织液、血浆、淋巴液等。","chapterNo":27,"chapterTitle":"血液与循环","source":"term_doc","answerStatus":"reference","qid":"TERM-0550"},{"term":"血液凝固","answer":"是指血液从流动的液体状态变成不能流动的凝胶状态的过程，是一个\n\n复杂的过程。包括凝血酶原复合物的形成、凝血酶原的激活、纤维蛋\n\n白的生成等过程。","chapterNo":27,"chapterTitle":"血液与循环","source":"term_doc","answerStatus":"reference","qid":"TERM-0551"},{"term":"心动周期","answer":"每次心脏搏动，由收缩到舒张的过程。一般以心房开始收缩为起点。\n\n心动周期包括心房和心室的收缩期和舒张期。通常心动周期指心室的\n\n活动周期。","chapterNo":27,"chapterTitle":"血液与循环","source":"term_doc","answerStatus":"reference","qid":"TERM-0552"},{"term":"高血压","answer":"人体超过 140/90mmHg 的血压。高血压由微动脉的过度收缩造成的，\n\n如不及时治疗会引起心脏的劳损。","chapterNo":27,"chapterTitle":"血液与循环","source":"term_doc","answerStatus":"reference","qid":"TERM-0553"},{"term":"粥样动脉硬化","answer":"动脉内膜中沉积含胆固醇的脂肪，形成粥样斑块，可引发血栓、心绞\n\n痛、局部心肌梗死以及中风等。(动脉粥样硬化治疗的关键在于预防，\n\n包括积极治疗高血压，减少血液黏度、减少血液中过高的低密度胆固\n\n醇含量，防止血栓形成，抑制血小板的功能等)","chapterNo":27,"chapterTitle":"血液与循环","source":"term_doc","answerStatus":"reference","qid":"TERM-0554"},{"term":"动脉","answer":"指在肺循环和体循环中，从心脏输送血液出去的管道。连通心室，主\n\n动脉连左心室，肺动脉连右心室。(动脉管径较粗，有一层弹性组织，\n\n主要功能是把血液从心脏引导到机体各部分，并可作为有弹性的血库，\n\n调节血量和血压，使心脏的间断性射血转变成动脉中持续不断的血\n\n流。)","chapterNo":27,"chapterTitle":"血液与循环","source":"term_doc","answerStatus":"reference","qid":"TERM-0555"},{"term":"静脉","answer":"指在肺循环和体循环中，从肺或其他组织输送血液回心脏的管道，连\n\n通心房，上下腔静脉连右心房，肺静脉连左心房。(静脉的管壁比动\n\n脉薄得多，弹性也较低。主要功能是从身体各部分的毛细血管将血液\n\n引导回心脏和储存血液。)","chapterNo":27,"chapterTitle":"血液与循环","source":"term_doc","answerStatus":"reference","qid":"TERM-0556"},{"term":"双循环","answer":"是人和哺乳动物的血液循环方式，包括肺循环和体循环。（2013 名\n\n词解释）\n\n体循环指血液往返于心和全身各组织器官之间的循环。血液由左心室\n\n射出，经主动脉及各级分支流到全身的毛细血管，在此与组织液进行\n\n物质交换，供给组织细胞氧和营养物质，运走二氧化碳和代谢产物，\n\n动脉血变成静脉血，再汇合到上下腔静脉，流回右心房。\n\n肺循环是指血液往返于心和肺之间的循环。血液由右心室射出，经肺\n\n动脉流到肺毛细血管，在此与肺泡进行气体交换，吸走氧并排出二氧\n\n化碳，静脉血变为动脉血，然后经肺静脉，流回左心房。","chapterNo":27,"chapterTitle":"血液与循环","source":"term_doc","answerStatus":"reference","qid":"TERM-0557"},{"term":"冠状动脉循环","answer":"是指供应心脏本身的血液循环。大动脉在离开心脏处分出两个冠状动\n\n脉，在心脏厚壁中分支而成毛细血管网，分布于心脏壁的各部分，再\n\n流入小静脉、冠状静脉等，最后流入右心房。\n\n(冠状动脉硬化或堵塞将引起心肌死亡。)","chapterNo":27,"chapterTitle":"血液与循环","source":"term_doc","answerStatus":"reference","qid":"TERM-0558"},{"term":"微循环","answer":"在封闭的血液循环系统中介于微动脉与微静脉间的一套微细的血管\n\n系统，血液和组织液之间的交换通过毛细血管来进行。","chapterNo":27,"chapterTitle":"血液与循环","source":"term_doc","answerStatus":"reference","qid":"TERM-0559"},{"term":"凝集素","answer":"血清中能与凝集原特异性结合的抗体。同名的凝集原和凝集素相遇\n\n(如凝集原 A 和抗 A 凝集素)会发生红细胞凝集。(凝集素是一种从各\n\n种植物，无脊椎动物和高等动物中提纯的糖蛋白或结合糖的蛋白，因\n\n其能凝集红血球(含血型物质),故名凝集素。)","chapterNo":27,"chapterTitle":"血液与循环","source":"term_doc","answerStatus":"reference","qid":"TERM-0560"},{"term":"凝集原","answer":"红细胞膜上的抗原物质，由糖蛋白和糖脂构成。同名的凝集原和凝集\n\n素相遇(如凝集原 A 和抗 A 凝集素)会发生红细胞凝集。","chapterNo":27,"chapterTitle":"血液与循环","source":"term_doc","answerStatus":"reference","qid":"TERM-0561"},{"term":"血液","answer":"血液是在人与动物机体的血管及心脏内循环流动的红色液体，由血浆\n\n与血细胞构成。","chapterNo":27,"chapterTitle":"血液与循环","source":"term_doc","answerStatus":"reference","qid":"TERM-0562"},{"term":"血浆","answer":"人的血浆是淡黄色的液体，约占血液体积的 1/2。由水、晶状物质、\n\n胶体物质和一些其他物质组成。","chapterNo":27,"chapterTitle":"血液与循环","source":"term_doc","answerStatus":"reference","qid":"TERM-0563"},{"term":"血细胞","answer":"血细胞分为红细胞、白细胞和血小板。红细胞的功能是运输氧和二氧\n\n化碳，白细胞的功能是保护机体，抵御外来微生物的侵袭，血小板的\n\n功能是参与止血和凝血过程。","chapterNo":27,"chapterTitle":"血液与循环","source":"term_doc","answerStatus":"reference","qid":"TERM-0564"},{"term":"血清","answer":"血清是指血凝块在血小板的作用下发生收缩并析出的淡黄色液体。血\n\n清和血浆的区别是血清中除去了纤维蛋白原和少量的参与凝血的血\n\n浆蛋白。","chapterNo":27,"chapterTitle":"血液与循环","source":"term_doc","answerStatus":"reference","qid":"TERM-0565"},{"term":"凝血因子","answer":"是直接参与血液凝固的物质，多数在干细胞产生，可分为外源性凝血\n\n因子和内源性凝血因子，用于激活凝血酶原复合物。","chapterNo":27,"chapterTitle":"血液与循环","source":"term_doc","answerStatus":"reference","qid":"TERM-0566"},{"term":"凝集","answer":"凝集是指加入同种其他个体的血清，使均匀悬浮在血液中的红细胞聚\n\n集成团的现象，是一种免疫反应。","chapterNo":27,"chapterTitle":"血液与循环","source":"term_doc","answerStatus":"reference","qid":"TERM-0567"},{"term":"ABO 血型系统","answer":"按照红细胞和血清中凝集原与凝集素的不同，将血液分为 4 种主要类\n\n型:A 型、B 型、AB 型、O 型。","chapterNo":27,"chapterTitle":"血液与循环","source":"term_doc","answerStatus":"reference","qid":"TERM-0568"},{"term":"Rh 因子","answer":"是指在正常的红细胞上存在的其他的抗原，能够与抗 Rh 凝集素结合，\n\n使猕猴和大部分人类的红细胞凝集，Rh 因子是显性遗传。","chapterNo":27,"chapterTitle":"血液与循环","source":"term_doc","answerStatus":"reference","qid":"TERM-0569"},{"term":"Rh 血型系统","answer":"根据红细胞上 Rh 因子的有无分为 Rh 阳性血型和 Rh 阴性血型。Rh 阳\n\n性（Rh＋）:大多数人，红细胞上含有 Rh 因子，血清中无抗 Rh 凝集\n\n素，与抗 Rh 血清混合时发生凝集反应。","chapterNo":27,"chapterTitle":"血液与循环","source":"term_doc","answerStatus":"reference","qid":"TERM-0570"},{"term":"血液循环","answer":"是指血液在全身心血管系统内周而复始的循环流动的过程。在脊椎动\n\n物体内，血液循环是在心血管系统内进行的，心血管系统包括血管与\n\n心脏、血液。","chapterNo":27,"chapterTitle":"血液与循环","source":"term_doc","answerStatus":"reference","qid":"TERM-0571"},{"term":"心脏","answer":"心脏是一个中空的肌肉器官，被纵中隔和横中隔分为左心室、左心房、\n\n右心室、友心房四个部分，主要功能是为血液流动提供动力，推动血\n\n液循环。","chapterNo":27,"chapterTitle":"血液与循环","source":"term_doc","answerStatus":"reference","qid":"TERM-0572"},{"term":"毛细血管","answer":"毛细血管是指介于动脉、静脉之间的管道，几乎分布全身的各个器官，\n\n管壁极薄，由一层内皮细胞构成。血流速度缓慢，有利于血液和组织\n\n液之间的物质交换，物质交换绝大部分是通过扩散进行的。","chapterNo":27,"chapterTitle":"血液与循环","source":"term_doc","answerStatus":"reference","qid":"TERM-0573"},{"term":"起搏点","answer":"心脏的自动性节律起源于心脏的起搏点，窦房结是心脏活动的正常起\n\n搏点，当窦房结因疾病遭受损伤不能正常起搏时，房室结成为起搏点。","chapterNo":27,"chapterTitle":"血液与循环","source":"term_doc","answerStatus":"reference","qid":"TERM-0574"},{"term":"心脏传导系统","answer":"由特殊分化的心肌细胞构成，包括窦房结、房室结、房室束和浦肯野\n\n氏纤维，具有自动产生节律性兴奋的能力，主要功能是产生和传导冲\n\n动。","chapterNo":27,"chapterTitle":"血液与循环","source":"term_doc","answerStatus":"reference","qid":"TERM-0575"},{"term":"呼吸","answer":"是指机体与外界环境之间进行气体交换的过程。呼吸过程可分为内呼\n\n吸和外呼吸。","chapterNo":28,"chapterTitle":"气体交换与呼吸","source":"term_doc","answerStatus":"reference","qid":"TERM-0576"},{"term":"内呼吸","answer":"是指能源物质在细胞内的生物氧化过程，消耗氧产生高能键、二氧化\n\n碳和水等，又称细胞呼吸。","chapterNo":28,"chapterTitle":"气体交换与呼吸","source":"term_doc","answerStatus":"reference","qid":"TERM-0577"},{"term":"外呼吸","answer":"是指外界空气与血液之间交换气体的过程，即通过呼吸运动和血液循\n\n环，肺泡内的空气与肺部毛细血管内的静脉血之间不断地进行气体交\n\n换，静脉血吸入氧，排出二氧化碳，变成含氧丰富的动脉血的过程。","chapterNo":28,"chapterTitle":"气体交换与呼吸","source":"term_doc","answerStatus":"reference","qid":"TERM-0578"},{"term":"腹式呼吸","answer":"(由于呼吸时不同的肌肉活动，可以将呼吸运动分为腹式呼吸和胸式\n\n呼吸，一般情况下，人是腹式、胸式呼吸并用。)腹式呼吸指以膈肌\n\n运动为主的主动呼吸，吸气时膈肌收缩，膈下降，胸廓扩大；呼气时\n\n膈肌舒张，膈上升，胸廓缩小。","chapterNo":28,"chapterTitle":"气体交换与呼吸","source":"term_doc","answerStatus":"reference","qid":"TERM-0579"},{"term":"胸式呼吸","answer":"(由于呼吸时不同的肌肉活动，可以将呼吸运动分为腹式呼吸和胸式\n\n呼吸，一般情况下，人是腹式、胸式呼吸并用。)胸式呼吸指以肋间\n\n外肌收缩运动为主的主动呼吸，吸气时肋间外肌收缩，肋骨上升，胸\n\n廓扩大；呼气时肋间外肌舒张，肋骨下降，胸廓缩小。","chapterNo":28,"chapterTitle":"气体交换与呼吸","source":"term_doc","answerStatus":"reference","qid":"TERM-0580"},{"term":"呼气","answer":"气体进出肺的原动力是呼吸肌的收缩与舒张活动，直接动力是肺内外\n\n气压差。由于肋间肌和膈肌舒张，导致胸廓容积缩小，肺回位而体积\n\n减小，使肺内压上升，当肺内压上升至高于大气压时，气体被驱出肺，\n\n此过程称为呼气。\n\n(由于肋间肌和膈肌收缩，导致胸廓容积变大，肺被牵张而体积增大，\n\n使肺内压下降，当肺内压下降至低于大气压时，气体被吸入肺，此过\n\n程称为吸气。)","chapterNo":28,"chapterTitle":"气体交换与呼吸","source":"term_doc","answerStatus":"reference","qid":"TERM-0581"},{"term":"呼吸系统","answer":"呼吸系统包括口、鼻、咽、喉、气管、肺等器官。功能是与外界进行\n\n气体交换，吸进氧气，呼出二氧化碳。吸气时，空气经鼻或口进入咽，\n\n再经喉、气管进入肺。","chapterNo":28,"chapterTitle":"气体交换与呼吸","source":"term_doc","answerStatus":"reference","qid":"TERM-0582"},{"term":"潮气量","answer":"人在平静呼吸时每次吸入或呼出的气量。","chapterNo":28,"chapterTitle":"气体交换与呼吸","source":"term_doc","answerStatus":"reference","qid":"TERM-0583"},{"term":"补吸气量","answer":"在平静吸气后再做最大吸气动作所能增加的吸气量。","chapterNo":28,"chapterTitle":"气体交换与呼吸","source":"term_doc","answerStatus":"reference","qid":"TERM-0584"},{"term":"补呼气量","answer":"在平静呼气后再做最大呼气动作所能增加的呼气量。","chapterNo":28,"chapterTitle":"气体交换与呼吸","source":"term_doc","answerStatus":"reference","qid":"TERM-0585"},{"term":"肺活量","answer":"最大吸气后尽力呼气所能呼出的气量。","chapterNo":28,"chapterTitle":"气体交换与呼吸","source":"term_doc","answerStatus":"reference","qid":"TERM-0586"},{"term":"肺通气量","answer":"单位时间内进出肺的总气量。","chapterNo":28,"chapterTitle":"气体交换与呼吸","source":"term_doc","answerStatus":"reference","qid":"TERM-0587"},{"term":"血红蛋白","answer":"血红蛋白由一个珠蛋白分子结合 4 个血红素构成的，珠蛋白分子包括\n\n4 条链，两条α链，两条β链，每条链中包含一个血红素，每个血红\n\n素中心有一个亚铁离子，每个亚铁离子能携带一个氧分子。","chapterNo":28,"chapterTitle":"气体交换与呼吸","source":"term_doc","answerStatus":"reference","qid":"TERM-0588"},{"term":"排泄系统","answer":"排泄是指人体将分解代谢的终末产物排出体外的过程。泌尿系统是最\n\n重要的排泄系统，由肾脏、输尿管、膀胱和尿道等器官构成，作用是\n\n将流经肾的血液中的代谢废物，如含氮废物等，排出体外，维持体液\n\n渗透压的平衡和内环境的稳定。","chapterNo":29,"chapterTitle":"渗透调节与排泄","source":"term_doc","answerStatus":"reference","qid":"TERM-0589"},{"term":"肾单位","answer":"肾单位是肾的基本功能单位，每个肾有 100 万~130 万个肾单位，每\n\n个肾单位由肾小体和肾小管组成。肾小体又分为肾小球和肾小囊两部\n\n分，肾小管分为近曲小管、髓袢、远曲小管。","chapterNo":29,"chapterTitle":"渗透调节与排泄","source":"term_doc","answerStatus":"reference","qid":"TERM-0590"},{"term":"渗透调节","answer":"渗透调节是指体内盐类和水含量的调节，即体液渗透压的调节，保证\n\n了机体内水分和盐类含量的稳定，以维持机体内环境的稳定。","chapterNo":29,"chapterTitle":"渗透调节与排泄","source":"term_doc","answerStatus":"reference","qid":"TERM-0591"},{"term":"排泄","answer":"是指人体将分解代谢的终末产物排出体外的过程。细胞代谢过程所产\n\n生的废物穿过细胞膜进入组织液，再进入血浆，经由血液循环运送到\n\n相关的器官排出体外。人体参与排泄的器官有呼吸器官、消化器官、\n\n皮肤和肾等。","chapterNo":29,"chapterTitle":"渗透调节与排泄","source":"term_doc","answerStatus":"reference","qid":"TERM-0592"},{"term":"泌尿系统","answer":"泌尿系统是最重要的排泄系统，由肾、输尿管、膀胱和尿道等器官构\n\n成，作用是将流经肾的血液中的代谢废物，如含氮废物等，排出体外，\n\n维持体液渗透压的平衡和内环境的稳定。","chapterNo":29,"chapterTitle":"渗透调节与排泄","source":"term_doc","answerStatus":"reference","qid":"TERM-0593"},{"term":"肾","answer":"肾是人体最重要的渗透器官和排泄器官。肾脏包括肾实质和肾盂，肾\n\n实质又包括皮质和髓质。皮质是由肾单位组成，而肾单位由肾小体和\n\n肾小管组成，肾小体又由肾小球和肾小囊组成。髓质是由锥体和肾柱\n\n组成，而锥体的主要组织为集合管，肾柱是部分皮质伸展至髓质锥体\n\n与锥体间。其功能是清除机体内代谢的最终产物，如尿酸和尿素等，\n\n也清除机体内异物及其代谢产物，还具有渗透调节功能。","chapterNo":29,"chapterTitle":"渗透调节与排泄","source":"term_doc","answerStatus":"reference","qid":"TERM-0594"},{"term":"淋巴","answer":"组织液进人淋巴管就称为淋巴液，也称淋巴。淋巴在淋巴管内循环，\n\n最后流入静脉，是组织液流入血液的媒介。淋巴内含淋巴细胞，淋巴\n\n存在于人体的各个部分，对于人体的免疫系统有着至关重要的作用。","chapterNo":30,"chapterTitle":"免疫系统与免疫功能","source":"term_doc","answerStatus":"reference","qid":"TERM-0595"},{"term":"免疫","answer":"是指机体识别并排除抗原性异物，保护机体不受外来侵害的能力。(免\n\n疫分为先天免疫和适应性免疫，先天免疫是人体对付病原体侵袭的第\n\n二道防线，包括局灶性炎症反应、补体系统和干扰素。适应性免疫是\n\n人体对付病原体侵袭的第三道防线，包括细胞免疫和体液免疫。)","chapterNo":30,"chapterTitle":"免疫系统与免疫功能","source":"term_doc","answerStatus":"reference","qid":"TERM-0596"},{"term":"特异性免疫","answer":"如果人侵者突破了身体的第一、二道防线，第三道防线就会针对特定\n\n病原体发生特异性反应，这种作用即特异性免疫，也叫免疫应答。特\n\n异性免疫包括细胞免疫和体液免疫。","chapterNo":30,"chapterTitle":"免疫系统与免疫功能","source":"term_doc","answerStatus":"reference","qid":"TERM-0597"},{"term":"体液免疫（2013 年名词解释）","answer":"体液介导的免疫应答。主要是体液中的抗体起作用，利用抗体结合体\n\n液中的病原体。体液免疫包括感应阶段、反应阶段、效应阶段三个阶\n\n段。","chapterNo":30,"chapterTitle":"免疫系统与免疫功能","source":"term_doc","answerStatus":"reference","qid":"TERM-0598"},{"term":"细胞免疫","answer":"细胞介导的免疫应答。主要是免疫细胞(T 淋巴细胞)起作用，直接对\n\n抗被病原体感染的细胞。细胞免疫包括感应阶段、反应阶段、效应阶\n\n段三个阶段。","chapterNo":30,"chapterTitle":"免疫系统与免疫功能","source":"term_doc","answerStatus":"reference","qid":"TERM-0599"},{"term":"补体系统","answer":"简称补体，指存在于正常人或脊椎动物血清与组织液中的一类不耐热\n\n的具有酶活性的蛋白质，包括 20 余种可溶性蛋白和膜结合蛋白。\n\n(补体分子通过三种方式起作用：\n\n①聚合在一起形成孔道复合体，嵌入病原体的细胞膜，使病原体膨胀\n\n破裂而死亡。\n\n②直接附在细菌的细胞壁上，增加细菌被吞噬的概率。\n\n③刺激肥大细胞释放组胺，促进炎症反应。)","chapterNo":30,"chapterTitle":"免疫系统与免疫功能","source":"term_doc","answerStatus":"reference","qid":"TERM-0600"},{"term":"干扰素（2022 名词解释）","answer":"是受病毒感染的细胞所产生的能抵抗病毒感染的一组蛋白质。干扰素\n\n刺激自身和周围细胞，产生另一种能抵制病毒复制的蛋白质，从而抵\n\n抗感染。干扰素的产生是机体的一种保护性反应。","chapterNo":30,"chapterTitle":"免疫系统与免疫功能","source":"term_doc","answerStatus":"reference","qid":"TERM-0601"},{"term":"局灶性炎症反应","answer":"皮肤破损可使病原体微生物进入体内，引起中性白细胞和单核细胞迁\n\n移到受伤部位。单核细胞从血液进入组织后，便分化成巨噬细胞，和\n\n中性白细胞一样吞噬细菌，然后由溶酶体中的水解酶将它们消化，有\n\n四种症状：疼痛、发红、肿胀、发热。","chapterNo":30,"chapterTitle":"免疫系统与免疫功能","source":"term_doc","answerStatus":"reference","qid":"TERM-0602"},{"term":"抗原","answer":"指可以使机体产生特异性免疫应答的物质，或任何一个可以引发产生\n\n大量淋巴细胞的“非我”标志。如蛋白质、多糖类大分子等。","chapterNo":30,"chapterTitle":"免疫系统与免疫功能","source":"term_doc","answerStatus":"reference","qid":"TERM-0603"},{"term":"抗体","answer":"是指机体的免疫系统在抗原刺激下，由 B 淋巴细胞或记忆细胞增殖分\n\n化成的浆细胞所产生的、可与相应抗原发生特异性结合的免疫球蛋白。","chapterNo":30,"chapterTitle":"免疫系统与免疫功能","source":"term_doc","answerStatus":"reference","qid":"TERM-0604"},{"term":"单克隆抗体","answer":"由淋巴细胞杂交瘤产生的、只针对复合抗原分子上某一单个抗原决定\n\n簇的特异性抗体。)在人工培养的条件下，促使鼠的骨髓瘤细胞与 B\n\n淋巴细胞融合成一种杂交瘤细胞，这种杂交瘤细胞不仅能无限制的分\n\n裂生长，经过筛选，还能产生出人们所需要的特定的抗体。这种抗体\n\n就称为单克隆抗体。","chapterNo":30,"chapterTitle":"免疫系统与免疫功能","source":"term_doc","answerStatus":"reference","qid":"TERM-0605"},{"term":"免疫器官","answer":"是免疫细胞生成、成熟和集中分布的场所。根据发生的时间顺序和功\n\n能差异，可分为中枢免疫器官(骨髓、胸腺)和外周免疫器官(脾、淋\n\n巴结、扁桃体等)。","chapterNo":30,"chapterTitle":"免疫系统与免疫功能","source":"term_doc","answerStatus":"reference","qid":"TERM-0606"},{"term":"淋巴细胞","answer":"淋巴细胞是体积最小的白细胞，是特异性免疫应答中重要细胞成分，\n\n来源于骨髓中的淋巴干细胞，可分为 B 淋巴细胞和 T 淋巴细胞。(T\n\n淋巴细胞迁移到胸腺中成熟，与细胞免疫有关；B 淋巴细胞在骨髓中\n\n成熟，与体液免疫有关，两者都起源于骨髓中的淋巴干细胞。)","chapterNo":30,"chapterTitle":"免疫系统与免疫功能","source":"term_doc","answerStatus":"reference","qid":"TERM-0607"},{"term":"细胞克隆选择学说","answer":"这一理论认为动物体内存在许多免疫活性细胞，不同克隆的细胞具有\n\n不同的表面受体。一旦某种抗原进入体内与相应克隆的受体发生结合\n\n后，便选择性的激活了这一克隆，使它扩增并产生大量抗体，抗体分\n\n子的特异性与被选择的细胞的表面受体相同。","chapterNo":30,"chapterTitle":"免疫系统与免疫功能","source":"term_doc","answerStatus":"reference","qid":"TERM-0608"},{"term":"主动免疫","answer":"主动免疫也称自动免疫，由机体自身产生抗体，使机体不再担心被病\n\n毒感染的免疫。即利用抗原刺激，使机体产生抗体的方法，而非直接\n\n自体外引入抗体。(特点是效应慢，但能长久甚至终生保持，且通过\n\n注射所需抗原很容易再活化。)","chapterNo":30,"chapterTitle":"免疫系统与免疫功能","source":"term_doc","answerStatus":"reference","qid":"TERM-0609"},{"term":"被动免疫","answer":"被动免疫是机体被动接受抗体、致敏淋巴细胞或其产物所获得的特异\n\n性免疫能力。即把已经获得免疫性的动物的血清注射到未经免疫的机\n\n体所产生的短时期的免疫，机体中的抗体不是自己产生而是从外界获\n\n得的。(特点是效应快，不需经过潜伏期，一经输入，立即可获得免\n\n疫力。但维持时间短。)","chapterNo":30,"chapterTitle":"免疫系统与免疫功能","source":"term_doc","answerStatus":"reference","qid":"TERM-0610"},{"term":"淋巴系统","answer":"淋巴系统是一种分布机体全身的单向运输系统，由淋巴器官与淋巴管\n\n道组成。淋巴器官包括骨髓、淋巴结、脾、胸腺。淋巴管道包括淋巴\n\n管、淋巴导管。","chapterNo":30,"chapterTitle":"免疫系统与免疫功能","source":"term_doc","answerStatus":"reference","qid":"TERM-0611"},{"term":"免疫系统（2017 年名词解释）","answer":"免疫系统是机体执行免疫应答和免疫功能的重要系统，包括免疫器官、\n\n免疫细胞和免疫分子。","chapterNo":30,"chapterTitle":"免疫系统与免疫功能","source":"term_doc","answerStatus":"reference","qid":"TERM-0612"},{"term":"免疫细胞","answer":"免疫细胞是发挥免疫作用的细胞，包括吞噬细胞、树突状细胞、淋巴\n\n细胞等。","chapterNo":30,"chapterTitle":"免疫系统与免疫功能","source":"term_doc","answerStatus":"reference","qid":"TERM-0613"},{"term":"免疫分子","answer":"免疫分子又称免疫活性物质，是由免疫细胞或其他细胞产生的发挥免\n\n疫作用的物质，包括抗体、淋巴因子、溶菌酶等。","chapterNo":30,"chapterTitle":"免疫系统与免疫功能","source":"term_doc","answerStatus":"reference","qid":"TERM-0614"},{"term":"免疫接种","answer":"免疫接种又称接种疫苗，是以诱发机体产生特异性免疫应答为目的接\n\n种疫苗以预助某种传染性疾病。疫苗种类分为灭活微生物所做疫苗、\n\n分离微生物成分或其产物所做疫苗、减毒的微生物所做疫苗。","chapterNo":30,"chapterTitle":"免疫系统与免疫功能","source":"term_doc","answerStatus":"reference","qid":"TERM-0615"},{"term":"杂交瘤技术","answer":"杂交瘤技术是制备单克隆抗体的技术，该技术在细胞融合技术的基础\n\n上，将具有分泌特异性抗体能力的致敏 B 细胞和具有无限繁殖能力的\n\n骨髓瘤细胞融合为一种杂交瘤细胞。这种杂交瘤细胞不仅能无限制地\n\n分裂和生长，经过筛选，还能产生出人们所需要的特定的抗体。","chapterNo":30,"chapterTitle":"免疫系统与免疫功能","source":"term_doc","answerStatus":"reference","qid":"TERM-0616"},{"term":"过敏反应","answer":"过敏反应是指一些人对某种无害的物质，如花粉、某些食物、某些药\n\n物、螨虫、灰尘及化妆品等产生强烈的免疫应答，称为过敏反应，又\n\n称变态反应。分为速发型过敏反应和迟发型过敏反应。能引发过敏反\n\n应的物质称为致敏原。","chapterNo":30,"chapterTitle":"免疫系统与免疫功能","source":"term_doc","answerStatus":"reference","qid":"TERM-0617"},{"term":"自身免疫病","answer":"自身免疫病是指机体对自身抗原发生免疫反应而导致自身组织损害\n\n所引起的疾病。分为器官特异性自身免疫病和系统性自身免疫病。器\n\n官特异性自身免疫病，自身抗体只攻击某一器官，如突眼性甲状腺肿\n\n中的甲状腺 TSH 受体。系统性自身免疫病，会波及全身，如系统性红\n\n斑狼疮、类风湿性关节炎。","chapterNo":30,"chapterTitle":"免疫系统与免疫功能","source":"term_doc","answerStatus":"reference","qid":"TERM-0618"},{"term":"内分泌","answer":"机体组织所产生的物质不经导管而直接分泌于血液（体液）中的现象。\n\n内分泌系统包括分散在体内的一些无管腺和细胞。","chapterNo":31,"chapterTitle":"激素与内分泌系统","source":"term_doc","answerStatus":"reference","qid":"TERM-0619"},{"term":"体液调节","answer":"指细胞产生的某些化学物质（如激素等），通过体液运送的方式对人\n\n和动物的生理活动所进行的调节。与神经调节相比，体液调节反应比\n\n较缓慢，作用的持续时间比较长，作用的范围比较广泛。","chapterNo":31,"chapterTitle":"激素与内分泌系统","source":"term_doc","answerStatus":"reference","qid":"TERM-0620"},{"term":"激素","answer":"特定的器官或细胞在特定的刺激（神经的或体液的）作用下分泌到体\n\n液中的某种特异性物质。激素作用于特定的靶器官，只调节特定过程\n\n的速率，并不向组织提供能量或物质。\n\n各种激素，根据它们的化学结构可以分为几种类型：\n\n蛋白质类：包括胰岛素、促肾上腺皮质激素、促甲状腺激素、生长激\n\n素、胸腺素、绒毛膜促性腺激素等；\n\n多肽类：包括胰高血糖素、催产素、抗利尿激素（又称血管升压素）；\n\n氨基酸衍生物：如甲状腺素、肾上腺素、去甲肾上腺素等；\n\n类固醇：如肾上腺皮质类固醇、雄激素、雌激素等。\n\n以上 4 类又可归并为两大类，一是含氮激素，包括蛋白质、多肽、氨\n\n基酸衍生物；另一类是类固醇激素。","chapterNo":31,"chapterTitle":"激素与内分泌系统","source":"term_doc","answerStatus":"reference","qid":"TERM-0621"},{"term":"降钙素","answer":"降钙素是由甲状腺滤泡旁细胞分泌的一种降低血钙和血磷的激素。高\n\n浓度的血钙引起滤泡旁细胞释放降钙素，其通过抑制骨质溶解及肾小\n\n管对钙、磷、钠、氯的重吸收来降低血钙浓度。","chapterNo":31,"chapterTitle":"激素与内分泌系统","source":"term_doc","answerStatus":"reference","qid":"TERM-0622"},{"term":"甲状旁腺","answer":"人体最小的腺体之一，共有两对。假装螃蟹分泌甲状旁腺素，它通过\n\n促进骨钙溶解、促进小肠从食物中吸收钙以及肾小管对钙离子的重吸\n\n收，使血钙浓度上升。","chapterNo":31,"chapterTitle":"激素与内分泌系统","source":"term_doc","answerStatus":"reference","qid":"TERM-0623"},{"term":"第二信使","answer":"第二信使指在胞内产生的非蛋白质类小分子，通过其浓度变化应答胞\n\n外信号与细胞表面受体的结合，调节胞内特有的酶或反应过程，引起\n\n细胞的各种生物学效应。第二信使包括：cAMP、cGMP、DAG 等。","chapterNo":31,"chapterTitle":"激素与内分泌系统","source":"term_doc","answerStatus":"reference","qid":"TERM-0624"},{"term":"无性生殖","answer":"不经过生殖细胞的结合，由母体直接产生出新个体的生殖方式。(主\n\n要类型有：①分裂生殖：细菌；②出芽生殖：酵母、水螅；③孢子生\n\n殖：真菌；④营养生殖：植物插枝。）\n\n无性生殖繁殖方式简单、快速，没有遗传物质的浪费，有利于保存亲\n\n代的优良特性，但是由于后代与亲代完全相同，没有什么变异，难以\n\n适应环境的改变。","chapterNo":32,"chapterTitle":"生殖与胚胎发育","source":"term_doc","answerStatus":"reference","qid":"TERM-0625"},{"term":"接合生殖","answer":"两个亲体细胞间形成接合部位，交换部分核物质后再产生新个体的繁\n\n殖方式。(如单细胞的草履虫同时具有无性生殖方式和有性生殖方式，\n\n在有性生殖中它进行的是接合生殖，在此过程中有遗传物质的交换，\n\n但不分雌雄。)","chapterNo":32,"chapterTitle":"生殖与胚胎发育","source":"term_doc","answerStatus":"reference","qid":"TERM-0626"},{"term":"有性生殖","answer":"由亲本产生两性生殖细胞，经过两性生殖细胞的结合，成为合子，再\n\n由合子发育成为新个体的生殖方式。\n\n(主要类型有：同配生殖、异配生殖、卵式生殖，接合生殖是有性生\n\n殖的初级阶段。绝大多数高等生物都是通过有性生殖繁衍后代的，有\n\n性生殖将雄性与雌性的遗传物质结合起来，产生的后代具有更多的变\n\n异，这种后代将比无性生殖产生的与亲代完全一致的后代更能适应多\n\n变的环境。)","chapterNo":32,"chapterTitle":"生殖与胚胎发育","source":"term_doc","answerStatus":"reference","qid":"TERM-0627"},{"term":"受精","answer":"精子穿入卵子形成受精卵的过程，它始于精子细胞膜与卵子细胞膜的\n\n接触，终于两者细胞核的融合。","chapterNo":32,"chapterTitle":"生殖与胚胎发育","source":"term_doc","answerStatus":"reference","qid":"TERM-0628"},{"term":"分娩","answer":"成熟的胎儿从子宫脱离母体成为独立个体的过程。\n\n(可以分为三个时期：扩张期、娩出期、胎盘期。)","chapterNo":32,"chapterTitle":"生殖与胚胎发育","source":"term_doc","answerStatus":"reference","qid":"TERM-0629"},{"term":"绝育","answer":"用外科手术结扎输精管(男性)或输卵管(女性),阻止精子和卵子的输\n\n出以达到避孕目的的措施。","chapterNo":32,"chapterTitle":"生殖与胚胎发育","source":"term_doc","answerStatus":"reference","qid":"TERM-0630"},{"term":"人工流产","answer":"在避孕失败后不得已而采取的人工终止妊娠的措施。","chapterNo":32,"chapterTitle":"生殖与胚胎发育","source":"term_doc","answerStatus":"reference","qid":"TERM-0631"},{"term":"桑甚胚","answer":"受精卵的分裂称为卵裂，卵裂产生的细胞称为分裂球，卵裂在开始时\n\n是同步的，分裂的结果形成一个多细胞的实心球状体，形如桑葚，称\n\n为桑葚胚。","chapterNo":32,"chapterTitle":"生殖与胚胎发育","source":"term_doc","answerStatus":"reference","qid":"TERM-0632"},{"term":"囊胚","answer":"桑葚胚形成后，细胞继续分裂，细胞数目增多，细胞排列到表面呈一\n\n单层，中央成为一充满液体的腔，这个球形幼体称为囊胚。","chapterNo":32,"chapterTitle":"生殖与胚胎发育","source":"term_doc","answerStatus":"reference","qid":"TERM-0633"},{"term":"原肠胚","answer":"囊胚形成后，细胞继续分裂，囊胚的一端内陷，细胞层逐渐褶入囊胚\n\n腔，形成了一个新腔，这个新腔称原肠腔，这个幼体就称为原肠胚。\n\n未来将发育成为消化管的原肠。","chapterNo":32,"chapterTitle":"生殖与胚胎发育","source":"term_doc","answerStatus":"reference","qid":"TERM-0634"},{"term":"顶体反应","answer":"是受精过程的反应之一。指精卵相遇后，精子的顶体外模与卵子头部\n\n的细胞膜融合、破裂，释放出顶体酶，以溶解卵子外围放射冠及透明\n\n带的过程。\n\n(顶体反应受钙离子的调节。反应过程较长，包括顶体受体的激活、\n\n顶体膜与精细胞质膜融合、顶体中水解酶的释放、透明带的水解等)","chapterNo":32,"chapterTitle":"生殖与胚胎发育","source":"term_doc","answerStatus":"reference","qid":"TERM-0635"},{"term":"卵泡期","answer":"指由上一次月经停止开始至卵巢排卵为止的时期。在该时期，下丘脑\n\n释放促性腺激素释放激素的水平升高，刺激腺垂体产生和释放促卵泡\n\n激素(FSH)和黄体生成素(LH)，促进卵泡的生长和成熟。","chapterNo":32,"chapterTitle":"生殖与胚胎发育","source":"term_doc","answerStatus":"reference","qid":"TERM-0636"},{"term":"排卵期","answer":"指卵细胞离开卵巢的时期。雌激素的浓度达到一个临界值就会刺激腺\n\n垂体爆发式地释放积累的 LH，同时也释放 FSH；LH 的突然大量出现\n\n刺激成熟卵泡中的初级卵母细胞完成减数分裂 I，分出第一极体，成\n\n为次级卵母细胞；LH 引发突出的卵泡壁破裂，排出次级卵母细胞；\n\n排卵后不久雌激素浓度开始下降，卵泡变成血体。","chapterNo":32,"chapterTitle":"生殖与胚胎发育","source":"term_doc","answerStatus":"reference","qid":"TERM-0637"},{"term":"黄体期","answer":"指排卵后，卵泡内的细胞增殖并发育为黄体的时期。在大量 LH 的作\n\n用下，卵泡与内膜细胞一起变成了黄体，黄体分泌少量孕激素和雌激\n\n素，抑制腺垂体释放 LH 和 FSH，使黄体期不再出现新的卵泡发育；\n\n如果排出的卵母细胞没有受精，随着 LH 浓度降低，对黄体的刺激终\n\n止，一个新的卵巢周期又重新开始；如果排出的卵母细胞受精，受精\n\n卵在子宫内膜上逐步发育出胎盘，胎盘产生 LH 样激素——人绒毛膜\n\n促性腺激素(hCG)，促使黄体继续长大，直到胎盘充分发育起来，接\n\n替黄体生产激素的作用，黄体才开始退化。","chapterNo":32,"chapterTitle":"生殖与胚胎发育","source":"term_doc","answerStatus":"reference","qid":"TERM-0638"},{"term":"月经期","answer":"是在分泌期之后。当血液中雌激素、孕激素浓度降低时，子官内膜脱\n\n落，与血液混在一起从阴道流出。","chapterNo":32,"chapterTitle":"生殖与胚胎发育","source":"term_doc","answerStatus":"reference","qid":"TERM-0639"},{"term":"增生期","answer":"在血液中雌激素的作用下，基底层增生，子宫内膜重建，刺激排卵。","chapterNo":32,"chapterTitle":"生殖与胚胎发育","source":"term_doc","answerStatus":"reference","qid":"TERM-0640"},{"term":"分泌期","answer":"黄体生成并产生孕激素，血液中孕激素浓度升高，在雌激素作用的基\n\n础上促使子宫内膜进一步增生。","chapterNo":32,"chapterTitle":"生殖与胚胎发育","source":"term_doc","answerStatus":"reference","qid":"TERM-0641"},{"term":"性传播疾病","answer":"主要通过性接触而传染的疾病。这些疾病可由病毒、细菌或寄生虫引\n\n起。常见的有淋病、梅毒、艾滋病等。","chapterNo":32,"chapterTitle":"生殖与胚胎发育","source":"term_doc","answerStatus":"reference","qid":"TERM-0642"},{"term":"艾滋病","answer":"又称获得性免疫缺陷综合征，由人类免疫缺陷病毒(HIV)引起的。","chapterNo":32,"chapterTitle":"生殖与胚胎发育","source":"term_doc","answerStatus":"reference","qid":"TERM-0643"},{"term":"透明带反应","answer":"在精子触及卵细胞膜的瞬间，会产阻止后来的精子进入透明带的生理\n\n反应。防止多精入卵的第一道屏障。","chapterNo":32,"chapterTitle":"生殖与胚胎发育","source":"term_doc","answerStatus":"reference","qid":"TERM-0644"},{"term":"卵细胞膜反应","answer":"精子入卵后，卵细胞膜立即发生一种生理反应，拒绝其他精子再进人\n\n卵内。防止多精入卵的第二道屏障。","chapterNo":32,"chapterTitle":"生殖与胚胎发育","source":"term_doc","answerStatus":"reference","qid":"TERM-0645"},{"term":"孤雌生殖/单性生殖","answer":"孤雌生殖又称单性生殖，即卵不需受精直接发育成个体。如蜜蜂的雄\n\n蜂即是由未受精卵发育而成的可育单倍体，而蜂后和工蜂均为受精卵\n\n发育而成的二倍体。一些膜翅目昆虫、鲨和蜥蜴可以进行孤雌生殖。","chapterNo":32,"chapterTitle":"生殖与胚胎发育","source":"term_doc","answerStatus":"reference","qid":"TERM-0646"},{"term":"神经元","answer":"又称神经细胞，是神经系统的基本结构和功能单位。一般包含 包括\n\n胞体和突起两部分，突起又分为树突与轴突，作用是接受并传导神经\n\n冲动。","chapterNo":33,"chapterTitle":"神经系统与神经调节","source":"term_doc","answerStatus":"reference","qid":"TERM-0647"},{"term":"突触","answer":"一个神经元的冲动传到另一个神经元或另一细胞的相互接触的结构。\n\n包括突触前膜，突触后膜与突触间隙。突触可分为化学突触和电突触。","chapterNo":33,"chapterTitle":"神经系统与神经调节","source":"term_doc","answerStatus":"reference","qid":"TERM-0648"},{"term":"反射","answer":"在中枢神经系统参与下，机体对刺激感受器所发生的规律性反应，是\n\n神经系统最基本的活动方式，通过反射弧进行。包括先天性反射和后\n\n天性反射。","chapterNo":33,"chapterTitle":"神经系统与神经调节","source":"term_doc","answerStatus":"reference","qid":"TERM-0649"},{"term":"反射弧（2015/2017/2018 名词解释）","answer":"是进行反射活动的神经结构，包括：感受器、传入神经、反射中枢、\n\n传出神经、效应器。反射弧中任何一个环节受损伤，反射活动都不能\n\n实现。","chapterNo":33,"chapterTitle":"神经系统与神经调节","source":"term_doc","answerStatus":"reference","qid":"TERM-0650"},{"term":"自发脑电活动","answer":"大脑皮层连续的节律性电位变化称为自发脑电活动，它的记录称为脑\n\n电图。\n\n(一般可把脑电节律区分为四种波，即 a 波、β波、θ波、 ∑ 波。)","chapterNo":33,"chapterTitle":"神经系统与神经调节","source":"term_doc","answerStatus":"reference","qid":"TERM-0651"},{"term":"适宜刺激","answer":"是指能在传入神经上引起冲动发放的敏感性最高的能量形式的刺激。\n\n(如嗅觉的适宜刺激是能挥发、有气味的物质；味觉的适宜刺激是能\n\n溶 解的、有味道的物质。)","chapterNo":33,"chapterTitle":"神经系统与神经调节","source":"term_doc","answerStatus":"reference","qid":"TERM-0652"},{"term":"不适宜刺激","answer":"是指不发生反应或敏感性很低的能量形式的刺激。","chapterNo":33,"chapterTitle":"神经系统与神经调节","source":"term_doc","answerStatus":"reference","qid":"TERM-0653"},{"term":"神经递质","answer":"指在突触传递中担当“信使”的特定化学物质，简称递质，如乙酰胆\n\n碱、去肾上腺素、谷氨酸、多巴胺等。它由突触前膜释放，经突触间\n\n隙 扩散到突触后膜，并与相应受体结合而产生作用。","chapterNo":33,"chapterTitle":"神经系统与神经调节","source":"term_doc","answerStatus":"reference","qid":"TERM-0654"},{"term":"周围神经系统","answer":"人的神经系统分为中枢神经系统和周围神经系统。周围神经系统包括\n\n脑神经(12 对)和脊神经(31 对)。从功能上划分，周围神经系统分为\n\n传入神经和传出神经，周围神经系统的功能是将外周感受器和中枢神\n\n经系统连起来。","chapterNo":33,"chapterTitle":"神经系统与神经调节","source":"term_doc","answerStatus":"reference","qid":"TERM-0655"},{"term":"中枢神经系统","answer":"人的神经系统分为中枢神经系统和周围神经系统。中枢 神经系统包\n\n括脑和脊髓，是人体神经系统的最主体部分。(主要功能是传递、储\n\n存和加工信息，产生各种心理活动，支配人的行为。)","chapterNo":33,"chapterTitle":"神经系统与神经调节","source":"term_doc","answerStatus":"reference","qid":"TERM-0656"},{"term":"静息电位","answer":"是指细胞未受刺激时，存在于细胞膜内外两侧的外正内负的电位差。","chapterNo":33,"chapterTitle":"神经系统与神经调节","source":"term_doc","answerStatus":"reference","qid":"TERM-0657"},{"term":"动作电位（2017 名词解释）","answer":"是指膜电位由外正内负到外负内正，再到外正内负的过程，也称为神\n\n经冲动。神经冲动的传导就是动作电位的传播。","chapterNo":33,"chapterTitle":"神经系统与神经调节","source":"term_doc","answerStatus":"reference","qid":"TERM-0658"},{"term":"极化","answer":"安静时，细胞膜 K＋通道开放，Na＋通道几乎关闭，因此细胞膜对 K\n\n＋的通透性大，对 Na＋的通透性小，膜内的 K＋扩散到膜外，膜外\n\n的 Na＋不能扩散进来，从而形成外正内负的电位差，即静息电位，\n\n这一状态称为极化状态。","chapterNo":33,"chapterTitle":"神经系统与神经调节","source":"term_doc","answerStatus":"reference","qid":"TERM-0659"},{"term":"反极化","answer":"当神经某处受到刺激时，Na＋通道迅速开放，于是膜外的 Na＋在短\n\n期内大量涌入膜内，造成了内正外负的反极化状态。","chapterNo":33,"chapterTitle":"神经系统与神经调节","source":"term_doc","answerStatus":"reference","qid":"TERM-0660"},{"term":"复极化","answer":"几乎在 Na＋通道开放的同时，K＋通道也被激活开放，但它比 Na＋\n\n通道开放的速率慢。K 的外流对抗了 Na＋的内流，随着 Na 通道的\n\n逐渐失活，K＋外流超过了 Na＋内流，膜电位又开始逐渐恢复到外正\n\n内负的状态，称为复极化.","chapterNo":33,"chapterTitle":"神经系统与神经调节","source":"term_doc","answerStatus":"reference","qid":"TERM-0661"},{"term":"超极化","answer":"是指跨膜电位处于较原来的参照状态下的跨膜电位更负的状态。","chapterNo":33,"chapterTitle":"神经系统与神经调节","source":"term_doc","answerStatus":"reference","qid":"TERM-0662"},{"term":"化学突触（真题）","answer":"神经细胞与效应细胞之间通过神经末梢释放的神经递质来进行信号\n\n传递，这种传递称为化学传递，这种突触称为化学突触。","chapterNo":33,"chapterTitle":"神经系统与神经调节","source":"term_doc","answerStatus":"reference","qid":"TERM-0663"},{"term":"电突触（真题）","answer":"在突触前膜与突触后膜上有缝隙连接，前一个神经元的神经冲动产生\n\n的电流可以通过这种缝隙连接流到后一个神经元，使神经冲动传递下\n\n去。这种突触称为电突触。","chapterNo":33,"chapterTitle":"神经系统与神经调节","source":"term_doc","answerStatus":"reference","qid":"TERM-0664"},{"term":"条件反射","answer":"指在一定条件下，外界刺激与有机体反应之间建立起来的暂时神经联\n\n系。","chapterNo":33,"chapterTitle":"神经系统与神经调节","source":"term_doc","answerStatus":"reference","qid":"TERM-0665"},{"term":"交感神经","answer":"根据节前神经元细胞体的位置，内脏神经系统可分为交感神经与副交\n\n感神经。交感神经纤维起源于胸腰部脊髓，大部分交感神经节位于脊\n\n椎旁，组成交感神经干(链)。它在紧张状态下占优势。","chapterNo":33,"chapterTitle":"神经系统与神经调节","source":"term_doc","answerStatus":"reference","qid":"TERM-0666"},{"term":"副交感神经","answer":"根据节前神经元细胞体的位置，内脏神经系统可分为交感神经与副交\n\n感神经。副交感神经纤维起源于脑部神经核与骶部脊髓，大部分副交\n\n感神经节位于效应器官附近或其壁内。它在安静状态下占优势。","chapterNo":33,"chapterTitle":"神经系统与神经调节","source":"term_doc","answerStatus":"reference","qid":"TERM-0667"},{"term":"主要运动区","answer":"主要运动区是位于大脑皮层的中央前回的一个功能区。大脑皮质运动\n\n区的损伤，会引起对应躯体部位的运动障碍。中央前回皮质与躯体呈\n\n现对侧的、颠倒的关系，与头面部是双侧的、正立的关系。皮质运动\n\n区代表区范围的大小与躯体各部分大小无关，而与各部分运动功能的\n\n灵活性和细致程度有关。","chapterNo":33,"chapterTitle":"神经系统与神经调节","source":"term_doc","answerStatus":"reference","qid":"TERM-0668"},{"term":"躯体感觉区","answer":"躯体感觉区是位于大脑皮层的中央后回的一个功能区，又称第一体觉\n\n区。中央后回皮质与躯体呈现对侧的、颠倒的关系，与头面部是双侧\n\n的、正立的关系。皮质感觉区代表区的面积与感觉功能的敏感性有关，\n\n而与体表面积无关，即感觉灵敏的部位在皮质的代表区大。","chapterNo":33,"chapterTitle":"神经系统与神经调节","source":"term_doc","answerStatus":"reference","qid":"TERM-0669"},{"term":"慢波睡眠","answer":"通常的睡眠，脑电波呈现缓慢的 δ 波，叫做慢波睡眠，此时，内脏\n\n活动水平低，骨骼肌松弛。","chapterNo":33,"chapterTitle":"神经系统与神经调节","source":"term_doc","answerStatus":"reference","qid":"TERM-0670"},{"term":"快波睡眠/快速眼动睡眠/异相睡眠","answer":"在成人睡眠时，会有规律地呈现快速的 β 波，眼球快速运动，因此\n\n又叫做快速眼动睡眠，一般与做梦有关，快波睡眠时，虽然脑的活动\n\n水平高，但比慢波睡眠时睡得更深，更难唤醒，在该阶段脑血流、耗\n\n氧量、血压、呼吸活动、心搏率都有所增加，因此也称异相睡眠。","chapterNo":33,"chapterTitle":"神经系统与神经调节","source":"term_doc","answerStatus":"reference","qid":"TERM-0671"},{"term":"感觉器官","answer":"是实现感觉过程的生理装置。包括感受器、神经通道和大脑皮层感觉\n\n中枢三部分。如视觉器官眼。","chapterNo":34,"chapterTitle":"感觉器官与感觉","source":"term_doc","answerStatus":"reference","qid":"TERM-0672"},{"term":"感受器","answer":"动物接受外界和体内刺激的细胞和器官。如耳蜗中的毛细胞，视网膜\n\n上的视锥细胞和视杆细胞。(感受器可分为物理感受器和化学感受器\n\n两大类。感受器有换能作用和放大作用，换能作用即感受器可以将环\n\n境中的能量刺激转换为生物能——感受器上膜电位的变化，放大作用\n\n即感受器对于适宜刺激非常敏感，可以感受到极微弱的能量，经过换\n\n能后的神经冲动的功率放大了很多倍。)","chapterNo":34,"chapterTitle":"感觉器官与感觉","source":"term_doc","answerStatus":"reference","qid":"TERM-0673"},{"term":"本体感受器","answer":"感受自身肌肉、腱、关节的张力和运动的器官。本体感受器能够感受\n\n肌肉张力和压力的变化，并将这些感受变化的刺激信号转化为神经冲\n\n动传入大脑皮质躯体运动中枢，以调节骨骼肌的运动。","chapterNo":34,"chapterTitle":"感觉器官与感觉","source":"term_doc","answerStatus":"reference","qid":"TERM-0674"},{"term":"效应器","answer":"是生物在信号刺激下对外界刺激做出反应的部位。(是反射弧的末一\n\n环节，是运动神经元轴突的末梢装置，由中枢传向效应器的神经冲动\n\n在此发生转变，并传至各种器官、肌肉或腺体，从而以一定的活动表\n\n现出来，所以称为效应器。)","chapterNo":34,"chapterTitle":"感觉器官与感觉","source":"term_doc","answerStatus":"reference","qid":"TERM-0675"},{"term":"物理感受器","answer":"感受器可分为物理感受器和化学感受器两大类。凡是感受接触、压力、\n\n地心引力、张力、运动姿势以及光、声、热等的感受器都是物理感受\n\n器。人的视觉感受器、听觉感受器、触觉感受器、温度觉感受器等都\n\n属于物理感受器。","chapterNo":34,"chapterTitle":"感觉器官与感觉","source":"term_doc","answerStatus":"reference","qid":"TERM-0676"},{"term":"化学感受器","answer":"感受器可分为物理感受器和化学感受器两大类。化学感受器是感受机\n\n体内、外环境化学刺激的感受器的总称。人的味觉感受器、嗅觉感受\n\n器都属于化学感受器。","chapterNo":34,"chapterTitle":"感觉器官与感觉","source":"term_doc","answerStatus":"reference","qid":"TERM-0677"},{"term":"异常眼","answer":"异常眼指由于眼的形状或折光系统发生异常，使平行光线无法聚焦于\n\n视网膜上清晰成像的眼。包括近视、远视、散光三种类型。","chapterNo":34,"chapterTitle":"感觉器官与感觉","source":"term_doc","answerStatus":"reference","qid":"TERM-0678"},{"term":"视杆细胞","answer":"是感光细胞的一种，位于视网膜上。视杆细胞的感光色素是视紫红质；\n\n主司视觉是暗视觉；对光的敏感性强；没有色觉；分布在视网膜周边，\n\n中央凹处无；外段形状是杆状；空间分辨能力弱，只能分析轮廓。","chapterNo":34,"chapterTitle":"感觉器官与感觉","source":"term_doc","answerStatus":"reference","qid":"TERM-0679"},{"term":"视锥细胞","answer":"是感光细胞的一种，位于视网膜上。视杆细胞的感光色素是视紫质；\n\n主司视觉是明视觉；对光的敏感性弱；有色觉；分布在视网膜中部多，\n\n边缘少；外段形状是锥状；空间分辨能力强，能分辨物体细微结构。","chapterNo":34,"chapterTitle":"感觉器官与感觉","source":"term_doc","answerStatus":"reference","qid":"TERM-0680"},{"term":"视盘","answer":"神经节细胞发出的轴突先在视网膜内表面聚合成束，然后从眼的后极\n\n穿过视网膜眼球，这个部位称为视盘。","chapterNo":34,"chapterTitle":"感觉器官与感觉","source":"term_doc","answerStatus":"reference","qid":"TERM-0681"},{"term":"盲点","answer":"视盘没有感光细胞，因而不感光，如果外界物体的像正好投射在这一\n\n区域，便会看不到，是生理上的盲点。","chapterNo":34,"chapterTitle":"感觉器官与感觉","source":"term_doc","answerStatus":"reference","qid":"TERM-0682"},{"term":"黄斑","answer":"眼球后极稍偏外侧的视网膜上有直径为 1.5mm 的黄色色素区，称为黄\n\n斑。","chapterNo":34,"chapterTitle":"感觉器官与感觉","source":"term_doc","answerStatus":"reference","qid":"TERM-0683"},{"term":"中央凹","answer":"黄斑中央有一个直径为 0.5mm 的小凹，称为中央凹。这里视网膜极薄，\n\n只有视锥细胞，没有视杆细胞。","chapterNo":34,"chapterTitle":"感觉器官与感觉","source":"term_doc","answerStatus":"reference","qid":"TERM-0684"},{"term":"视紫红质","answer":"是视杆细胞外段中的感光色素，由视蛋白和视黄醛组成，视蛋白镶嵌\n\n在外段的细胞膜上。","chapterNo":34,"chapterTitle":"感觉器官与感觉","source":"term_doc","answerStatus":"reference","qid":"TERM-0685"},{"term":"夜盲症","answer":"由于缺乏维生素 A，视杆细胞不能发生正常的光化学反应，影响视紫\n\n红质的合成，光敏感度下降，在傍晚和夜间看不清物体，这种病称为\n\n夜盲症。","chapterNo":34,"chapterTitle":"感觉器官与感觉","source":"term_doc","answerStatus":"reference","qid":"TERM-0686"},{"term":"听觉的行波学说","answer":"当耳蜗发生振动，会沿着蜗管引起一个行波，行波沿着基底膜由耳蜗\n\n底部向顶部传播，频率不同时，行波所能到达的部位和最大行波振幅\n\n出现的部位有所不同。声波振动频率越低，行波传播越远，因此最大\n\n振幅出现的部位在基底膜顶部(毛细胞处)，振动频率的分析决定于基\n\n底膜上行波振幅所在的部位。","chapterNo":34,"chapterTitle":"感觉器官与感觉","source":"term_doc","answerStatus":"reference","qid":"TERM-0687"},{"term":"化学感受性","answer":"化学感受性是指感受器对溶于水的化学物质的感受功能。味感受器细\n\n胞感受溶解的离子或分子的刺激；嗅感受器细胞的表面有一层黏液，\n\n挥发的气体分子必须先溶于这层黏液后才再刺激感受器细胞。","chapterNo":34,"chapterTitle":"感觉器官与感觉","source":"term_doc","answerStatus":"reference","qid":"TERM-0688"},{"term":"味蕾","answer":"味蕾是人的味觉感受器，大多数集中在舌乳头中，味蕾由感受器细胞\n\n(味觉细胞)和支持细胞组成，感觉神经末梢包围在感受器细胞的周围，\n\n可将味觉冲动传入中枢。味觉可分为酸、甜、苦、咸 4 种基本味觉。\n\n舌尖为甜、咸的敏感部，舌外侧为酸的敏感部，舌根为苦的敏感部。","chapterNo":34,"chapterTitle":"感觉器官与感觉","source":"term_doc","answerStatus":"reference","qid":"TERM-0689"},{"term":"嗅细胞","answer":"嗅细胞是一种存在于鼻腔上鼻道背侧鼻黏膜中的卵圆形双极神经元，\n\n起着感受刺激和传导冲动的双重作用。","chapterNo":34,"chapterTitle":"感觉器官与感觉","source":"term_doc","answerStatus":"reference","qid":"TERM-0690"},{"term":"两点阈","answer":"指皮肤感觉能分辨出两个点的最小距离。","chapterNo":34,"chapterTitle":"感觉器官与感觉","source":"term_doc","answerStatus":"reference","qid":"TERM-0691"},{"term":"肌丝滑行学说","answer":"该学说认为肌纤维的缩短是肌小节中粗肌丝和细肌丝相对运动的结\n\n果。\n\n(当细肌丝滑行伸入粗肌丝时，明带变窄而暗带宽度不变。从粗肌丝\n\n上突起的横桥是引起细肌丝滑动的结构，当横桥与细肌丝的某位点接\n\n触便发生摆动，推动细肌丝滑行，每次横桥摆动引起的细肌丝位移很\n\n小，因此一次肌肉收缩时，横桥要变换与细肌丝的接触位点反复摆动\n\n多次。横桥摆动需要能量，这些能量由细肌丝的 ATP 供给。)","chapterNo":35,"chapterTitle":"动物如何运动","source":"term_doc","answerStatus":"reference","qid":"TERM-0692"},{"term":"等长收缩","answer":"肌肉收缩可以分为等长收缩和等张收缩。等长收缩是指长度保持不变\n\n而张力发生变化的肌肉收缩。例如用力握拳。","chapterNo":35,"chapterTitle":"动物如何运动","source":"term_doc","answerStatus":"reference","qid":"TERM-0693"},{"term":"等张收缩","answer":"肌肉收缩可以分为等长收缩和等张收缩。等张收缩是指张力保持不变\n\n而长度发生变化的肌肉收缩。例如推举杠铃。","chapterNo":35,"chapterTitle":"动物如何运动","source":"term_doc","answerStatus":"reference","qid":"TERM-0694"},{"term":"人骨的直接连接","answer":"颅骨各骨之间多以骨缝连接，不能活动；各椎骨之间以椎间盘相连，\n\n活动范围也较少，这都属于直接连接。","chapterNo":35,"chapterTitle":"动物如何运动","source":"term_doc","answerStatus":"reference","qid":"TERM-0695"},{"term":"人骨的间接连接","answer":"骨与骨之间多数通过关节连接，使骨面之间间隙大，增大运动能力，\n\n称为间接连接。如股骨与胫骨通过膝关节连接。","chapterNo":35,"chapterTitle":"动物如何运动","source":"term_doc","answerStatus":"reference","qid":"TERM-0696"},{"term":"肌纤维","answer":"肌纤维是构成骨骼肌的细胞，呈柱状，分为红肌纤维和白肌纤维。\n\n肌纤维是由若干肌原纤维平行排列构成的，肌原纤维是由粗肌丝和细\n\n肌丝组成的肌小节构成的。\n\n肌丝滑行学说认为肌纤维的缩短是肌小节中粗肌丝和细肌丝相对运\n\n动的结果。","chapterNo":35,"chapterTitle":"动物如何运动","source":"term_doc","answerStatus":"reference","qid":"TERM-0697"},{"term":"行为","answer":"动物在个体层次上对外界环境变化和内在生理变化所作出的整体性\n\n反应，并具有一定的生物学意义。","chapterNo":36,"chapterTitle":"动物的行为","source":"term_doc","answerStatus":"reference","qid":"TERM-0698"},{"term":"本能","answer":"是可遗传的复杂反射，是神经系统对外界制激所作出的先天性反应，\n\n这种反应已构成整个动物遗传结构的一部分，它是通过自然选择进化\n\n而来，是在长期进化过程中形成的，不需要学习。","chapterNo":36,"chapterTitle":"动物的行为","source":"term_doc","answerStatus":"reference","qid":"TERM-0699"},{"term":"动性","answer":"指动物对某种刺激所作出的一种随机的和无定向的运动反应，反应程\n\n度随诱发刺激强度的变化而变化，导致身体长轴没有特定的指向。动\n\n性的最终效果是使动物趋向于有利刺激源，避开不利刺激源。动性在\n\n昆虫和无脊椎动物中最常见。","chapterNo":36,"chapterTitle":"动物的行为","source":"term_doc","answerStatus":"reference","qid":"TERM-0700"},{"term":"趋性","answer":"指动物对某种刺激所作出的一种定向的运动反应，定向是沿着动物身\n\n体的长轴直接指向刺激源的方向。趋性是靠身体两侧的感觉器官，把\n\n同等量的刺激强度传到中枢神经，然后做出反应。类型有：趋光性、\n\n趋地性、趋湿性。趋触性、趋流性。","chapterNo":36,"chapterTitle":"动物的行为","source":"term_doc","answerStatus":"reference","qid":"TERM-0701"},{"term":"固定行为型","answer":"是指按一定时间、空间顺序进行的肌肉收缩活动，表现为一定的动作\n\n并能达到某种生物学目的。每一个物种都有属子自己的固定行为型，\n\n它是一种先天的本能行为，这种方式在诸如求偶、筑巢、取食和清洁\n\n身体等行为中最为常见。","chapterNo":36,"chapterTitle":"动物的行为","source":"term_doc","answerStatus":"reference","qid":"TERM-0702"},{"term":"学习","answer":"动物借助于个体生活经历和经验使自身的行为发生适应性变化的过\n\n程。动物的行为在特定的刺激场合下发生了变化即是一种学习，学习\n\n行为是在个体发育过程中获得的","chapterNo":36,"chapterTitle":"动物的行为","source":"term_doc","answerStatus":"reference","qid":"TERM-0703"},{"term":"习惯化","answer":"习惯化是指由于刺激重复发生而无任何有意思的结果致使个体对这\n\n种刺激(例如警报、防御、攻击)的自发反应减弱或消失的现象。改变\n\n刺激的形式或结果，可能使习惯化了的反应重新发生。这是动物界最\n\n常见最简单的一种学习类型，广义上习惯化是指动物学会对特定的刺\n\n激不发生反应。","chapterNo":36,"chapterTitle":"动物的行为","source":"term_doc","answerStatus":"reference","qid":"TERM-0704"},{"term":"印记","answer":"个体发育早期的一个特定阶段，动物对于第一次接触的能活动的较大\n\n物体紧紧追随的现象。印记使得动物能够准确可靠地辨别自己的双亲\n\n和本种其他成员。","chapterNo":36,"chapterTitle":"动物的行为","source":"term_doc","answerStatus":"reference","qid":"TERM-0705"},{"term":"联系学习","answer":"把 2 个或 2 个以上的刺激联系起来而诱发同样的行为就是联系学习。\n\n条件反射就是一种联系学习。","chapterNo":36,"chapterTitle":"动物的行为","source":"term_doc","answerStatus":"reference","qid":"TERM-0706"},{"term":"顿悟学习","answer":"动物利用已有经验来解决当前新问题的能力，包括了解问题、思考问\n\n题和解决问题。整个过程需要判断与推理。最有名的是黑猩猩拿木箱\n\n取食的行为。","chapterNo":36,"chapterTitle":"动物的行为","source":"term_doc","answerStatus":"reference","qid":"TERM-0707"},{"term":"利他行为","answer":"不利于自己存活和生殖而有利于种群中其他个体存活和生殖的行为。\n\n(这种行为在自然界是普遍存在的，如双亲互幼就是明显的一例。(可\n\n用亲缘选择和广义适合度解释。)","chapterNo":36,"chapterTitle":"动物的行为","source":"term_doc","answerStatus":"reference","qid":"TERM-0708"},{"term":"广义适合度","answer":"是指一个个体在后代中传布自身基因的能力有多大，能够最大限度地\n\n把自身基因传递给后代的个体，具有最大的广义适合度不一定是通过\n\n自身繁殖的形式)。","chapterNo":36,"chapterTitle":"动物的行为","source":"term_doc","answerStatus":"reference","qid":"TERM-0709"},{"term":"亲缘选择","answer":"是指彼此有亲缘关系的一个家族或家族中的成员中选择广义适合度\n\n最大的个体，而不管这个个体的行为是否对自身的存活和繁殖有利的\n\n自然选择作用。","chapterNo":36,"chapterTitle":"动物的行为","source":"term_doc","answerStatus":"reference","qid":"TERM-0710"},{"term":"生物节律","answer":"植物和动物在自然界中的活动都是有节律的，以日为周期的昼夜节律，\n\n以月为周期的月周期节律，或年为周期的年节律。生物节律是在生物\n\n长期进化过程中适应地球的自然条件，如昼夜、冬夏、潮汐等而发生\n\n的。","chapterNo":36,"chapterTitle":"动物的行为","source":"term_doc","answerStatus":"reference","qid":"TERM-0711"},{"term":"经典条件反射","answer":"是指一个条件刺激和另一个带有奖赏或惩罚的无条件刺激多次结合，\n\n可使个体学会在单独呈现该一刺激时，也能引发类似无条件反应的条\n\n件反应。特点是在条件反射建立的过程中，无条件刺激是必不可少的，\n\n如果没有无条件刺激不断给予强化，已建立的条件反射就会逐渐消失。","chapterNo":36,"chapterTitle":"动物的行为","source":"term_doc","answerStatus":"reference","qid":"TERM-0712"},{"term":"操作式条件反射","answer":"是指在条件反射的建立过程中，总是先有刺激，后做出反应，最后才\n\n得到报偿，操作式条件反射建立的基本过程是让动物依据某一信号必\n\n须做一件事才能得到报偿。其应用是行为学家常常利用操作式条件反\n\n射训练动物学会各种技能，基本原理是让动物按特定指令(外界刺激)\n\n完成一定的动作，然后给予报偿。","chapterNo":36,"chapterTitle":"动物的行为","source":"term_doc","answerStatus":"reference","qid":"TERM-0713"},{"term":"拟态","answer":"指一动物由于在形态和体色上模拟另一有毒且不可食的动物而得到\n\n好处。分为贝茨拟态和米勒拟态。贝茨拟态是指一种无毒可食的动物\n\n模拟一种有毒不可食的动物，如副王蛱蝶模拟普雷克西普斑蝶。米勒\n\n拟态是指两个有毒不可食的物种彼此相互模拟，双方都能得到好处，\n\n如毒蛾科的各个蛾种之间相互模拟。","chapterNo":36,"chapterTitle":"动物的行为","source":"term_doc","answerStatus":"reference","qid":"TERM-0714"},{"term":"贝茨拟态","answer":"是防御对策中的一种，是指一种无毒可食的动物模拟一种有毒不可食\n\n的动物，如副王蛱蝶模拟普雷克西普斑蝶。","chapterNo":36,"chapterTitle":"动物的行为","source":"term_doc","answerStatus":"reference","qid":"TERM-0715"},{"term":"米勒拟态","answer":"是防御对策中的一种，是指两个有毒不可食的物种彼此相互模拟，双\n\n方都能得到好处，如毒蛾科的各个蛾种之间相互模拟。","chapterNo":36,"chapterTitle":"动物的行为","source":"term_doc","answerStatus":"reference","qid":"TERM-0716"},{"term":"领域行为","answer":"是一种资源独占行为。领域是指被动物占有和保卫的区域，这个区域\n\n不允许同种其他个体侵入，并含有占有者及其家庭所需要的各种资源。\n\n占有领域的可以是一个个体、一对配偶、一个家庭或一个群体，动物\n\n有时会永远占有一个领域，如生活在森林中的灰林鹗；有时只在生殖\n\n期间才占有领域，如大多数雀形目鸟类。","chapterNo":36,"chapterTitle":"动物的行为","source":"term_doc","answerStatus":"reference","qid":"TERM-0717"},{"term":"通讯行为","answer":"是指社群动物通过醒目的形态特征、行为动作和分泌的化学物质以及\n\n发出声音等信号，引起接受个体产生行为反应的过程。发送信号只需\n\n消耗较少的能量，但靠利用其他动物的肌力却能得到较大的利益。类\n\n型包括视觉通讯、听觉通讯、化学和接触通讯。","chapterNo":36,"chapterTitle":"动物的行为","source":"term_doc","answerStatus":"reference","qid":"TERM-0718"},{"term":"行为节律","answer":"是指生物随着地球、太阳、月亮的周期性变化，逐渐形成的周期性、\n\n有节律的行为，如昼夜节律、月运节律、四季交替等，动物都有自己\n\n固有的行为节律。意义是可以使动物的生活与环境周期变化保持同步，\n\n有利于动物获取食物、避开不良生活条件、获得适宜的生活环境，它\n\n是以生化过程为基础的生理机制。","chapterNo":36,"chapterTitle":"动物的行为","source":"term_doc","answerStatus":"reference","qid":"TERM-0719"},{"term":"昼夜节律","answer":"是指除细菌以外的所有生物 24h 的活动和不活动相交替的固有节律，\n\n这种活动节律与地球自转一周的时间极为接近。特点是行为的昼夜节\n\n律具有很强的遗传性，它不是通过学习获得的，也几乎不受温度变化\n\n的影响。\n\n意义是\n\na.影响动物活动的时间安排；\n\nb.影响动物的生理过程和代谢率，它提供了一种生物钟机制使动物与\n\n其环境保持同步。","chapterNo":36,"chapterTitle":"动物的行为","source":"term_doc","answerStatus":"reference","qid":"TERM-0720"},{"term":"自运周期","answer":"是指相邻两日开始活动时间的间距即昼夜节律的一个周期，在永恒黑\n\n暗或永恒光照的条件下，生物仍能表现出这种活动的周期性。","chapterNo":36,"chapterTitle":"动物的行为","source":"term_doc","answerStatus":"reference","qid":"TERM-0721"},{"term":"潮汐节律","answer":"是指海洋生物与潮水涨退的变化相适应的节律行为，如招潮蟹、牡蛎、\n\n珊瑚。","chapterNo":36,"chapterTitle":"动物的行为","source":"term_doc","answerStatus":"reference","qid":"TERM-0722"},{"term":"季节节律","answer":"是指动物随季节改变而发生的周期性行为，如候鸟迁徙。","chapterNo":36,"chapterTitle":"动物的行为","source":"term_doc","answerStatus":"reference","qid":"TERM-0723"},{"term":"生态学","answer":"研究生物、人类和环境之间错综复杂关系的科学，叫做生态学。","chapterNo":37,"chapterTitle":"生物与环境","source":"term_doc","answerStatus":"reference","qid":"TERM-0724"},{"term":"环境","answer":"是指某一特定生物体以外的空间及直接、间接影响该生物体生存的一\n\n切事物的总和。)包括生物环境和非生物环境。非生物环境是指环境\n\n中非生物因子的总称，由物理、化学因子和其他非生命物质组成，如\n\n阳光、空气、水。","chapterNo":37,"chapterTitle":"生物与环境","source":"term_doc","answerStatus":"reference","qid":"TERM-0725"},{"term":"生态因子(2022 年名词解释）","answer":"是指环境中对生物的生长、发育、生殖、行为和分布有着直接影响的\n\n环境要素。生态因子的种类有：气候因子、土壤因子、地形因子、生\n\n物因子、人为因子。","chapterNo":37,"chapterTitle":"生物与环境","source":"term_doc","answerStatus":"reference","qid":"TERM-0726"},{"term":"限制因子","answer":"在生物生长发育所必须的多种生态因子中，若其中某一生态因子的量\n\n接近或超过生物的耐受性极限而限制着该生物的生长发育，这个生态\n\n因子就称为该生物生长的限制因子，限制因子是限制生物生存和繁殖\n\n的关键因子。","chapterNo":37,"chapterTitle":"生物与环境","source":"term_doc","answerStatus":"reference","qid":"TERM-0727"},{"term":"最小因子法则","answer":"李比希研究发现每一种植物都需要一定种类和一定数量的营养物，如\n\n果其中有一种营养物完全缺失，植物就不能生存。如果这种营养物少\n\n于一定的量而其他营养物又都充足的话，植物的生长发育就决定于这\n\n种营养物的数量。","chapterNo":37,"chapterTitle":"生物与环境","source":"term_doc","answerStatus":"reference","qid":"TERM-0728"},{"term":"耐受性法则","answer":"谢尔福德提出生物对每一种生态因子都有耐受的下限和上限，上、下\n\n限之间就是生物对这种生态因子的耐受范围。","chapterNo":37,"chapterTitle":"生物与环境","source":"term_doc","answerStatus":"reference","qid":"TERM-0729"},{"term":"选择性共生","answer":"选择性共生又称特异性共生，指生物有选择性地针对一种或几种生物\n\n的共生现象。)共生是指物种之间不能分开的一种互利关系，如果失\n\n去一方，另一方也就不能生存。如地衣是单细胞藻类和真菌的共生体，\n\n白蚁和多鞭毛虫的共生关系。","chapterNo":37,"chapterTitle":"生物与环境","source":"term_doc","answerStatus":"reference","qid":"TERM-0730"},{"term":"特征替代","answer":"是相似物种对种间竞争在进化上表现出的一种适应。若两个物种在其\n\n共同的分布区内发生分化，则可在重叠分布区内长期共存。但形态上\n\n的种间差异只有在两物种的重叠分布区内才存在，而在各自独占的分\n\n布区内则消失。例如，黄土蚁及其近缘种在它们共存的分布区内至少\n\n有 8 点形态上的差异，但在它们各自的独占的分布区内，这些形态上\n\n的差异变得模糊起来。","chapterNo":37,"chapterTitle":"生物与环境","source":"term_doc","answerStatus":"reference","qid":"TERM-0731"},{"term":"重寄生","answer":"是指寄生昆虫本身有时也会被其他寄生昆虫所寄生，形成了寄生链，\n\n这种现象称重寄生。例如，蚜虫←蚜小蜂←瘿蜂←金小蜂。","chapterNo":37,"chapterTitle":"生物与环境","source":"term_doc","answerStatus":"reference","qid":"TERM-0732"},{"term":"种群密度","answer":"是指单位面积上个体的数量。它随着季节、气候条件、食物储量和其\n\n他因素而发生变化。常采用标志重捕法调查动物种群密度。种群密度\n\n是种群最基本的数量特征。","chapterNo":38,"chapterTitle":"种群的结构、动态与数量调节","source":"term_doc","answerStatus":"reference","qid":"TERM-0733"},{"term":"年龄结构","answer":"是指不同年龄的个体在种群中占有比例的关系。动物的年龄分为生殖\n\n前期、生殖期和生殖后期 3 个年龄组。年龄结构有增长型、衰退型、\n\n稳定型 3 种类型。年龄结构预示着种群未来的增长趋势","chapterNo":38,"chapterTitle":"种群的结构、动态与数量调节","source":"term_doc","answerStatus":"reference","qid":"TERM-0734"},{"term":"逻辑斯蒂增长","answer":"是指种群在资源、空间有限和存在其他生物制约条件下的种群增长方\n\n式。(逻辑斯蒂增长曲线是 s 型。它在指数增长曲线的基础上引入了\n\n环境容纳量的概念。)","chapterNo":38,"chapterTitle":"种群的结构、动态与数量调节","source":"term_doc","answerStatus":"reference","qid":"TERM-0735"},{"term":"环境容纳量(真题）","answer":"是指由环境资源决定的种群数量，即某一环境在长期基础上所能维持\n\n的种群最大数量。","chapterNo":38,"chapterTitle":"种群的结构、动态与数量调节","source":"term_doc","answerStatus":"reference","qid":"TERM-0736"},{"term":"种群增长","answer":"种群增长有指数增长和逻辑斯蒂增长两种类型。指数增长是指种群在\n\n资源、空间无限和无其他生物制约条件下的种群增长方式。逻辑斯蒂\n\n增长是指种群在资源、空间有限和存在其他生物制约条件下的种群增\n\n长方式。(指数增长曲线是 J 型，逻辑斯蒂增长曲线是 s 型，它在指\n\n数增长曲线的基础上引入了环境容纳量的概念。)","chapterNo":38,"chapterTitle":"种群的结构、动态与数量调节","source":"term_doc","answerStatus":"reference","qid":"TERM-0737"},{"term":"种群数量的 S 型增长","answer":"又称逻辑斯蒂增长，是指种群在资源、空间有限和存在其他生物制约\n\n条件下的种群增长方式。曲线是 s 型，它在指数增长曲线的基础上引\n\n入了环境容纳量的概念。","chapterNo":38,"chapterTitle":"种群的结构、动态与数量调节","source":"term_doc","answerStatus":"reference","qid":"TERM-0738"},{"term":"标志重捕法","answer":"定义先捕获一部分个体进行标记,然后再将它们释放,过一定时间后\n\n再进行重捕，并记下重捕个体中已被标记的个体数。\n\n计算公式：N=M×n/m。N 表示种群总个体数,M 表示标志个体数,n 表\n\n示重捕个体数,m 表示重捕中被标记的个体数。\n\n应用条件：\n\n①标志个体释放后应与其他个体均匀混合；\n\n②标志方法不会伤害动物和影响动物的行为；\n\n③研究区域呈相对封闭状态,没有个体的迁入和迁出。","chapterNo":38,"chapterTitle":"种群的结构、动态与数量调节","source":"term_doc","answerStatus":"reference","qid":"TERM-0739"},{"term":"分布型","answer":"是指种群中个体的空间分布格局。其分布型包括集群分布、均匀分布\n\n和随机分布。","chapterNo":38,"chapterTitle":"种群的结构、动态与数量调节","source":"term_doc","answerStatus":"reference","qid":"TERM-0740"},{"term":"集群分布","answer":"种群中最常见的分布型。产生原因是动植物对生境差异发生反应的结\n\n果，同时受生殖方式和社会行为的影响。特点是种群中的个体集中分\n\n布在特定的几个位置上。例如放牧中的羊群、人类在地球表面的分布。","chapterNo":38,"chapterTitle":"种群的结构、动态与数量调节","source":"term_doc","answerStatus":"reference","qid":"TERM-0741"},{"term":"均匀分布","answer":"其产生原因是种群成员间进行种内竞争所引起的，特点是种群中的个\n\n体等距分布。例如森林树木、沙漠植株的分布。","chapterNo":38,"chapterTitle":"种群的结构、动态与数量调节","source":"term_doc","answerStatus":"reference","qid":"TERM-0742"},{"term":"随机分布","answer":"产生原因是生长环境条件均一，种群成员间既不互相吸引也不互相排\n\n斥。特点是种群内的每个个体在任意空间的分布概率相等。例如森林\n\n底层某些无脊椎动物和狼蛛的分布。","chapterNo":38,"chapterTitle":"种群的结构、动态与数量调节","source":"term_doc","answerStatus":"reference","qid":"TERM-0743"},{"term":"指数增长‘","answer":"有些生物在食物和空间无限、没有敌害的条件下可以连续进行生殖，\n\n且没有特定的生殖期，种群数量呈指数增长。\n\n其计算公式是 dN/dT=(b-a)N。其中，dN/dT 表示种群的瞬时增长量，\n\nb 和 a 分别代表个体的瞬时出生率和死亡率，N 代表种群大小。令\n\nr=b-a(表示种群的瞬时增长率)，因此种群的瞬时增长率就是：\n\ndN/dT=rN。特点是增长不受资源、空间和其他生物制约；虽然开始增\n\n长很慢，但随着种群基数的加大，增长会越来越快；增长曲线呈现“J”\n\n型。","chapterNo":38,"chapterTitle":"种群的结构、动态与数量调节","source":"term_doc","answerStatus":"reference","qid":"TERM-0744"},{"term":"r 对策","answer":"r 对策：主要目标是提高生育力。\n\n①r 对策生物通常是个体小、寿命短、生殖力强但存活率低，亲代对\n\n后代缺乏保护；\n\n②r 对策生物有较强的迁移和散布能力，其发展常常要靠机会;\n\n③种群的死亡率：主要是由环境变化引起的，而与种群密度无关；\n\n④r 对策的物种：主要是无脊椎动物和昆虫，也包括小型的哺乳动物\n\n和鸟类如鼠类和麻雀，一年生植物;\n\n⑤动态曲线:：r 对策物种只有一个稳定平衡点而没有灭绝点，它们\n\n的种群在密度极低时也能迅速回升到稳定平衡点 S，并在 S 点上下波\n\n动，故不易灭绝。这就是很多有害生物，人们想消灭又消灭不了的原\n\n因。","chapterNo":38,"chapterTitle":"种群的结构、动态与数量调节","source":"term_doc","answerStatus":"reference","qid":"TERM-0745"},{"term":"k 对策","answer":"k 对策：主要目标是提高竞争力。\n\n1k 对策生物通常是个体大、寿命长、生殖力弱但存活率高，亲代对\n\n后代保护很好。\n\n2k 对策生物迁移和散布能力较弱，但对生境有极好的适应能力，种\n\n群数量通常能稳定在环境容纳量的水平上或有微小波动。\n\n③种群死亡率：主要是由密度制约因素引起的，而不是由环境条件变\n\n化引起的。\n\n④k 对策的物种：大型的鸟兽和林木，也包括少数较大昆虫如大型的\n\n蝴蝶和天牛。\n\n⑤动态曲线：k 对策物种的种群动态曲线有 2 个平衡点：一个是稳定\n\n平衡点 S，一个是不稳定平衡点 X(又称灭绝点)，种群数量一旦低于\n\nX 就必然会走向灭绝。这就是很多珍稀濒危物种，人们想保护又保护\n\n不住的原因。","chapterNo":38,"chapterTitle":"种群的结构、动态与数量调节","source":"term_doc","answerStatus":"reference","qid":"TERM-0746"},{"term":"周期波动","answer":"少数物种的数量波动是有规则的，严格说来任何波动只要在两个波峰\n\n之间相隔的时间相等，就可称为周期波动，如猞猁和雪兔，每隔 9~10\n\n年出现一次数量高峰。","chapterNo":38,"chapterTitle":"种群的结构、动态与数量调节","source":"term_doc","answerStatus":"reference","qid":"TERM-0747"},{"term":"密度制约因子","answer":"相当于生物因子，如捕食、寄生、流行病和食物等。其特点是作用强\n\n度随种群密度的加大而增强，种群受影响个体的百分比也与种群密度\n\n的大小有关。","chapterNo":38,"chapterTitle":"种群的结构、动态与数量调节","source":"term_doc","answerStatus":"reference","qid":"TERM-0748"},{"term":"非密度制约因子","answer":"相当于气候等非生物因子。对种群的影响不受种群密度本身的制约，\n\n在任何密度下，种群总是有一固定的百分数受到影响或被杀死，因此\n\n对种群密度无法起调节作用。","chapterNo":38,"chapterTitle":"种群的结构、动态与数量调节","source":"term_doc","answerStatus":"reference","qid":"TERM-0749"},{"term":"群落","answer":"是占有一定空间和时间的多种生物种群的集合体，是由很多种类的生\n\n物种群所组成的一个生态功能单位。(群落的性质是由组成群落的各\n\n种生物的适应性以及这些生物彼此之间的相互关系所决定的。)","chapterNo":39,"chapterTitle":"群落的结构、类型及演替","source":"term_doc","answerStatus":"reference","qid":"TERM-0750"},{"term":"生态位（2016、2021 名词解释）","answer":"是指物种利用群落中各种资源的总和以及该物种与群落中其他物种\n\n相互关系的总和。它表示物种在群落中的地位、作用和重要性。","chapterNo":39,"chapterTitle":"群落的结构、类型及演替","source":"term_doc","answerStatus":"reference","qid":"TERM-0751"},{"term":"基本生态位","answer":"是指一个物种按其生理上的需求及所需的资源，可能占领的全部生态\n\n位。","chapterNo":39,"chapterTitle":"群落的结构、类型及演替","source":"term_doc","answerStatus":"reference","qid":"TERM-0752"},{"term":"实际生态位","answer":"是指由于物种的相互作用(主要是种间竞争),一个物种实际上所占领\n\n的生态位。","chapterNo":39,"chapterTitle":"群落的结构、类型及演替","source":"term_doc","answerStatus":"reference","qid":"TERM-0753"},{"term":"竞争排斥原理","answer":"当两个物种利用同一资源时，就会发生生态位重叠，当两个生态位完\n\n全相同的物种竞争有限资源时，竞争优势大的物种就会把另一物种完\n\n全排除掉，因此在同一群落中不可能有两个物种的生态位是完全相同\n\n的。这就是竞争排斥原理。","chapterNo":39,"chapterTitle":"群落的结构、类型及演替","source":"term_doc","answerStatus":"reference","qid":"TERM-0754"},{"term":"生态演替","answer":"是指在一定区域内，群落随时间而发生变化，由一种类型转变为另一\n\n种类型的生态过程，又称群落演替。它可以分为原生演替和次生演替。","chapterNo":39,"chapterTitle":"群落的结构、类型及演替","source":"term_doc","answerStatus":"reference","qid":"TERM-0755"},{"term":"原生演替","answer":"群落在从没有长过任何植物的裸岩、沙丘和湖底等地方进行的演替。","chapterNo":39,"chapterTitle":"群落的结构、类型及演替","source":"term_doc","answerStatus":"reference","qid":"TERM-0756"},{"term":"次生演替","answer":"由于火灾、洪水泛滥和人为破坏把原生群落毁灭，在被毁灭的群落的\n\n基质上所进行的演替。","chapterNo":39,"chapterTitle":"群落的结构、类型及演替","source":"term_doc","answerStatus":"reference","qid":"TERM-0757"},{"term":"顶级群落","answer":"在不受外来因素的干扰下，通过演替发展成为与当地环境条件相适应\n\n的、结构稳定的群落。\n\n它已经演替到了最终平衡状态，只要不受外力干扰，将永远保持原状。","chapterNo":39,"chapterTitle":"群落的结构、类型及演替","source":"term_doc","answerStatus":"reference","qid":"TERM-0758"},{"term":"群落的垂直结构","answer":"即群落的层次性，主要是由植物的生长型决定的。生长型是指植物的\n\n外貌特征，主要生长型有苔藓、草木、灌木和乔木，它们自下而上配\n\n置在群落的不同高度上，形成群落的垂直结构。以森林群落为例，其\n\n垂直结构从上到下为林冠层、下木层、灌木层、草本层和地表层。","chapterNo":39,"chapterTitle":"群落的结构、类型及演替","source":"term_doc","answerStatus":"reference","qid":"TERM-0759"},{"term":"群落的水平结构","answer":"指生物群落在水平方向上，由于地形的起伏，光照的阴暗，温度的大\n\n小等因素的影响，在不同地段上有不同的分布。以森林的水平结构为\n\n例，在乔木的和被其他树冠遮盖的位置，光线往往较暗，适合苔藓植\n\n物等喜阴植物的生存；在树冠下的间隙等光照较为充足的地段，则有\n\n较多的灌木与草丛。","chapterNo":39,"chapterTitle":"群落的结构、类型及演替","source":"term_doc","answerStatus":"reference","qid":"TERM-0760"},{"term":"群落的物种多样性","answer":"受两个指标影响：物种丰富度、相对多度。\n\n物种丰富度：群落所包含的不同物种的数量\n\n相对多度：每个物种在群落中所占的比例\n\n香农-维纳多样性指数：对群落的物种多样性进行定量的评估","chapterNo":39,"chapterTitle":"群落的结构、类型及演替","source":"term_doc","answerStatus":"reference","qid":"TERM-0761"},{"term":"优势种","answer":"是最丰富或总生物量最高的物种，例如寒带针叶林生物群落中的优势\n\n种通常是云杉或冷杉。优势种在利用有限的资源方面具有竞争优势，\n\n可能在避免被取食或疫病影响方面更成功。","chapterNo":39,"chapterTitle":"群落的结构、类型及演替","source":"term_doc","answerStatus":"reference","qid":"TERM-0762"},{"term":"关键种","answer":"对群落结构的控制不是通过数量的力量，而是通过其关键的生态作用。\n\n例如，加利福尼亚贻贝数量众多，是优势种，其捕食者海星数量较低。\n\n海星为关键种，尽管数量水平低，但是对于群落的物种多样性组成和\n\n结构有重要影响。","chapterNo":39,"chapterTitle":"群落的结构、类型及演替","source":"term_doc","answerStatus":"reference","qid":"TERM-0763"},{"term":"生态系统（2015、2016、2019 年名词解释）","answer":"是指在一定的空间内，生物成分和非生物成分通过物质循环和能量流\n\n动而相互作用、互相依存而构成的一个生态学功能单位。(任何生态\n\n系统都是由非生物成分(无机物、有机物、气候、能源)和生物成分(生\n\n产者、消费者、分解者)组成的，生态系统的两大重要功能是物质循\n\n环和能量流动。)","chapterNo":40,"chapterTitle":"生态系统及其功能","source":"term_doc","answerStatus":"reference","qid":"TERM-0764"},{"term":"生产者","answer":"指生态系统中的自养型生物(包括绿色植物、非绿色植物和自养型微\n\n生物)。它们借助于光合作用生产有机物，并把太阳能转化为化学能\n\n储存在合成的有机物中。","chapterNo":40,"chapterTitle":"生态系统及其功能","source":"term_doc","answerStatus":"reference","qid":"TERM-0765"},{"term":"消费者","answer":"指只能利用现存的有机物的动物。包括以动、植物为食的动物，也包\n\n括杂食动物和寄生动物。","chapterNo":40,"chapterTitle":"生态系统及其功能","source":"term_doc","answerStatus":"reference","qid":"TERM-0766"},{"term":"分解者","answer":"主要是指细菌、真菌等营腐生生活的微生物，它们能把动植物的尸体、\n\n排泄物和残落物等所含有的有机物，分解成简单的无机物，归还到无\n\n机环境中，再重新被绿色植物利用来制造有机物。","chapterNo":40,"chapterTitle":"生态系统及其功能","source":"term_doc","answerStatus":"reference","qid":"TERM-0767"},{"term":"食物链","answer":"是指由生产者固定的能量，通过一系列的取食和被取食的关系，在生\n\n态系统中传递的单方向的营养关系。(有两种类型：捕食食物链和腐\n\n食食物链。捕食食物链是以活的生物为起点的食物链，主要存在于海\n\n洋生态系统中，腐食食物链是以死亡的动植物或腐败的有机物为起点\n\n的食物链，主要存在陆地和浅水生态系统中。)","chapterNo":40,"chapterTitle":"生态系统及其功能","source":"term_doc","answerStatus":"reference","qid":"TERM-0768"},{"term":"食物网","answer":"在一个生态系统中，许多食物链彼此相互交错连接的复杂营养关系，\n\n叫做食物网。食物网越复杂，生态系统就越稳定，食物网越简单，生\n\n态系统就越容易发生波动和毁灭。","chapterNo":40,"chapterTitle":"生态系统及其功能","source":"term_doc","answerStatus":"reference","qid":"TERM-0769"},{"term":"营养级","answer":"处于食物链某环节上的全部生物种的总和。(特点有：①营养级的数\n\n目是有限的，一般是 4~5 个；②营养级的位置越高，归属于这个营养\n\n级的生物种类和数量就越少。)","chapterNo":40,"chapterTitle":"生态系统及其功能","source":"term_doc","answerStatus":"reference","qid":"TERM-0770"},{"term":"初级生产量","answer":"又称第一性生产量，是指绿色植物经光合作用生产的有机物质数量。\n\n净初级生产量等于总初级生产量减去植物呼吸消耗量。只有净初级生\n\n产量才有可能被人或其他动物所利用。","chapterNo":40,"chapterTitle":"生态系统及其功能","source":"term_doc","answerStatus":"reference","qid":"TERM-0771"},{"term":"次级生产量","answer":"又称第二性生产量，是指动物靠吃植物、其他动物和一切现成的有机\n\n物质而生产出来的有机物数量。包括动物的肉、蛋、奶、毛皮、血液、\n\n内脏器官等。","chapterNo":40,"chapterTitle":"生态系统及其功能","source":"term_doc","answerStatus":"reference","qid":"TERM-0772"},{"term":"生物量","answer":"生态系统内营养级中有机体的总重量，以生物的干重表示。(生物量\n\n的单位通常是用 g/m²或 J/m²表示。)","chapterNo":40,"chapterTitle":"生态系统及其功能","source":"term_doc","answerStatus":"reference","qid":"TERM-0773"},{"term":"物质循环","answer":"指组成生物体的基本元素，不断的进行着从无机环境到生物群落，又\n\n从生物群落到无机环境的循环过程。生态系统的物质循环又称生物地\n\n球化学循环，简称生物地化循环，可分为三种基本类型，即水循环、\n\n气体型循环和沉积型循环。","chapterNo":40,"chapterTitle":"生态系统及其功能","source":"term_doc","answerStatus":"reference","qid":"TERM-0774"},{"term":"碳的循环","answer":"碳以二氧化碳形式从无机环境进人生物群落，以有机物形式在生物群\n\n落的各成分之间传递，最终又以二氧化碳的形式回到无机环境的过程。\n\n碳循环始终与能量流动结合在一起。","chapterNo":40,"chapterTitle":"生态系统及其功能","source":"term_doc","answerStatus":"reference","qid":"TERM-0775"},{"term":"能量流动","answer":"指生态系统中能量的输人、传递和散失的过程(能量流动的起点、总\n\n能量和流动渠道)。能量流动是单方向的和不可逆的，并且在流动过\n\n程中急剧减少，主要是因为资源利用率不高和呼吸消耗。","chapterNo":40,"chapterTitle":"生态系统及其功能","source":"term_doc","answerStatus":"reference","qid":"TERM-0776"},{"term":"系统的能量流","answer":"能量只是一次穿过生态系统，不能再次被生产者利用而进行循环。这\n\n一通过生态系统的能量单向流动的现象叫做能量流。","chapterNo":40,"chapterTitle":"生态系统及其功能","source":"term_doc","answerStatus":"reference","qid":"TERM-0777"},{"term":"生态效率","answer":"是指食物链各环节上的能量的转化效率，约为 10%。(在每一步传递\n\n过程中，能量都有大量的损耗，每一级的生物都只能利用所食用的前\n\n一级生物提供的能量的一部分。)","chapterNo":40,"chapterTitle":"生态系统及其功能","source":"term_doc","answerStatus":"reference","qid":"TERM-0778"},{"term":"生态平衡","answer":"生态系统发展到一定阶段，它的生产者、消费者和分解者之间能够较\n\n长时间地保持着一种动态的平衡(它的物质循环和能量流动能够较长\n\n时间的保持动态平衡),在外来干扰下，通过自然调节能恢复原初的稳\n\n定状态。生态系统的这种动态平衡的状态，称为生态平衡。","chapterNo":40,"chapterTitle":"生态系统及其功能","source":"term_doc","answerStatus":"reference","qid":"TERM-0779"},{"term":"腐食性营养","answer":"指生物以死亡的动植物或腐败的有机物为食料而得到营养的习性。)\n\n如细菌以死的动植物为食并把它们分解，蜥蜴、虾蟹类、家蝇、蜗牛\n\n等喜好以动物的尸体为食，都是属于腐食性营养。","chapterNo":40,"chapterTitle":"生态系统及其功能","source":"term_doc","answerStatus":"reference","qid":"TERM-0780"},{"term":"捕食食物链","answer":"食物链根据起点不同可分为两种类型。其中捕食食物链是以活的生物\n\n为起点的食物链，主要存在于海洋生态系统中以捕食食物链为主。例\n\n如，草→蝗虫→小鸟→蛇→鹰。","chapterNo":40,"chapterTitle":"生态系统及其功能","source":"term_doc","answerStatus":"reference","qid":"TERM-0781"},{"term":"腐食食物链","answer":"食物链根据起点不同可分为两种类型。其中腐食食物链是以死亡的动\n\n植物或腐败有机物为起点的食物链，主要在多数陆地和浅水生态系统\n\n中以腐食食物链为主。例如，植物的残枝败叶→蚯蚓→线虫→节肢动\n\n物。","chapterNo":40,"chapterTitle":"生态系统及其功能","source":"term_doc","answerStatus":"reference","qid":"TERM-0782"},{"term":"数量金字塔","answer":"数量金字塔是三种生态金字塔之一。其定义是以食物链不同环节上生\n\n物的数量作为营养级之间的数量关系。特点:一般是呈上宽下窄的正\n\n椎体，部分情况下可以呈现出倒椎形。","chapterNo":40,"chapterTitle":"生态系统及其功能","source":"term_doc","answerStatus":"reference","qid":"TERM-0783"},{"term":"生物量金字塔","answer":"生物量金字塔是三种生态金字塔之一。其定义是以生物的干重表示营\n\n养级中生物的总重量(即生物量)。特点:通常是上窄下宽的正椎体，\n\n在海洋生态系统中常常表现为一个倒椎体生物量金字塔。","chapterNo":40,"chapterTitle":"生态系统及其功能","source":"term_doc","answerStatus":"reference","qid":"TERM-0784"},{"term":"能量金字塔","answer":"能量金字塔是三种生态金字塔之一。其定义是由各营养级所固定的总\n\n能量多少构成。特点总是呈正椎体图形，而绝不会出现倒椎体。","chapterNo":40,"chapterTitle":"生态系统及其功能","source":"term_doc","answerStatus":"reference","qid":"TERM-0785"},{"term":"气体型循环","answer":"是物质循环中的一种。主要储存库是大气和海洋，其循环具有明显的\n\n全球性，循环性能最为完善，循环速度比较快，属于气体型循环的物\n\n质有氧、二氧化碳、氮、氯、溴和氟等。","chapterNo":40,"chapterTitle":"生态系统及其功能","source":"term_doc","answerStatus":"reference","qid":"TERM-0786"},{"term":"沉积型循环","answer":"是物质循环中的一种。特点是主要储存是土壤、沉积岩和岩石圈。循\n\n环的全球性不明显，循环性能不完善，循环速度缓慢，属于沉积型循\n\n环的物质主要有磷、钙、钾、钠、镁、铁、锰、碘、铜和硅等。","chapterNo":40,"chapterTitle":"生态系统及其功能","source":"term_doc","answerStatus":"reference","qid":"TERM-0787"},{"term":"生物多样性（14、15、17、18、19、20 年名词解释）","answer":"指生命有机体的种类和变异性及其与环境形成的生态复合体以及与\n\n此相关的各种生态过程的总和，包括动物、植物、微生物和它们所拥\n\n有的基因以及它们与其生存环境形成的复杂的生态系统和自然景观。\n\n包含有遗传多样性、物种多样性、生态系统的多样性 3 个层次。","chapterNo":41,"chapterTitle":"生物多样性及保护生物学","source":"term_doc","answerStatus":"reference","qid":"TERM-0788"},{"term":"保护生物学","answer":"是寻求制止生物多样性下降办法的一门科学，保护生物学的前沿是在\n\n生物多样性危机比较大的那些地理区域。","chapterNo":41,"chapterTitle":"生物多样性及保护生物学","source":"term_doc","answerStatus":"reference","qid":"TERM-0789"},{"term":"最小存活种群","answer":"确保一个物种长期存活所必需的个体数量。(最小存活种群必须有足\n\n够的个体数量，以便应付个体出生和死亡的偶然变化、遗传漂变、一\n\n系列的环境随机改变和各种灾难性事件。一般来说，保持种群长期存\n\n活所需要的最低个体数量约为 1000 个或更多一些。)","chapterNo":41,"chapterTitle":"生物多样性及保护生物学","source":"term_doc","answerStatus":"reference","qid":"TERM-0790"},{"term":"就地保护","answer":"为了保护生物多样性，在原来生境中对濒危动植物进行保护。由于自\n\n然选择的择优汰劣作用，能保持野生状态下物种的活力，因此就地保\n\n护是将物种作为生物圈中的一个有生存力的物种进行保护，是最有效\n\n的保护。就地保护的主要形式是建立自然保护区。","chapterNo":41,"chapterTitle":"生物多样性及保护生物学","source":"term_doc","answerStatus":"reference","qid":"TERM-0791"},{"term":"自然保护区","answer":"为了保护自然和自然资源，特别是保护珍稀动植物，保护代表不同自\n\n然地带的自然环境和生态系统，国家划出一定的区域加以保护，这些\n\n区域叫做自然保护区。","chapterNo":41,"chapterTitle":"生物多样性及保护生物学","source":"term_doc","answerStatus":"reference","qid":"TERM-0792"},{"term":"迁地保护","answer":"为了保护生物多样性，将濒危动植物迁移到人工环境中或易地实施保\n\n护。迁地保护是就地保护的补充，当物种丧失在野生状态下的生存能\n\n力，在野生状态下即将灭绝时，迁地保护为他们提供了最后的生存机\n\n会。","chapterNo":41,"chapterTitle":"生物多样性及保护生物学","source":"term_doc","answerStatus":"reference","qid":"TERM-0793"},{"term":"水体富营养化","answer":"指由于水体中氮、磷等植物必需的矿质元素含量过多，导致藻类植物\n\n等大量繁殖，并引起水质恶化和水生动物死亡的现象。","chapterNo":41,"chapterTitle":"生物多样性及保护生物学","source":"term_doc","answerStatus":"reference","qid":"TERM-0794"},{"term":"生物富集作用","answer":"指环境中的一些污染物(如重金属、化学农药),通过食物链在生物体\n\n内大量积聚的过程。","chapterNo":41,"chapterTitle":"生物多样性及保护生物学","source":"term_doc","answerStatus":"reference","qid":"TERM-0795"},{"term":"生物净化","answer":"指生物体通过吸收、分解和转化作用，使生态环境中的污染物的浓度\n\n和毒性降低或消失的过程。生物净化过程中，绿色植物和微生物起重\n\n要作用。","chapterNo":41,"chapterTitle":"生物多样性及保护生物学","source":"term_doc","answerStatus":"reference","qid":"TERM-0796"},{"term":"遗传多样性","answer":"遗传多样性是指地球上生物所携带的各种遗传信息的总和，包括种群\n\n内部个体的变异和种群之间的遗传变异，这种变异通常与适应地方条\n\n件相联系。\n\n遗传多样性的意义:\n\na.遗传多样性通常可促进微进化的发生:\n\nb.整个物种遗传多样性的下降将会降低该物种的适应潜力，并可加速\n\n正在逐渐变小的种群走向灭绝。","chapterNo":41,"chapterTitle":"生物多样性及保护生物学","source":"term_doc","answerStatus":"reference","qid":"TERM-0797"},{"term":"物种多样性","answer":"地球上动植物、微生物等生物种类的丰富程度，是物种水平的生物多\n\n样性，地球上的大多数物种都有地方性分布的特点。","chapterNo":41,"chapterTitle":"生物多样性及保护生物学","source":"term_doc","answerStatus":"reference","qid":"TERM-0798"},{"term":"生态系统多样性","answer":"生态系统多样性是指生物圈内生态环境、生物群落和生态过程的多样\n\n化以及生态系统内生态环境、生物群落和生态过程变化的多样性。每\n\n个生态系统都有独一无二的生物群落，都有自身的能量流动和物质循\n\n环格局。","chapterNo":41,"chapterTitle":"生物多样性及保护生物学","source":"term_doc","answerStatus":"reference","qid":"TERM-0799"},{"term":"濒危物种","answer":"量化分类法是指 IUCN 为了确认稀有和濒危物种所处的状况而提出分\n\n类法，这个分类法是依据物种的灭绝概率而提出的。其中濒危物种是\n\n指 20 年之间或 5 个世代之内物种灭绝的概率为 20%。","chapterNo":41,"chapterTitle":"生物多样性及保护生物学","source":"term_doc","answerStatus":"reference","qid":"TERM-0800"},{"term":"生物多样性热点","answer":"生物多样性热点是指在一个相对较小的区域内有特别多的物种存在，\n\n生物多样性热点也是生物灭绝的热点。","chapterNo":41,"chapterTitle":"生物多样性及保护生物学","source":"term_doc","answerStatus":"reference","qid":"TERM-0801"},{"term":"生物多样性热点区域","answer":"一个含有 1500 种以上本地植物物种的区域(占全球植物总数的 0.5%)\n\n才能被评为生物多样性热点区域，生物多样性热点区域是最需要全球\n\n努力做出强有力保护的地区。","chapterNo":41,"chapterTitle":"生物多样性及保护生物学","source":"term_doc","answerStatus":"reference","qid":"TERM-0802"}]};
